WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[44338] = { title = "Goddess Watch Over You", description = "I may have found a \"key\" to unlock Light's Heart, {name}.\n\nI was going through some ancient cosmology tomes when I stumbled upon a passage indicating that the prime naaru may have been created by Elune during the great ordering of Light and Shadow.\n\nIf Elune did create Xe'ra, then it stands to reason that we could use the Tears of Elune to unlock the secrets of Light's Heart.\n\nNow it falls upon you to recover the Tears of Elune from Val'sharah.", objectives = "" }
WordHunterWoW_QuestEN[44366] = { title = "One Last Adventure", description = "There is still one last path you may yet walk - one more weapon you might wield.\n\nIf you wish to seek it out, just say the word.", objectives = "" }
WordHunterWoW_QuestEN[44370] = { title = "Completing Your Arsenal", description = "Highlord, there is still one last weapon out there that would aid you against the Legion.\n\nIf you would like, I would be happy to go over our latest information on its whereabouts.", objectives = "" }
WordHunterWoW_QuestEN[44375] = { title = "The Final Blade", description = "As I'm sure you recall, we have retained our final set of plans to obtain a weapon of immense power.\n\nNo pressure, of course, but if you wish to pursue it just let me know.", objectives = "" }
WordHunterWoW_QuestEN[44379] = { title = "In Pursuit of Power", description = "There is one more pair of blades still within reach that would aid you against the Legion.\n\nIf you wish to pursue them, just let me know.", objectives = "" }
WordHunterWoW_QuestEN[44383] = { title = "In Pursuit of Power", description = "There is still one other pair of blades that could be of great use to you in the battles to come.\n\nI can brief you on what we know if you would like to pursue them.", objectives = "" }
WordHunterWoW_QuestEN[44400] = { title = "Assault on Violet Hold: Purple Pain", description = "Again! It happened again!\n\nSure, it's the Legion that staged the prison breakout this time, but I *told* them it was a bad idea to keep some of the most dangerous beings on Azeroth in a prison inside our city!\n\nWe can talk about relocating later, I suppose. Right now, we've got some... pacification to tend to.\n\nCan you help?", objectives = "" }
WordHunterWoW_QuestEN[44401] = { title = "A Weapon For Every Occasion", description = "Our ally, the Lich King, has offered to provide you with a lead on a final weapon should you desire to maximize our offensive options.\n\nLet me know how you would like to proceed.", objectives = "" }
WordHunterWoW_QuestEN[44406] = { title = "Aggra's Guidance", description = "{class}t, have you met the shaman Aggra? Born of a shattered world, she learned the ways of the elements among the Mag'har orcs of Outland. On the eve of the Cataclysm she took it upon herself to complete Thrall's shamanistic training. Our younger initiates are fortunate to have her among us to guide them.\n\nIf you wish to seek out a second artifact, Aggra can assist you. She is training new recruits above us on the Storm's Eye Overlook.", objectives = "" }
WordHunterWoW_QuestEN[44407] = { title = "The Third Legend", description = "You have not one but TWO powerful artifacts to use against the Legion. But can you imagine a world where you have three? Think of what you could do in such a world!\n\nShall we look at the possibilities?", objectives = "" }
WordHunterWoW_QuestEN[44411] = { title = "Strange Humming Crystal", description = "<You place the crystal to your ear and hear the disharmonious din of hundreds of voices speaking at once. Perhaps Khadgar might know more about this strange gem.>", objectives = "" }
WordHunterWoW_QuestEN[44412] = { title = "Enemies Everywhere", description = "Hold a moment, {name}. While I look into this orb of yours, why don't you look into something for me?\n\nI have long suspected an infiltration of Dalaran but after an embarrassing encounter with a local florist I've withheld my accusations until I'm absolutely certain.\n\nHave you noticed citizens among us that seem just too mundane? Almost inhumanly so? Spies, serving dark masters, watch and wait until our backs are turned. Root them out, but try and keep it quiet.", objectives = "" }
WordHunterWoW_QuestEN[44414] = { title = "Felspawns of Lothros", description = "These Felspawns are endless! I can't cut them down quickly enough to get to the dreadlord within the mausoleum.\n\nMaster Illidan, will you come with me so we can take down Lothros together?", objectives = "" }
WordHunterWoW_QuestEN[44415] = { title = "The Red Axe", description = "Broxigar the Red is cornered on the bridge. I am not sure he would ever admit that he needs our help, but I feel it only proper to lend him our aid.\n\nIf you wish to assist our ally, I would be humbled to accompany you in this endeavor.", objectives = "" }
WordHunterWoW_QuestEN[44416] = { title = "Hunter of Night", description = "A glorious battle indeed!\n\nIf I am correct, we can expect something a bit more deadly at any moment.\n\nThe Legion often uses fodder such as these to prepare the way for a more worthy foe.\n\nMy axe is sharp and ready.", objectives = "" }
WordHunterWoW_QuestEN[44417] = { title = "One More Legend", description = "Two is good, but three would be better. You should pursue another artifact to add to your armory.\n\nWhat say you?", objectives = "" }
WordHunterWoW_QuestEN[44421] = { title = "Anomalous Anomalies", description = "Dalaran's move to this location was intended to be a temporary measure, but we may need to depart sooner than expected.\n\nBlinking a city across the world is no mean feat. The magnitude of energies involved can lead to... unexpected side effects.\n\nArcane anomalies are causing mischief throughout the city. Their presence could destabilize any attempt to blink again.\n\nWe don't have time to let them dissipate on their own, {name}. I have a device that will help speed things along.", objectives = "" }
WordHunterWoW_QuestEN[44424] = { title = "Three Paths, Three Weapons", description = "We've searched and found a lead upon another artifact that you might find helpful.\n\nHere, let me show you what I've found. If it interests you then simply let me know.", objectives = "" }
WordHunterWoW_QuestEN[44431] = { title = "More Weapons of Old", description = "You've had great success against our foes, but you should be ready for any challenge they send your way.\n\nYou would be wise to consider obtaining yet another of the weapons of old to aid in our conflict.\n\nLet me know how you'd like to proceed.", objectives = "" }
WordHunterWoW_QuestEN[44443] = { title = "Weapons of the Ancients", description = "You've proven yourself to be a druid without equal, but if we are to succeed in our battles against the Burning Legion you need you to take advantage of every opportunity to stay ahead of our foes.\n\nYou should consider obtaining one final weapon of the Ancients. Its powers will maximize your ability to adapt to whatever the Legion can throw our way.\n\nLet me know how you'd like to proceed.", objectives = "" }
WordHunterWoW_QuestEN[44448] = { title = "In the House of Light and Shadow", description = "The Tears of Elune are ready for you, {name}. I am uncertain what to do from here. Take the relic back to your order hall and try to use it on Light's Heart.\n\nMaybe make them touch? Honestly your guess is as good as mine.\n\nLet's hope this works!", objectives = "" }
WordHunterWoW_QuestEN[44449] = { title = "Advanced Quenching", description = "Now that we have a frost mage at our disposal, testing this method out should be a cinch.\n\nHere are the plans for what I'd like you to make. Get to work and give me the armguards when you're finished.", objectives = "" }
WordHunterWoW_QuestEN[44457] = { title = "Brotherly Love", description = "Maiev will be somewhere in the prison. I found her discarded armor on my way here.\n\nI know the two of you have a history. I trust that will not be a problem.\n\nLet's split up to search the cells more quickly. We must find her.", objectives = "" }
WordHunterWoW_QuestEN[44463] = { title = "Demons Among Them", description = "It is just as we suspected, {name}! The demons thought they could take us by surprise.\n\nQuickly, to arms! Warn the King!", objectives = "" }
WordHunterWoW_QuestEN[44464] = { title = "Awakenings", description = "Light's Heart is to serve as the vessel for Illidan Stormrage's rebirth: my last act of service to the Light.\n\nBut Illidan is dead and his soul is lost in the Nether. Before we may attempt to recover his soul, we must prepare the vessel for his return.\n\nAcross two worlds exist echoes of Illidan's past. You must venture out and find the echoes.\n\nStart where all life begins, {name}: birth. Find Illidan's birthplace in Val'sharah. Awaken the memory.", objectives = "" }
WordHunterWoW_QuestEN[44465] = { title = "Recruiting Earthcallers", description = "Felinda Frye has recently joined us at the Heart of Azeroth. She oversees the recruitment and training of our Earthcallers.\n\nI recommend that you speak with her at your soonest convenience, Farseer {name}. The Earthcallers are powerful shaman and will greatly bolster our ranks.", objectives = "" }
WordHunterWoW_QuestEN[44466] = { title = "An Unclear Path", description = "Much of Illidan's formative years were spent in Val'sharah, alongside his twin brother, Malfurion.\n\nAs young night elves, the twins vied for the affection of the young priestess, Tyrande, as they underwent the trials of the demi-god, Cenarius.\n\nWe must travel to the Dreamgrove now, where Illidan's true path would be forged.", objectives = "" }
WordHunterWoW_QuestEN[44471] = { title = "Second Sight", description = "Though young King Anduin is a noble soul, he may lack the conviction of his father. The Alliance needs a leader who will do what needs to be done. The Legion will strike at the first hint of weakness.\n\nEven now, I sense something amiss, {name}. I fear that not all is as it seems.\n\nQuickly, use your Spectral Sight. We must know if there are foes among us!", objectives = "" }
WordHunterWoW_QuestEN[44473] = { title = "A Weapon of the Alliance", description = "At first I was unsure whether it was wise to allow the Illidari inside the city. But you may have just saved all our lives.\n\nYou may establish a camp in the Mage Quarter. The Alliance will have need of your skills if we are to face the Legion.\n\nMake no mistake though. Should your kind give in to the fel energies you toy with, we will treat you like the demons you are becoming.", objectives = "" }
WordHunterWoW_QuestEN[44479] = { title = "Ravencrest's Legacy", description = "Years later, as the War of the Ancients raged on and the Burning Legion's grip upon this world took hold, Illidan would meet a military leader known as Kur'talos Ravencrest. He too would see the potential within Illidan, eventually promoting him to captain of the Moon Guard: a powerful group of night elf sorcerers.\n\nWe must experience this memory in Black Rook Hold, located on the western shores of Val'sharah.", objectives = "" }
WordHunterWoW_QuestEN[44480] = { title = "In My Father's House", description = "Most mortals cannot comprehend the truth of the Legion. Those that recognize it, often refuse to accept its meaning. Such knowledge carries a weight that the mortal frame cannot bear. To sacrifice that much of ones self changes the soul.\n\nAmong your greatest heroes, a rare few understood that type of sacrifice. Let us witness it through Illidan's eyes.\n\nWe must go to Azshara, on the continent of Kalimdor.", objectives = "" }
WordHunterWoW_QuestEN[44481] = { title = "Destiny Unfulfilled", description = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.\n\nYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.\n\nWe must travel to Outland to experience Illidan's last memory.", objectives = "" }
WordHunterWoW_QuestEN[44482] = { title = "Recruiting Ebon Knights", description = "Korgaz Deadaxe has been hard at work training a new generation of death knights.\n\nHe has done an excellent job culling the ranks of weakness. Those who have survived the trials of death knight training are ready to join the ranks of the Ebon Blade.\n\nKorgaz is waiting for you on the upper level. I suggest you speak with him at your soonest convenience.\n\nNew death knights will bolster our ranks and aid is in the war against the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[44486] = { title = "Fel-Ravaged Tome", description = "Much of the elven writing in the tome has been singed by fel fire.\n\nThe head of the curators in Dalaran is renowned for his restoration skills.  Perhaps he can treat the tome to bring it back to legibility.", objectives = "" }
WordHunterWoW_QuestEN[44487] = { title = "Waterlogged Tome", description = "In spite of its magical nature, the book has been damaged by water.\n\nThe head of the curators in Dalaran is renowned for his abilities.  Perhaps he can restore it.", objectives = "" }
WordHunterWoW_QuestEN[44488] = { title = "Cursed Tome", description = "Much of the elven writing in the tome has been singed by fel fire.\n\nThe head of the curators in Dalaran is renowned for his restoration skills.  Perhaps he can treat the tome to bring it back to legibility.", objectives = "" }
WordHunterWoW_QuestEN[44489] = { title = "Lyana Darksorrow", description = "<Your fellow Illidari, Lyana Darksorrow, floats captive in stasis in front of you; her soul slowly draining into the harvester crystal.>\n\n<In order to release her from stasis, you will need to destroy the soul harvester.>", objectives = "" }
WordHunterWoW_QuestEN[44490] = { title = "Grimwing the Devourer", description = "You have my thanks for rescuing me from captivity, {name}.\n\nHowever, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion.\n\nBefore we can get to him, there is another that must be destroyed.\n\nGrimwing the Devourer is the strongest of the felbats. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears.\n\nThen, return to me with her head. My thirst for vengeance must be quenched.", objectives = "" }
WordHunterWoW_QuestEN[44492] = { title = "Leyline Apprentice", description = "Good work finding those additional leyline feeds.\n\nYou seem rather competent - for an outlander.\n\nAllow me to share with you a few secrets about the power of the leylines. This should help you in scavenging more ancient mana from the creatures around Suramar. A grisly task, I know - which is why I leave it to you!", objectives = "" }
WordHunterWoW_QuestEN[44493] = { title = "Leyline Proficiency", description = "Our leyline feed grows stronger.\n\nThe more powerful our feed becomes, the more I learn about ancient mana itself.\n\nOf course, as my apprentice, you may reap the benefits of my discoveries. Listen well, and I will teach you how to extract power from your enemies more reliably.", objectives = "" }
WordHunterWoW_QuestEN[44495] = { title = "Leyline Master", description = "You surprise me, outlander. During our first lesson about the ancient leylines, I half-expected you to be lost in daydreams of adventure, or treasure or... some such nonsense.\n\nBut you have proven an apt student.\n\nOur leyline feed has grown extremely powerful. Watching it grow has taught me a great deal about the arcane, and the nature of mana.\n\nI have one final lesson that will help you find even more ancient mana.", objectives = "" }
WordHunterWoW_QuestEN[44496] = { title = "Destiny Unfulfilled", description = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.\n\nYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.\n\nWe must travel to Outland to experience Illidan's last memory.", objectives = "" }
WordHunterWoW_QuestEN[44497] = { title = "Destiny Unfulfilled", description = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.\n\nYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.\n\nWe must travel to Outland to experience Illidan's last memory.", objectives = "" }
WordHunterWoW_QuestEN[44498] = { title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  The well is to the southeast, but be warned: whoever did this may still be there, laying in wait.\n\nThis may prove very dangerous, {name}.  Be careful...but do not let the defilers of our well escape.", objectives = "" }
WordHunterWoW_QuestEN[44500] = { title = "Author! Author!", description = "We've reviewed the tome recovered from Karazhan. Though we found references to the Pillars of Creation, one piece of crucial information was omitted from the book... where to find the artifacts.\n\nFortunately, we have access to an expert on the subject.\n\nThe author, Alodi, was the first Guardian of Tirisfal. His spirit is forever bound to the Forge of the Guardian, which has been hidden in our safekeeping. I think the time has come to call him forth.", objectives = "" }
WordHunterWoW_QuestEN[44543] = { title = "The Battle for Broken Shore", description = "This wind rider will take you to Broken Shore, {name}. May your weapon bring you many kills today.\n\nThe Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.", objectives = "" }
WordHunterWoW_QuestEN[44544] = { title = "Call of the Earthen Ring", description = "At last, I've found you!\n\nI have a message from Advisor Sevel.\n\nThe Earthen Ring has need of you, Farseer. Please return to the Heart of Azeroth at your soonest convenience. Advisor Sevel is eagerly awaiting your return.", objectives = "" }
WordHunterWoW_QuestEN[44545] = { title = "Pressing the Assault", description = "<With this Pillar of Creation safely secured, it is time to take advantage of your momentum and continue onward after the next.>\n\n<You recall that your order has gathered information that would aid you in your journey - looking it over once more before setting off would be wise.>", objectives = "" }
WordHunterWoW_QuestEN[44547] = { title = "Isle Hopping", description = "<Victory in hand, you know there are still Pillars of Creation that must be recovered if the Legion is to be defeated once and for all.>\n\n<Your order has identified uncharted regions of the Broken Isles that still house the remaining Pillars - looking over the information would help focus your next effort.>", objectives = "" }
WordHunterWoW_QuestEN[44548] = { title = "Scouring What Remains", description = "<Looking around the chamber, you know you are well on your way to gathering all of the Pillars of Creation, but your work is not yet complete.>\n\n<Your order has continued to scour the isles below for anything that might be useful - best to check in with them before embarking once more.>", objectives = "" }
WordHunterWoW_QuestEN[44549] = { title = "Master of the Isles", description = "<Only one region remains from your order's carefully laid plan to assault the Broken Isles and gather the Pillars of Creation.>\n\n<Victory feels close, but studying your order's intelligence one last time couldn't hurt.>", objectives = "" }
WordHunterWoW_QuestEN[44550] = { title = "Called to Acherus", description = "Deathlord, your presence has been requested on Acherus.\n\nThe war against the Burning Legion rages on and the Knights of the Ebon Blade await further orders.\n\nPlease return to Acherus at your soonest convenience. Siouxsie the Banshee is awaiting your return.", objectives = "" }
WordHunterWoW_QuestEN[44555] = { title = "Khadgar's Discovery", description = "Champion! Please come to the Violet Citadel immediately.\n\nI have made a discovery that I would like to share with you before the Council of Six.", objectives = "" }
WordHunterWoW_QuestEN[44557] = { title = "Finite Numbers", description = "It seems not all the protections I put in place have been defeated. The Legion isn't able to open portals inside or near the tower... at least, not yet.\n\nThey appear to be bringing reinforcements in through the catacombs running beneath Deadwind Pass. Disable them and you just might buy us the time we need to drive them out of Karazhan.", objectives = "" }
WordHunterWoW_QuestEN[44561] = { title = "Seed of Hope", description = "Thalyssra was wise to send you in search of the arcan'dor, though she underestimates its power.\n\nShe will learn - as will the others.\n\nBut it will take time. And with hunger gnawing at their very souls, the Nightfallen will need your help to survive.", objectives = "" }
WordHunterWoW_QuestEN[44562] = { title = "Growing Strong", description = "Magic has long been a vice of the elves. It shaped us, and lifted us out of the darkness - but without balance, it also threatens to unmake us.\n\nThe shal'dorei are too proud to admit it, but they are the product of indulgence. They live without harmony.\n\nBut I sense potential among the Nightfallen. Losing everything has humbled them. It has made them stronger.\n\nStay the course, {name}. Help the Nightfallen rise up.", objectives = "" }
WordHunterWoW_QuestEN[44563] = { title = "Redemption for the Fallen", description = "Soon the change of seasons will be upon us, and the Nightfallen will take command of their fate.\n\nYou have given them hope, and set them on the path to redemption. They need you now more than ever.\n\nWe all do.", objectives = "" }
WordHunterWoW_QuestEN[44570] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[44571] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
