WordHunterWoW_QuestEN[44577] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence or crushing our enemies into dust!\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
