WordHunterWoW_QuestEN[44627] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[44636] = { title = "Building an Army", description = "We must keep our eyes on the future. There will come a time when we will need an army.\n\nWe've proven that the withered are not completely beyond redemption. They can be taught, and molded.\n\nI want you to be their combat trainer, {name}. Come with me. We can use the nearby ruins as an arena to hone their abilities.", objectives = "" }
WordHunterWoW_QuestEN[44663] = { title = "In the Blink of an Eye", description = "<The entity speaks with the familiar voice of Archmage Khadgar.>\n\nAzeroth needs you, {name}!\n\nAfter scouring Ulduar and Karazhan for answers, we know the key to defeating the Legion: five ancient artifacts called the Pillars of Creation.\n\nTo find them, Dalaran must be moved to the Broken Isles. As our leader Jaina is... absent, Kalecgos of the blue dragonflight has offered the Kirin Tor his aid.\n\nThe Legion is assaulting our current position over Deadwind Pass. Hurry!", objectives = "" }
WordHunterWoW_QuestEN[44667] = { title = "Will of the Valarjar", description = "As we prepare to launch an attack on the Legion's own world, it is important to not give reprieve to our enemies in this one.\n\nAs your armies seek to secure enemy gateways, you would do well to return to the Broken Isles and carry on the battle against those who stand against you.", objectives = "" }
WordHunterWoW_QuestEN[44672] = { title = "Ancient Mana", description = "Without the Nightwell to feed upon, my comrades and I will have to live off the land itself.\n\nAncient mana from the underground leylines can reach the surface in many forms, most commonly as crystals or gems.\n\n<Thalyssra picks up a small stone and, whispering words of power, traces a rune upon it with her fingertip.>\n\nThis stone will glow when ancient mana is nearby. Please gather as much as possible! It will be a precious resource in the weeks to come.", objectives = "" }
WordHunterWoW_QuestEN[44680] = { title = "Leading by Example", description = "We cannot let our current situation overshadow the Unseen Path's mission to protect the people of Azeroth.\n\nThere are many in this world who could use our help.\n\nAs our leader, you can set the example by aiding those in need.", objectives = "" }
WordHunterWoW_QuestEN[44682] = { title = "Unparalleled Power", description = "Power is all around us, {name}, waiting to be harnessed.\n\nYou must venture out into the world and claim it for the council!\n\nWith our First wielding such unparalleled power, our enemies won't stand a chance.", objectives = "" }
WordHunterWoW_QuestEN[44683] = { title = "Holding the Lines", description = "Karazhan sits upon a confluence of ley lines. It's why this location was chosen for the tower in the first place... a fact that has not escaped the Legion's notice.\n\nIf the demons are tapping into these lines of power, they must need their energy for something particularly menacing. You must cut off their access to the ley lines if we're to have a chance of retaking the tower, {name}.", objectives = "" }
WordHunterWoW_QuestEN[44684] = { title = "Corruption Runs Deep", description = "Everything the Legion touches is marred by fingerprints of their corruption. If I can study the traces of magic they leave behind, perhaps I can discern their plans for Karazhan.\n\nThis vial is specially reinforced to contain fel magic. If you bring me the essences of corrupted soil and water from near their portals, I believe we'll be closer to unraveling their scheme.", objectives = "" }
WordHunterWoW_QuestEN[44685] = { title = "Reclaiming the Ramparts", description = "With the ley lines protected we must move to secure the tower's perimeter.\n\nAround the tower are several locations where corruption continues to run rampant. Seek out these locations and secure them with these wards.\n\nWith the progress we've made so far, bolstering our defenses should keep the remaining Legion's forces at bay just long enough for us to discover who's behind their efforts.", objectives = "" }
WordHunterWoW_QuestEN[44686] = { title = "Thought Collection", description = "While I examine these samples further, I ask that you seek out one of our patrols in the structure to the north. It appears they've captured one of the demons.\n\nGo, interrogate it. Find out anything you can. And hurry! I'm afraid time is no longer an ally.", objectives = "" }
WordHunterWoW_QuestEN[44689] = { title = "The Might of the Tirisgarde", description = "The Tirisgarde has received requests from across the Broken Isles for aid in fighting the Burning Legion. While we will continue pursuing Archmage Vargoth, we cannot forget that our primary mission is to repel the demons and protect Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[44690] = { title = "A Thirst For Blood", description = "Blood is the fountain of life and the fuel of my creations. Unfortunately, Deathlord, my supply is running low and the quality as of late has been disappointing at best.\n\nIf my undead offspring are to reach their full potential, I will need pure blood of the highest quality. Bring me the Blood of Sargeras and I will use it to fuel my finest creations!", objectives = "" }
WordHunterWoW_QuestEN[44691] = { title = "Hungry Work", description = "We must get Chief Telemancer Oculeth back on his feet as soon as possible.\n\nFind ancient mana, any way you can, and feed it to him.", objectives = "" }
WordHunterWoW_QuestEN[44694] = { title = "One Battle at a Time", description = "Before I  became a demon hunter, I practiced the arcane arts. I still retain some of that knowledge, though the fel makes it all but impossible to use.\n\nOne thing I can still manage is the occasional glimpse into faraway places. You've seen me use the nether crucible to do this. I'm afraid that things don't look too good.\n\nThe forces that are arrayed against us are not limited to the Burning Legion. You must act quickly to keep the Broken Isles from being overwhelmed.", objectives = "" }
WordHunterWoW_QuestEN[44700] = { title = "Stormheim", description = "It is good we found you, {name}!\n\nSky Admiral Rogers has sent word for you to meet her in Dalaran. It sounded important. She awaits your presence in the Violet Citadel.\n\nMake haste!", objectives = "" }
WordHunterWoW_QuestEN[44701] = { title = "Stormheim", description = "It is good we found you, {name}!\n\nNathanos Blightcaller, Champion of the Banshee Queen herself, sent for you in Dalaran. He made it sound urgent. He should be waiting for you in the Violet Citadel.\n\nMake haste!", objectives = "" }
WordHunterWoW_QuestEN[44719] = { title = "Breaching the Sanctum", description = "It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area.\n\nTake these telemancy orbs. If you find you need support, use them to summon Withered.\n\nWe must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.", objectives = "" }
WordHunterWoW_QuestEN[44720] = { title = "A Call to Action", description = "<As the raven stares into your eyes, a familiar voice fills your mind.>\n\nChampion, I require your aid. It seems Helya has shown her hand.\n\nSteel yourself then come to me.", objectives = "" }
WordHunterWoW_QuestEN[44721] = { title = "Helya's Conquest", description = "If Helya is making an advance on the Broken Isles, we will need to answer in turn.\n\nGo to Tideskorn Harbor and scout her forces. We will see if Helya is foolish enough to begin her campaign against me.", objectives = "" }
WordHunterWoW_QuestEN[44722] = { title = "Disillusioned Defector", description = "The atmosphere in the city has improved little, but we may find this to our advantage today.\n\nSilgryn asks for you at the Terrace. It seems even Elisande's forces are fleeing before her insanity.\n\nA defector has risen from the ranks and seeks to join our cause.\n\nSee that this individual is well received, {name}. We need all the friends we can get during these dark times.", objectives = "" }
WordHunterWoW_QuestEN[44723] = { title = "More Like Me", description = "Greetings, Outlander.\n\nI am Victoire. I served Elisande while she maintained peace in the city. I fought beside demons and worse for the greater good.\n\nThe massacre at the Waning Crescent made it clear that she no longer serves the Nightborne. She serves only herself.\n\nThere are others who feel as I do. They simply need proof that there is another way.\n\nThe Dusk Lily is not unknown to us- try showing it to those now guarding Astravar Harbor. They have seen the worst of Elisande's cruelty.", objectives = "" }
WordHunterWoW_QuestEN[44724] = { title = "Missing Persons", description = "Our new friend brings us some disturbing information.\n\nShe claims to have seen a large number of citizens dragged from Starcaller Retreat in chains. Their destination appears to be Astravar Harbor.\n\nThose taken to the harbor have yet to return, however. Worse yet, the area is now overrun with demons.\n\nI need you to find out where these people went. Infiltrate the harbor and gather any information you can.\n\nStart with the Legion filth- their corpses may point us in the right direction.", objectives = "" }
WordHunterWoW_QuestEN[44725] = { title = "Hostage Situation", description = "Our own people, sacrificed to the Legion!\n\nWe need to intercept a transport if we intend to put an end to this trade. I'm afraid this does mean you will be playing the part of a captive, my friend.\n\nBefore voicing your concerns, try to have a little faith.\n\nWe will follow behind in one of Deline's boats and break you out once we know where they are going.\n\nGo to the harbor and find a group of captives. Stand among them. Allow yourself to be taken.\n\nWe will not be far.", objectives = "" }
WordHunterWoW_QuestEN[44726] = { title = "In the Business of Souls", description = "We will hold our position here while you find and slay the demon responsible for this camp.\n\nEnding Aargoss will not permanently stop this smuggling operation, but it may slow them down long enough for us to find another way to help these people.\n\nGo quickly. He is somewhere atop this ridge.", objectives = "" }
WordHunterWoW_QuestEN[44727] = { title = "Smuggled!", description = "Please get me out of here!\n\nThe bars are brittle but I am so weak...\n\nThe others! There are so many others! Please help us!", objectives = "" }
WordHunterWoW_QuestEN[44729] = { title = "Trial of Valor: Odyn's Favor", description = "The time to deal with that treacherous witch has come. I suspect you may be the one to deal the final blow, but I must be certain.\n\nSee me in the Halls of Valor and we will test the strength of your will.", objectives = "" }
WordHunterWoW_QuestEN[44733] = { title = "The Power of Corruption", description = "The time has come at last.\n\nDeep within the cavernous underbelly of Karazhan lies a long-forgotten chamber. Based on what you learned from our demon friend, I believe this is where its mistress dwells.\n\nThis demon's master must come from the highest ranks of the Burning Legion. This does not bode well for Karazhan.\n\nWe need to secure Deadwind Pass, {name}.\n\nYou must find this demon and destroy it.", objectives = "" }
WordHunterWoW_QuestEN[44734] = { title = "Fragments of the Past", description = "Though your primary objective is to liberate the tower from the Legion's hold, I have... another request.\n\nKarazhan is a place where magic and history intertwine. Moments of the past have been known to take physical form, and these forms can possess great power.\n\nAs you journey through Karazhan, watch for places where memories coalesce. These fragments could provide valuable insight into what's really going on inside that tower.", objectives = "" }
WordHunterWoW_QuestEN[44735] = { title = "Return to Karazhan: In the Eye of the Beholder", description = "The Legion's intentions are clear. They intend to harness the tower's magical energy to communicate with other Legion worlds!\n\nI'm afraid we haven't much time, {name}. You must ascend the tower and destroy this monstrosity before it is too late!", objectives = "" }
WordHunterWoW_QuestEN[44736] = { title = "Gates of the Nighthold", description = "Our combined armies are arrayed in front of the palace, ready to strike! I cannot believe the time has come.\n\nYour allied commanders are already there and we will join you. Make your way to Astravar Harbor and speak with Khadgar. He is coordinating the attack, or at least I think he is.\n\nSee you there... and thanks for everything.", objectives = "" }
WordHunterWoW_QuestEN[44738] = { title = "Full Might of the Elves", description = "Thalyssra managed to get all 3 to agree to the same thing? I am impressed with her skills of negotiation.\n\nAlright hero, Liadrin is already marching on Suramar. Join her forces.\n\nTyrande will flank the city defenders and meet you deeper in.\n\nThe Nightborne will bring up the rear and hold the territory for us.\n\nOculeth and I will move the Kirin Tor forces to Astravar Harbor. With luck, we shall see you on the other side.", objectives = "" }
WordHunterWoW_QuestEN[44739] = { title = "Ready for Battle", description = "Thanks to your efforts and a lot of effort on the part of our new army, the Nightfallen are prepared for battle.\n\nWhat is more, we have managed to evacuate nearly all of the civilians between here and Astravar Harbor.\n\nI have drafted plans that can lead our combined forces through the city and take the harbor.\n\nCan you deliver these plans to Vereesa, Tyrande and Liadrin?", objectives = "" }
WordHunterWoW_QuestEN[44740] = { title = "Staging Point", description = "That is quite a corridor you and our allies have punched through the city. It will be difficult to hold but it will cut a wedge in Elisande's forces.\n\nOculeth has been busy redirecting a telemancy beacon to this location but wanted to give you the honor of activating it.", objectives = "" }
WordHunterWoW_QuestEN[44741] = { title = "Return to Karazhan: The Big Bag Theory", description = "I'm sure you've heard, {name}, that a bigger bag is always better. I disagree. I believe it's the quality of the bag that makes all the difference.\n\nJust look at those tattered things around your person. They make you look... well, quite plain.\n\nI'll prove it to you. Allegedly there are some bags in Karazhan that hold an almost infinite amount of items, but the materials required to make such bags are... well, you'll see.", objectives = "" }
WordHunterWoW_QuestEN[44742] = { title = "Tavernkeeper's Fate", description = "I have finished unraveling Ly'leth's message.\n\nI want you to come with me to her estate. It is long past time I returned to the city.", objectives = "" }
WordHunterWoW_QuestEN[44743] = { title = "Tyrande's Command", description = "Shal'aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered.\n\nAnd in all of this, Tyrande has a battery of requests I simply do not have the time to deal with.\n\nWill you go to her? Her growing army is hard to miss in Meredil.", objectives = "" }
WordHunterWoW_QuestEN[44747] = { title = "War Cargo", description = "Lord Illidan will be arriving shortly, and my orders are to establish a base camp before he arrives.\n\nHowever, the war effort has taken its toll and I have been given little in the way of equipment and supplies.\n\nThe wreckage of the previous assault on Broken Shore lays nearby. Scavenge the beach for any supplies you can find and bring them to me.\n\nOur hope of survival will rest upon the strength of our stronghold, so we will need all the help we can find.", objectives = "" }
WordHunterWoW_QuestEN[44749] = { title = "Names of the Fallen", description = "The Battle of Broken Shore was bloody and our losses were great. Many lives were lost in the defense of Azeroth.\n\nThe fallen soldiers of the Alliance and Horde deserve to have their names known.\n\nFind those valiant soldiers lost in the shipwreck and bring their insignias to me. I will ensure sure that the fallen are given a proper memorial.\n\nAzeroth will survive, and their sacrifice shall be recorded in the annals of history.", objectives = "" }
WordHunterWoW_QuestEN[44750] = { title = "Names of the Fallen", description = "The Battle of Broken Shore was bloody and our losses were great. Many lives were lost in the defense of Azeroth.\n\nThe fallen warriors of the Alliance and Horde deserve to have their names known.\n\nFind the fallen warriors lost in the shipwreck and bring their insignias to me. I will ensure sure that our honored dead are given a proper memorial.\n\nAzeroth will survive, and their sacrifice shall be recorded in the annals of history.", objectives = "" }
WordHunterWoW_QuestEN[44752] = { title = "Essence Triangulation", description = "Vanthir... an example! That certainly explains why Elisande chose to hold him this long.\n\nWe need to move quickly. I can track him, but I will need to find places where his Arcane Essence is strongest.\n\nThis will not be an easy feat, not in a city this old, but with any luck there are a few places important enough to him that he left a little bit of himself behind.\n\nWe should start in the promenade- he often visited it for business.", objectives = "" }
WordHunterWoW_QuestEN[44753] = { title = "On Public Display", description = "Now that I have identified Vanthir's essence from the multitude of Suramar's citizens, it may be that I can find his exact location.\n\nI believe you'll recall a similar ritual with our friend Theryn. Do not worry- there will be less screaming this time. Hopefully.\n\nCome. Let us find our missing tavernkeeper.", objectives = "" }
WordHunterWoW_QuestEN[44754] = { title = "Waxing Crescent", description = "His captor is familiar to me. He is one of Aluriel's lieutenants and a skilled spell-fencer at that. You will need Silgryn's help to retrieve the key to Vanthir's prison.\n\nOur friend's life hangs in the balance. Even if we manage to wrestle him from the executioner's grasp, he may well Wither before we can act.\n\nI need you to take an Arcan'dor fruit to him. They are precious, and few, but for Vanthir this is the only chance he has.\n\nGo quickly, and good luck.", objectives = "" }
WordHunterWoW_QuestEN[44756] = { title = "Sign of the Dusk Lily", description = "Simply... astounding.\n\nI have not felt this clear of mind in so long.\n\nI am still weak... I need to rest. But first...\n\n<Vanthir gestures to the top of his cage with a trembling hand.>\n\nShow them that the Dusk Lily triumphs this day.", objectives = "" }
WordHunterWoW_QuestEN[44758] = { title = "What's the Cache?", description = "We're here for a cache of gunpowder. It seems to have been infused with some sort of fel power... it's extremely reactive. One of the leaders of the pirate forces here currently has it.\n\nMaster Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.", objectives = "" }
WordHunterWoW_QuestEN[44764] = { title = "Demon in Disguise", description = "While you were... working your magic on that demon, I was able to make headway in distilling the corrupted essences down to a simpler, more manageable form.\n\nI've asked Khadgar to provide you with the concoction once he's had a look, but I must remind you - these essences are quite potent, often dangerous if not handled with the utmost of care.\n\nSpeak with Khadgar when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[44766] = { title = "Backup Plan", description = "Dalaran may appear to be just a floating city, but it is actually our most powerful magical weapon. It will take time to repair the arcane defenses - time the Legion will use to their great advantage.\n\nIt is imperative to come up with an interim plan, and quickly! \n\nArchmage Kalec is very knowledgeable about this sort of thing. Perhaps you should consult with him?", objectives = "" }
WordHunterWoW_QuestEN[44767] = { title = "A Celestial Invitation", description = "Greetings, mortal.\n\nFor many years I have continued my observation of this planet. The halls of Ulduar have been hollow and silent, save for the occasional clattering whisper from the darkness. I grew so very bored of it!\n\nThus, I have taken up this \"pet battling\" you seem so fond of. Truly, an amusing pastime that will sustain my mind for many centuries!\n\nI have been amassing my collection, scouring the stars for tiny beings of cosmic power. Come, let us do battle once more!", objectives = "" }
WordHunterWoW_QuestEN[44768] = { title = "Nyell's Workshop", description = "From what I've overheard, this is Master Artificer Nyell's workshop. His skills in construct creation are unparalleled! \n\nWhat a shame that he swore fealty to the Legion. I hate to destroy such a renowned craftsman, but we have no choice.\n\nIf you are lucky, he might even have a spare shield generator sitting around.", objectives = "" }
WordHunterWoW_QuestEN[44770] = { title = "Secrets of the Shal'dorei", description = "This workshop includes an extensive library of rare scrolls written by my people. We all benefit by sharing information, do you not agree? \n\nPerhaps if we bring back such a treasure trove the Tirisgarde will be more welcoming towards me and my kind...\n\nPlease gather whatever you can.", objectives = "" }
WordHunterWoW_QuestEN[44771] = { title = "A Threat Rises", description = "It is time I told you another tale. While you listen, would you be so kind as to pour me some grog? I've grown a terrible thirst.\n\nThe keg is very old and the tap is a bit slow.", objectives = "" }
WordHunterWoW_QuestEN[44775] = { title = "The Peak of Bones", description = "While you were gone, we strategized what to do with the harness. We can utilize its power to bind the spirits of deceased drakes to you, raising them under your will as loyal soldiers.\n\nI sent Minerva to Thorim's Peak in Stormheim, where she has found a brood of deceased Thorignir. They will be prime targets.\n\nSpeak to Grimwing for a flight to the mountain, then Minerva will fill you in.", objectives = "" }
WordHunterWoW_QuestEN[44782] = { title = "Away From Prying Eyes", description = "Wars are not won solely with armies charging bravely across the battlefield, {class}t.\n\nSometimes, it is the actions of individuals that matter most, fighting battles few ever hear about. That is why - \n\n<Khadgar furrows his brow slightly.>\n\nWe should really discuss this somewhere a tad more private. Let's move up to the Purple Parlor, shall we?", objectives = "" }
WordHunterWoW_QuestEN[44783] = { title = "From Bones They Rise", description = "Alright, the job is to get the broodmother under our control. But hear me out. A few more drakes would be a boon, right?\n\nWhile we're here, why don't we use our awesome power over undeath to raise some of her brood as well? Although the peak has claimed their corpses for the ice, I'm sure the embrace of undeath will be much more welcoming. We must find their frozen corpses and breathe your will into them.", objectives = "" }
WordHunterWoW_QuestEN[44785] = { title = "Tea Party", description = "I...I-I'm sorry. I... I can't...\n\n\n<You hear footsteps behind you.>\n\n\nA... Abby? Wh...", objectives = "" }
WordHunterWoW_QuestEN[44787] = { title = "The Bonemother", description = "It's time to call the mother, the true reason we came. She is strong, her sheer will and strength allowing her to face this peak in order to watch over the remains of her brood. While the Thorignir is a grand sight, I like my dragons a little more bony. She must die first.\n\nRemember the pyre where we met? She is its guardian, as the spirit was at the peak. If we light it, she will come.", objectives = "" }
WordHunterWoW_QuestEN[44789] = { title = "Holding the Ramparts", description = "With their ground presence weakened the Legion has retaliated with additional forces.\n\nOur allies managed to track several of these demons to the skies above Black Rook. I fear they intend to establish a foothold.\n\nTake this hippogryph and scout the ramparts. Should this fear become a reality I ask that you deal with the threat swiftly.", objectives = "" }
WordHunterWoW_QuestEN[44790] = { title = "Trial by Demonfire", description = "We are out of time. I have reports that a pitlord has come to Meredil. \n\nI have dispatched a strike force. We cannot let this demon flank our army here, nor can we let him find Shal'Aran. It is time to temper these recruits in a real battle.\n\nJoin our forces in Meredil, engage the demon, and help us ensure this new army of ours is not lost in its first conflict.", objectives = "" }
WordHunterWoW_QuestEN[44800] = { title = "Against Magatha's Will", description = "Well? What are you waiting for? Hand over the Doomstone.", objectives = "" }
WordHunterWoW_QuestEN[44803] = { title = "Return to Karazhan: Master of the House", description = "Inside the pocket watch is a worn note.\n\n\"The next affair will take place in Morgan's Plot, it will cause quite a stir! The following guests will be in attendance:\n\nLord Ference, his preferred vintage is red.\nBaroness Millstipe, she will only attend on the promise of cheese. Strange woman.\nBaron Dreuger, a ravenous soul, any well spiced meat should keep him happy.\n\nAs always, I shall ring the bell should I need you.\n\n- Medivh\"", objectives = "" }
WordHunterWoW_QuestEN[44814] = { title = "Waning Refuge", description = "We have done all we can here.\n\nLet us get everyone into the boat and get out while we still can.\n\nWe have bought time for the others but nothing more.", objectives = "" }
WordHunterWoW_QuestEN[44821] = { title = "In Dire Need", description = "The ill tidings you bear only increase the concerns the Council has been having.\n\nI know you have your hands full with the Tomb of Sargeras. Make no mistake, the battle for the tomb remains our top priority--but we must not think the Legion foolish enough to rely on brute force alone. They are far more cunning than that.\n\nPlease, hear us out.", objectives = "" }
WordHunterWoW_QuestEN[44822] = { title = "Temporal Investigations", description = "I knew the shal'dorei dabbled in time magic, but this is simply incredible...\n\nElisande stopped time on our entire army!\n\nCome, let us investigate. Perhaps there is a way to break the spell - or at least discover how it is being maintained.", objectives = "" }
WordHunterWoW_QuestEN[44827] = { title = "Citizens' Army", description = "I can barely get these civilians to stand in a straight line.\n\nThey are untrained, undisciplined, and underarmed.\n\nStill, they need to be ready for the real battle.\n\nKhadgar suggested we try some field training at the ruins of Black Rook Hold in Val'sharah. The risen forces of Lord Ravencrest apparently remember how to fight.\n\nGo, hero, and I will send some trainees to support you.", objectives = "" }
WordHunterWoW_QuestEN[44829] = { title = "We Need Weapons", description = "So many of the rebels want to help in the coming battle. Our people have the will, they lack only the means.\n\nThey need weapons.\n\nFrom what Khadgar has told me, the fortress of Black Rook has plenty of munitions we could use.\n\nTravel to the fortress and place these beacons on some weapon caches there. Once placed, I can teleport them back.", objectives = "" }
WordHunterWoW_QuestEN[44830] = { title = "Learning From the Dead", description = "I heard you were traveling to Black Rook Hold.\n\nIt was once home to the legendary Lord Ravencrest, a brilliant tactician. His knowledge may be exactly what we need to give us an edge against the Duskwatch.\n\nWhile you are at the Rook, keep your eyes peeled for any books that might have survived the ages that outline the Ravencrest's strategems.", objectives = "" }
WordHunterWoW_QuestEN[44831] = { title = "Taking a Promenade", description = "These people are foreign to us, despite our common heritage. They have changed much in the years they have been cloistered away.\n\nWe need to learn more about them, what they are capable of. We dispatched one of our scouts to infiltrate the Promenade and assess the defenses. The blood elves did the same, although I doubt their ability to be discreet.\n\nBoth are long past due for reporting back to us. Find them and make sure they are safe or at least did not die in vain.", objectives = "" }
WordHunterWoW_QuestEN[44832] = { title = "Scouting the Breach", description = "If Ly'leth's information is accurate, there is a breach in the Sanctum of Order that could be our only way into the Nighthold.\n\nNo doubt they have magically sealed it - take Valtrois and protect her while she examines the seal. She is an exceptional talent, and I have total faith in her ability to break whatever enchantment they have cooked up.\n\nValtrois has her own methods of getting into the city and will meet you inside the Sanctum of Order.", objectives = "" }
WordHunterWoW_QuestEN[44833] = { title = "The Seal's Power", description = "The Nightwell is so overloaded that they could not spare anything for this seal. Instead, they are borrowing power from the ley lines.\n\nI have traced one of their power sources to Kel'balor. We should head there immediately so I can determine how best to disable this barrier.\n\nYes of course I said \"we.\" Surely you do not expect me to go without my bodyguard, do you?\n\nI shall meet you there!", objectives = "" }
WordHunterWoW_QuestEN[44834] = { title = "Nullified", description = "The magus in charge of the defenses here is powerful. Perhaps too strong, even for the both of us.\n\nFortunately, the sin'dorei know a thing or two about magic. The mage's barrier is strong, but we are clever.\n\nHe has somehow channeled enough energy into his staff to power another set of defense portals, but he has left it out of his sight. Bring me the staff and an energy source from one of those constructs. I should be able to create just the thing we need to take that shield out.", objectives = "" }
WordHunterWoW_QuestEN[44842] = { title = "Shield, Meet Spell", description = "There you have it, one arcane nullifier! Using their weapon and magical signatures to cloak the spell, it should tear apart the shield as good as any spellbreaker would.\n\nGo teach that amateur spellslinger what it means to wage war against the sin'dorei!", objectives = "" }
WordHunterWoW_QuestEN[44843] = { title = "Crystal Clearing", description = "This portal is a problem. With it they can summon countless reserves.\n\nThe crystals nearby seem to be powering the gate. If we destroy those, we can set them back significantly.", objectives = "" }
WordHunterWoW_QuestEN[44844] = { title = "Powering Down the Portal", description = "Destroying the crystals will stop them temporarily, but it will be meaningless if we do not deal with the person controlling the portal itself.\n\nI heard their overseer, Ingra, shouting orders for more power so that she could bring the stronger Legion lieutenants through the gate. We must stop her to truly seal the portal for good.", objectives = "" }
WordHunterWoW_QuestEN[44845] = { title = "Break An Arm", description = "The insurgents you marshaled gave me some bad news, {name}.\n\nThe arcanists loyal to Elisande have reactivated the Arm of the Magistrix. The most powerful construct ever attempted, it raged out of control and decimated an entire district before it was disabled. Truly they must be desperate to turn it against us.\n\nThe scouts have spotted it in the Crimson Thicket to the north. We cannot allow it to reach full power if we are to succeed.", objectives = "" }
WordHunterWoW_QuestEN[44849] = { title = "Recruitment Drive", description = "Helya's kvaldir have been raiding Azeroth's coasts for centuries, and many worthy vrykul who were destined to become my Valarjar were stolen. \n\nNow that their cursed queen is defeated, the souls held captive in Helheim can finally be freed to join us!\n\nGo to Helheim with Aerylia. I assure you she will bring you back safely.", objectives = "" }
WordHunterWoW_QuestEN[44850] = { title = "Arming the Army", description = "The recent battles have greatly depleted our supplies, and we will need arms for our new Valarjar. \n\nThe kvaldir have an abundance of weapons, armor, and other spoils from their raiding stockpiled in stolen crates. \n\nConfiscate whatever you can!", objectives = "" }
WordHunterWoW_QuestEN[44858] = { title = "Trolling Them", description = "My army is disciplined, and they will follow my order not to engage the Sin'dorei in combat unless I give the command.\n\nHowever, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults.\n\nPlease, {name}, we need someone both armies respect to collect these items before fighting breaks out.", objectives = "" }
WordHunterWoW_QuestEN[44859] = { title = "Liadrin's Command", description = "Shal'Aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered.\n\nAnd in all of this, Lady Liadrin has a battery of requests I simply do not have the time to deal with.\n\nWill you go to her? Her growing army is hard to miss in Meredil.", objectives = "" }
WordHunterWoW_QuestEN[44860] = { title = "Trolling Them", description = "My army is disciplined, and they will follow my order not to engage the kaldorei in combat unless I give the command.\n\nHowever, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults.\n\nPlease, {name}, we need someone both armies respect to collect these items before fighting breaks out.", objectives = "" }
WordHunterWoW_QuestEN[44861] = { title = "Arming the Rebels", description = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages.\n\nVictoire and Silgryn are doing their best to train the new arrivals, but could use an experienced hand.\n\nGo to them and show them some of the skills in battle you have picked up in your travels. I want those Nightfallen ready for battle when the time comes.", objectives = "" }
WordHunterWoW_QuestEN[44862] = { title = "Arming the Rebels", description = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages.\n\nVictoire and Silgryn are doing their best to train the new arrivals and could use an experienced hand.\n\nGo to them and show them some of the skills in battle you have picked up in your travels. We need those Nightfallen ready for battle when the time comes.", objectives = "" }
WordHunterWoW_QuestEN[44863] = { title = "Clearing the Air", description = "Ancient weapons require ancient offerings to regain the knowledge on how to construct them.\n\nIf you wish to learn how weapons forged from air are crafted, then you must first battle with beings born from it.\n\nBring me their cores and I will gift you the knowledge you seek.", objectives = "" }
WordHunterWoW_QuestEN[44865] = { title = "Butler to the Great", description = "A ghostly dinner party awaits, ready for the spread and its dinner guests.", objectives = "" }
WordHunterWoW_QuestEN[44868] = { title = "Trial of Valor: Odyn's Judgment", description = "You've proven worthy to challenge Helya. Now with my blessing, the power to defeat her is yours.", objectives = "" }
WordHunterWoW_QuestEN[44869] = { title = "Talon Terror", description = "I just received word that the Shrine of Aviana is under attack by the Burning Legion! While the Druids of the Talon here are taking their time planning and strategizing their defense, our brothers and sisters are being slaughtered where they stand.\n\nI cannot stand idly by while my home shrine is in danger. Please, come with me to save my people.", objectives = "" }
WordHunterWoW_QuestEN[44870] = { title = "Mouths to Feed", description = "We have rescued many refugees, as you can see. Unfortunately this has revealed a new problem.\n\nThe arcan'dor fruit is our salvation, but it does not bear enough fruit right now to cure everyone. We must rely on mana a little longer to tide the refugees over.\n\nValtrois thinks that she may have a solution. Please go speak with her and see what she plans to do.", objectives = "" }
WordHunterWoW_QuestEN[44873] = { title = "Oculeth Ex Machina", description = "I have a plan to feed Shal'Aran.\n\nNow that I am no longer starving for mana I have had time to study ley lines in new regions. I detected an eddy of mana in the ley lines of Azsuna. I have plenty of magic at my disposal, but we must visit the ley line in person in order to properly redirect the energy to Shal'Aran.\n\nOculeth has graciously offered to teleport us there, but I could use an assistant. Care to join me?", objectives = "" }
WordHunterWoW_QuestEN[44874] = { title = "Unbeleyvable", description = "Back to the task at hand!\n\nTake these ley line taps. We can use the resonant energies to properly redirect the flow, but they must be placed in precise locations. I will show you where.\n\nYour friend has agreed to... \"supervise\" us. Let us hope she just stays out of the way while the professionals take care of this.", objectives = "" }
WordHunterWoW_QuestEN[44875] = { title = "The Art of Flow", description = "All done, {name}! We have but one more step and Shal'Aran will have all the mana it needs.\n\nNow that I have better access to the ley line below I can break the pool so that it will flow through properly. Given the chaotic state of this ley line it will require all of my concentration to redirect the energy.\n\nI must warn you that we will attract attention while I am doing this. You will need to protect me while I complete the process.\n\nSpeak to me when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[44876] = { title = "A Dance With Dragons", description = "I must say I am impressed, {name}.\n\nYou and your friend were able to fix a ley line, and you are not even dragons!\n\nYou both seem exhausted by this ordeal. Allow me to help you get back home.", objectives = "" }
WordHunterWoW_QuestEN[44877] = { title = "Attack on the Roost", description = "Skylord Shadegrove has been leading the defense of the shrine, but I think he's starting to lose hope. Clearly he needs some more firepower behind him!\n\nLet's take out these demons and fend off the attack. They'll never see it coming!", objectives = "" }
WordHunterWoW_QuestEN[44883] = { title = "A Speedy Delivery", description = "The Silver Hand are launching a second assault to the west, where the Alliance and Horde fleet previously landed during the first attack. Their objective is to take the beach and liberate any survivors or captives they can find.\n\nEven as we speak, they do battle against the enemy. There is little time to spare, we must aid them as soon as possible.\n\nMake your way down to the beach and find Justicar Julia Celeste. She is leading the Silver Hand's attack and will know best we can aid them.", objectives = "" }
WordHunterWoW_QuestEN[44885] = { title = "Shipwrecked Survivors", description = "It appears that we have allies here on the Broken Shore.\n\nA small band of shipwrecked soldiers have been surviving here since the first assault. Their strength and tenacity will bolster our ranks.\n\nMake your way to their encampment along the beach and bring them here. Tell them that reinforcements have arrived, and the battle against the Burning Legion waits for no one.", objectives = "" }
WordHunterWoW_QuestEN[44888] = { title = "Aviana's Grace", description = "If this was only the distraction, where is the main force? Who else is under attack? We need to figure out who else is in danger! Aviana should know, she's got eyes everywhere.\n\nLet's go ask her. We should be able to contact her in the back room.", objectives = "" }
WordHunterWoW_QuestEN[44889] = { title = "Resource Management", description = "Now that you possess Helya's Horn, the kvaldir are yours to command. We may as well put them to good use for a change. \n\nI've dispatched my Val'kyr, Danica, to the Broken Shore. She has identified a few Legion targets that should be eliminated.\n\nAerylia will send you there when you are ready to leave.", objectives = "" }
WordHunterWoW_QuestEN[44914] = { title = "Arms: The Thieving Apprentice", description = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him.\n\nFortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem.\n\nI'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.\n\nSpecialization: Arms Warrior", objectives = "" }
WordHunterWoW_QuestEN[44915] = { title = "Professionally Good Looking", description = "The archmage has recently locked himself away in his tower. If you wish to enter, you'll need help from some of his apprentices. I'm afraid you won't get it dressed like that.\n\nXylem has a thing for... outfits, and his apprentices use them to show rank. If you wish his apprentices to help you, you'll need to appear their superior. Such is their desire to impress the archmage, many of his apprentices will battle each other for the best pieces.\n\nI think you know where this is going.", objectives = "" }
WordHunterWoW_QuestEN[44918] = { title = "A Message From Our Enemies", description = "{name}! The messages from Ly'leth we traced throughout the Terrace - we could not have known at the time, but somebody was watching.\n\nThis crystal was delivered by a courier early this morning. <Pointing to the crystal by her side.>\n\nI am afraid the message contained within is not for the faint of heart. It has not been shown to anyone else, but you deserve to see it for all you have done for us.", objectives = "" }
WordHunterWoW_QuestEN[44919] = { title = "A Challenge From Our Enemies", description = "Make no mistake. This message cannot be taken lightly. Any threat made against our people will be dealt with swiftly.\n\nWe must travel to the estate at once to discover what has become of Ly'leth.", objectives = "" }
WordHunterWoW_QuestEN[44920] = { title = "Order of Incantations", description = "The barrier shielding the tower can only be opened by activating the imbued gems in the correct order. The order is only known to Xylem and his inner circle of apprentices. No others have yet been able to decipher the code, and mistakes are met with deadly consequences.\n\nThe aspiring apprentices spend a lot of their time around the tower. Some may have seen or heard something that might point to a solution.\n\nLet us hope, for your sake, their information proves valuable.", objectives = "" }
WordHunterWoW_QuestEN[44921] = { title = "Lone Wolf", description = "My eyes and ears fly across Azeroth, bringing me back news of many things. My ally Goldrinn took to the barrows of Moonglade in mourning upon the death of Varian Wrynn. He has been untouched in the dream... until now.\n\nDemons have been seen invading the very same barrows, killing many more of our mortal druids in the process. You must go. Save Goldrinn, avenge our people! Take my hatchling Thisalee with you. Her tenacity and bloodlust is welcome in my clutch. You shall have my aid.", objectives = "" }
WordHunterWoW_QuestEN[44922] = { title = "Inside the Winter Storm", description = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top.\n\nAccording to my  intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", objectives = "" }
WordHunterWoW_QuestEN[44924] = { title = "The Archmage Accosted", description = "With the barrier dispelled, Archmage Xylem is finally within reach!\n\nHopefully he'll be cooperative in returning the Iris...", objectives = "" }
WordHunterWoW_QuestEN[44925] = { title = "Closing the Eye", description = "We have received reports from the apprentices at Xylem's Tower that they've been able to use the remant of Xylem's portal to pinpoint his location.\n\nWe have orders from the Council of Six to open a portal directly to him, though whatever magic he's channeling on the other end is powerful enough to allow us to only keep it open for a brief window.\n\nThe apprentice, Joanna asked I give you this message before you proceed. Speak to me when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[44926] = { title = "A Familiar Axe to Grind", description = "The construction of this blade feels familiar, but you can't quite recall where you may have seen something like it before.\n\nPerhaps someone at Chiselgrip might know more about its construction.", objectives = "" }
WordHunterWoW_QuestEN[44927] = { title = "Worth Its Weight in Steel", description = "Listen, ye seem like one who may be interested in getting a copy of those axe plans.\n\nCould probably make a pretty penny at the auction house on it. But I can't just hand 'em over to ya, lad. Not fer free.\n\nThat axe blade ye brought me, I could use more of those. Good steel in those blades. Don't worry, lad, I just need a few...\n\nWhat do ye say?", objectives = "" }
WordHunterWoW_QuestEN[44928] = { title = "Something's Not Quite Right...", description = "Something is troubling me, champion.\n\nBeyond these simple japes, the Kirin Tor has had to break up a few fights between the elves. I am worried something - or someone - might be influencing them.\n\nYour disguise was made by the nightborne, yes? It is not unreasonable to assume they can do something similar.\n\nFortunately, Thalyssra has told me much about how the illusion works, and I believe this crystal can remove their disguise.\n\nWhy don't you check the camps, just to be safe?", objectives = "" }
WordHunterWoW_QuestEN[44930] = { title = "Deadmines: Sea'in Red", description = "Arr, finally! I been stuck up here f'years with naught company but me own thoughts. Tis good to clap me eyes on another swashbuckling soul. Are ye up for a plot of revenge and skullduggery? These meddlin' Defias thugs murdered  me and me crew years ago before they took over this cave. I propose a series of counter-murders to bring about balance! Bring me proof ye've dealt with enough of the thieves to clog a bilge pump!", objectives = "" }
WordHunterWoW_QuestEN[44940] = { title = "Inside the Winter Storm", description = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top.\n\nAccording to my  intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", objectives = "" }
WordHunterWoW_QuestEN[44948] = { title = "Raising Your Snowfeather", description = "<Your snowfeather hatchling looks at you timidly. It appears to be looking to you to help it survive and grow.>", objectives = "" }
WordHunterWoW_QuestEN[44949] = { title = "The Smell of Humans", description = "<You've noticed that your snowfeather hatchling shakes whenever humans are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of humans, so that it can get used to the smell.>", objectives = "" }
WordHunterWoW_QuestEN[44950] = { title = "Hunting Lesson: Northern Hawk Owls", description = "<Your snowfeather hatchling seems to get agitated when you are near other critters, none more so than the hawk owls of Highmountain. It fluffs up its plumage and squawks loudly whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", objectives = "" }
WordHunterWoW_QuestEN[44952] = { title = "Blackrock Depths: Jewel of the Depths", description = "Welcome to Everlook. Could I interest you in a new weapon of sorts?\n\nYou know, I'm not just into selling weapons of mass dismemberment here at the shop. I like rare jewels as well.\n\nPerhaps you and I can come to an arrangement of sorts in procuring a jewel I've had my eye on getting for quite some time. I have some great blacksmithing plans here you might be interested in, you know, in trade for your services.\n\nNow, onto the details...", objectives = "" }
WordHunterWoW_QuestEN[44953] = { title = "Allies in Highmountain", description = "<Your snowfeather hatchling emits a deep, chittering growl when you pass near Thunder Totem.> \n\n<The Highmountain Tribes immediately began attempting to evict the falcosaurs from their territory. It must consider them a threat to the flock, and the growl is probably its attempt to protect you.>\n\n<Show your falcosaur that you and it can work alongside the Highmountain Tribes.>", objectives = "" }
WordHunterWoW_QuestEN[44954] = { title = "Snowfeather Team Up", description = "<Your snowfeather hatchling looks at you and emits a sort of squawking bark. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", objectives = "" }
WordHunterWoW_QuestEN[44955] = { title = "Visitor in Shal'Aran", description = "Someone came to Shal'Aran while you were in the City. She asked for you specifically.\n\nI did not recognize her face, nor her voice, but she seemed trustworthy and earnest.\n\nShe is just outside the cavern. Meet with her and determine her purpose for coming here.", objectives = "" }
WordHunterWoW_QuestEN[44956] = { title = "Deadly Prey", description = "<After working together on recent pet battles, your snowfeather falcosaur seems much more interested in your combat abilities. It might learn a thing or two from watching you do battle with a powerful opponent.>", objectives = "" }
WordHunterWoW_QuestEN[44957] = { title = "Hunting Lesson: Spiketail Beaver", description = "<Your snowfeather hatchling has been interested in following beaver tracks recently. It must have found a new species to prey upon.>", objectives = "" }
WordHunterWoW_QuestEN[44958] = { title = "The Unfriendly Faction", description = "<When passing the other faction recently, your snowfeather walked right up to them without fear. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", objectives = "" }
WordHunterWoW_QuestEN[44959] = { title = "Snowfeather Bonding", description = "<Your snowfeather hatchling keeps getting into your pack and making a mess. It squawks loudly whenever you remove it, and rams you with its head. Maybe you can distract it with a tiny pack of its own?>", objectives = "" }
WordHunterWoW_QuestEN[44960] = { title = "Hunting Lesson: Mudshell Conch", description = "<Your snowfeather hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the snails of Highmountain.>", objectives = "" }
WordHunterWoW_QuestEN[44961] = { title = "Teamwork Lesson: Naraxas", description = "<While victorious, your snowfeather hatchling squawked and pecked at its allies during some of those last fights. Showing it a good example of teamwork might help.>", objectives = "" }
WordHunterWoW_QuestEN[44962] = { title = "Hunting Lesson: Coralback Fiddler", description = "<Your snowfeather hatchling is particularly wary of the elemental pets in your menagerie. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", objectives = "" }
WordHunterWoW_QuestEN[44964] = { title = "I'll Just Leave This Here", description = "Valtrois has a plan for the Sanctum's energy barrier.\n\nSeveral key Arcway locations throughout Suramar harness the power necessary for it. These Energy Disruptors she made will remotely break the links simultaneously on activation, causing the barrier to fall.\n\nTake these devices and install them at the leylines, then return here for the surprise assault on the Sanctum.", objectives = "" }
WordHunterWoW_QuestEN[44967] = { title = "Teamwork Lesson: Ursoc", description = "<Your snowfeather hatchling continues to fight with other pets when threatened. It must learn to remain calm under pressure, even when facing great beasts. Showing it an epic example of teamwork against a great beast might help.>", objectives = "" }
WordHunterWoW_QuestEN[44968] = { title = "Snowfeather Team Rumble", description = "<Your snowfeather hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", objectives = "" }
WordHunterWoW_QuestEN[44969] = { title = "Snowfeather Reunion", description = "<Your snowfeather hatchling has been lethargic as of late. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "" }
WordHunterWoW_QuestEN[44971] = { title = "The Smell of Orcs", description = "<You've noticed that your snowfeather hatchling shakes whenever orcs are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of orcs, so that it can get used to the smell.>", objectives = "" }
WordHunterWoW_QuestEN[44973] = { title = "Raising Your Direbeak", description = "<Your direbeak hatchling appears uncertain about what to do with itself. It appears to be looking to you to help it survive and grow.>", objectives = "" }
WordHunterWoW_QuestEN[44974] = { title = "The Smell of Dwarves", description = "<You've noticed that your direbeak hatchling shakes whenever dwarves are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of dwarves, so that it can get used to the smell.>", objectives = "" }
WordHunterWoW_QuestEN[44975] = { title = "The Smell of Tauren", description = "<You've noticed that your direbeak hatchling shakes whenever tauren are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of tauren, so that it can get used to the smell.>", objectives = "" }
WordHunterWoW_QuestEN[44976] = { title = "Hunting Lesson: Rose Taipan", description = "<Your direbeak hatchling seems to get agitated when you are near other critters, none more so than the rose taipans of Stormheim. It squawks loudly and slams its beak into the dirt whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", objectives = "" }
WordHunterWoW_QuestEN[44977] = { title = "Allies in Stormheim", description = "<Your direbeak hatchling scratches the ground and stares down a member of the Valarjar more than ten times its size.> \n\n<The Valarjar must have seen the falcosaurs as an excellent new source of meat, and begun hunting them immediately. Though a new species to the Broken Isles, it already fears the inhabitants of Stormheim.>\n\n<Show your falcosaur that you and it can work alongside the Valarjar.>", objectives = "" }
WordHunterWoW_QuestEN[44978] = { title = "Direbeak Team Up", description = "<Your direbeak hatchling bites you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", objectives = "" }
WordHunterWoW_QuestEN[44979] = { title = "Dire Prey", description = "<Your direbeak falcosaur nearly trips you the next time you enter combat. It is eager to learn more about how to defeat deadly creatures. It might learn a thing or two from watching you do battle with a powerful opponent.>", objectives = "" }
WordHunterWoW_QuestEN[44980] = { title = "Hunting Lesson: Tiny Apparition", description = "<Your direbeak hatchling seems to see prey that you cannot, sometimes staring at a wall for hours at a time. It must have found a new species to prey upon, or gotten into some mead.>", objectives = "" }
WordHunterWoW_QuestEN[44981] = { title = "The Unkindly Faction", description = "<When passing the other faction recently, your direbeak squawked at them for food. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", objectives = "" }
WordHunterWoW_QuestEN[44982] = { title = "Direbeak Bonding", description = "<Your direbeak hatchling puffs up its feathers and growls at you in a display of dominance. It seems unhappy with the results, as you are not cowering in fear. It might like to dress up like a grown-up falcosaur and try again.>", objectives = "" }
WordHunterWoW_QuestEN[44983] = { title = "Hunting Lesson: Golden Eaglet", description = "<Your direbeak hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the eagles of Stormheim.>", objectives = "" }
WordHunterWoW_QuestEN[44984] = { title = "Teamwork Lesson: Fenryr", description = "<Your direbeak hatchling timidly avoided the other flying pets during their last battles together. Showing it a good example of teamwork might help.>", objectives = "" }
WordHunterWoW_QuestEN[44985] = { title = "Hunting Lesson: Stormstruck Beaver", description = "<Your direbeak hatchling looks warily at any loud piece of machinery you pass. You begin to wonder if something transpired between it and a mechanical pet at one point. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", objectives = "" }
WordHunterWoW_QuestEN[44986] = { title = "Teamwork Lesson: Krosus", description = "<Your direbeak hatchling squawks loudly and panics when very large creatures are nearby, even if they are friendly. It must learn to remain calm under pressure, even when facing creatures many times its size. Showing it an epic example of teamwork against a monster the size of a mountain might help.>", objectives = "" }
WordHunterWoW_QuestEN[44987] = { title = "Direbeak Team Rumble", description = "<Your direbeak hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", objectives = "" }
WordHunterWoW_QuestEN[44988] = { title = "Direbeak Reunion", description = "<Your direbeak hatchling won't stop emitting soft, melancholy squawks. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "" }
WordHunterWoW_QuestEN[44989] = { title = "Raising Your Sharptalon", description = "<Your sharptalon hatchling continues to shiver as it settles in at your side. It looks up at you with wide, unblinking eyes. It appears to be looking to you to help it survive and grow.>", objectives = "" }
WordHunterWoW_QuestEN[44990] = { title = "Raising Your Bloodgazer", description = "<Your bloodgazer hatchling looks at you curiously, cocking its head to the side and emitting a low whistle. It appears to be looking to you to help it survive and grow.>", objectives = "" }
WordHunterWoW_QuestEN[44991] = { title = "The Smell of Draenei", description = "<You've noticed that your bloodgazer hatchling shakes whenever draenei are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of draenei, so that it can get used to the smell.>", objectives = "" }
WordHunterWoW_QuestEN[44992] = { title = "The Smell of Night Elves", description = "<You've noticed that your sharptalon hatchling shakes whenever night elves are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of night elves, so that it can get used to the smell.>", objectives = "" }
WordHunterWoW_QuestEN[44993] = { title = "The Smell of Blood Elves", description = "<You've noticed that your bloodgazer hatchling shakes whenever blood elves are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of blood elves, so that it can get used to the smell.>", objectives = "" }
WordHunterWoW_QuestEN[44994] = { title = "The Smell of Undead", description = "<You've noticed that your sharptalon hatchling shakes whenever forsaken are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of forsaken, so that it can get used to the smell.>", objectives = "" }
WordHunterWoW_QuestEN[44995] = { title = "Hunting Lesson: Spring Strider", description = "<Your sharptalon hatchling seems to get agitated when you are near other critters, especially the spring striders of Val'sharah. It fluffs up its plumage and scratches the ground whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", objectives = "" }
WordHunterWoW_QuestEN[44996] = { title = "Hunting Lesson: Erudite Manafiend", description = "<Your bloodgazer hatchling seems to get agitated when you are near other critters, none more so than the erudite manafiends of Azsuna. It makes an odd, low clucking noise and spreads its wings whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", objectives = "" }
WordHunterWoW_QuestEN[44997] = { title = "Allies in Val'sharah", description = "<Your sharptalon hatchling stubbornly refuses to enter Val'sharah when you approach.> \n\n<Though they revere nature, the Dreamweavers also must maintain the balance of nature, and began an aggressive campaign against the falcosaurs once their invasiveness was noted. It has likely seen the druids of Val'sharah slaughter some members of its flock.>\n\n<Show your falcosaur that you and it can work alongside the Dreamweavers.>", objectives = "" }
WordHunterWoW_QuestEN[44998] = { title = "Allies in Azsuna", description = "<Your bloodgazer hatchling emits a terrified squawk, and you sense the spirits of Azsuna are nearby.> \n\n<The spirits of the elves of Azsuna must seem strange and unnatural to your pet. It may instinctively fear them.>\n\n<Show your falcosaur that you and it can work alongside the spirits of the Court of Farondis.>", objectives = "" }
WordHunterWoW_QuestEN[44999] = { title = "Sharptalon Team Up", description = "<Your sharptalon hatchling flaps its wings excitedly and squawks at you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", objectives = "" }
WordHunterWoW_QuestEN[45000] = { title = "Bloodgazer Team Up", description = "<Your bloodgazer hatchling runs in a circle around your feet, nearly tripping you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", objectives = "" }
WordHunterWoW_QuestEN[45001] = { title = "Destructive Prey", description = "<Your sharptalon falcosaur watches carefully when you are in combat. It appears to be interested in your abilities. It might learn a thing or two from watching you do battle with a powerful opponent.>", objectives = "" }
WordHunterWoW_QuestEN[45002] = { title = "Dangerous Prey", description = "<Your bloodgazer falcosaur continues to tremble timidly whenever a powerful creature is nearby. It would help to build its confidence to see you defeat such a creature.>", objectives = "" }
WordHunterWoW_QuestEN[45003] = { title = "Hunting Lesson: Terror Larva", description = "<Your sharptalon hatchling has been desperately rooting for worms in Val'sharah recently. It must have found a new species to prey upon.>", objectives = "" }
WordHunterWoW_QuestEN[45004] = { title = "Hunting Lesson: Fledgling Kingfeather", description = "<Your bloodgazer hatchling has been flapping its wings excitedly and rubbing its beak on the trunks of trees in Azsuna. It must have found a new species to prey upon.>", objectives = "" }
WordHunterWoW_QuestEN[45005] = { title = "The Uncongenial Faction", description = "<When passing the other faction recently, your sharptalon attempted to play with their pet. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", objectives = "" }
WordHunterWoW_QuestEN[45006] = { title = "The Unfavorable Faction", description = "<When passing the other faction recently, your bloodgazer sniffed curiously at their pack. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", objectives = "" }
WordHunterWoW_QuestEN[45007] = { title = "Sharptalon Bonding", description = "<Your sharptalon hatchling will instinctively run into the kitchen of any inn you enter and make a mess of the pots and pans. It has a tendency to get into any dishes that are laying about, especially the dirty ones. You may be able to curb this behavior by finding it some silverware of its very own.>", objectives = "" }
WordHunterWoW_QuestEN[45008] = { title = "Bloodgazer Bonding", description = "<Your bloodgazer hatchling seems to love rolling around in flowers. You surmise that an affinity to flowering plants has probably helped the flock locate fruits to consume in the past. It would probably be quite excited to have a special flower of its own!>", objectives = "" }
WordHunterWoW_QuestEN[45009] = { title = "Hunting Lesson: Auburn Ringtail", description = "<Your sharptalon hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the raccoons of Val'sharah.>", objectives = "" }
WordHunterWoW_QuestEN[45010] = { title = "Hunting Lesson: Juvenile Scuttleback", description = "<Your bloodgazer hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the crabs of Azsuna.>", objectives = "" }
WordHunterWoW_QuestEN[45011] = { title = "Teamwork Lesson: Dresaron", description = "<Your sharptalon hatchling does not seem particularly interested in your other pets, and largely ignores them during combat. Showing it a good example of teamwork might help.>", objectives = "" }
WordHunterWoW_QuestEN[45012] = { title = "Teamwork Lesson: Serpentrix", description = "<While victorious, your bloodgazer hatchling distracted your other pets during crucial moments in combat. Showing it a good example of teamwork might help.>", objectives = "" }
WordHunterWoW_QuestEN[45013] = { title = "Hunting Lesson: Vale Flitter", description = "<Your sharptalon hatchling adamantly refuses to go anywhere near a body of water, squawking and scratching the ground whenever you wade in yourself. Perhaps working with some aquatic pets would help it get over this fear. Hunting together against the new prey it has begun stalking may just do the trick.>", objectives = "" }
WordHunterWoW_QuestEN[45014] = { title = "Hunting Lesson: Felspider", description = "<Whenever you retire to an inn, your hatchling climbs the furniture and refuses to touch the ground. It will hop unsteadily from object to object, often causing a large mess. You recall that this may be due to a bad experience with fleas. Hunting together with some critter pets against new prey might help it get over this fear.>", objectives = "" }
WordHunterWoW_QuestEN[45015] = { title = "Teamwork Lesson: Xavius", description = "<Your sharptalon hatchling has taken to hiding in your pack when you approach very powerful creatures in the world. It must learn to remain calm under pressure, even when facing the darkest of nightmares. Showing it an epic example of teamwork against a fearsome foe might help.>", objectives = "" }
WordHunterWoW_QuestEN[45016] = { title = "Teamwork Lesson: Skorpyron", description = "<Your bloodgazer hatchling growls and hisses at large beasts, seemingly without concern for its own safety. It will need to learn to rely on numbers to keep it safe. Showing it an epic example of teamwork against a great beast might help.>", objectives = "" }
WordHunterWoW_QuestEN[45017] = { title = "Sharptalon Team Rumble", description = "<Your sharptalon hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", objectives = "" }
WordHunterWoW_QuestEN[45018] = { title = "Bloodgazer Team Rumble", description = "<Your bloodgazer hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", objectives = "" }
WordHunterWoW_QuestEN[45019] = { title = "Sharptalon Reunion", description = "<Your sharptalon hatchling has not been eating recently. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "" }
WordHunterWoW_QuestEN[45020] = { title = "Bloodgazer Reunion", description = "<Your bloodgazer hatchling refuses to drink. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "" }
WordHunterWoW_QuestEN[45021] = { title = "Answers Unknown", description = "Have you noticed a change in Jubeka's demeanor? I know she's not the warmest of warlocks, but I fear she's been more withdrawn than usual.\n\nI imagine her mind lingers on Kanrethad, the council's one-time leader. Jubeka was steadfast in her commitment to keeping him banished, until the Burning Legion took her as their prisoner.\n\nHis fate is unknown, and it's clearly troubling our friend. The last thing she said to me, was that she felt his presence in Azsuna. Don't let her travel this path alone.", objectives = "" }
WordHunterWoW_QuestEN[45024] = { title = "Cult Culling", description = "The lure of Kanrethad is strong. Even when not in this world, there are those who wish to be near him at any cost, hoping to share in his power.\n\nA group of these fanatics are here in Faronaar, working tirelessly to bring Kanrethad back, I've learned as much from my prisoner.\n\nWe cannot let them succeed, {name}. Find their compound and kill as many of them as you can.\n\nI will remain here and see what else I can learn about their intentions.", objectives = "" }
WordHunterWoW_QuestEN[45025] = { title = "Stealing the Source of Power", description = "My prisoner is a chatty one, {name}. He tells me that the Cult of the Green Flame is harnessing fel energy to fuel their efforts of bringing Kanrethad back from banishment.\n\nWithin their compound they are powering fel crystals that can hold a great amount of fel magic. Without the proper power to perform their ritual, the occultists will have a tough time succeeding in their task.\n\nSteal their fel crystals, but don't destroy them. We can always find a use for something so powerful.", objectives = "" }
WordHunterWoW_QuestEN[45026] = { title = "Expending Fel Energy", description = "Soon Kanrethad's banishment will fade, and he will return to our world. \n\nWe must keep him, and his power, out of the Legion's hands at any cost.\n\nIf my old friend is still in there somewhere, perhaps we can bring him back.\n\nThe crystals you recovered feed on fel energy. We can use the ravenous crystals to siphon away the magic that consumes Kanrethad.\n\nBut first, their power must be depleted. To do so, you will need to harness the power of the crystals and use their energy to kill demons.", objectives = "" }
WordHunterWoW_QuestEN[45027] = { title = "To the Broken Shore", description = "It would seem that Kanrethad's twisted followers have begun their ritual on the Broken Shore.\n\nWe must act quickly. The Burning Legion cannot be allowed to use Kanrethad as their weapon.\n\nWe have acolytes on standby, ready to perform a ritual of summoning on the Broken Shore when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[45028] = { title = "The Fate of Kanrethad", description = "I can feel his presence, Netherlord! Kanrethad is here! His followers have set up camp in the nearby pass, and are performing the ritual to bring him back as we speak.\n\nQuickly, take the fel crystals. Arrange them in a circle around Kanrethad.\n\nIf placed correctly, the crystals should link together and begin to siphon the fel energy.\n\nNow go, before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[45030] = { title = "The Fel-Etched Bone", description = "<The bone is covered in intricate runes, etched directly into the surface in what can only be powerful fel magic.>\n\n<Surely someone among the Kirin Tor in Dalaran would be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[45033] = { title = "The Inferno Stone", description = "<While just another bit of fel debris to the untrained eye, you recognize this stone as one of the catalysts used to accelerate the regeneration of the Legion's strongest warriors in the nether.>\n\n<What it is doing in Azeroth is uncertain. Perhaps the Kirin Tor in Dalaran could help you learn more?>", objectives = "" }
WordHunterWoW_QuestEN[45034] = { title = "Fire the Cannons!", description = "It will take more than a damn shipwreck to bring me down. Those overgrown, vomit-reeking, demon felbags have another thing coming if they think that's all it's gonna take to stop me.  \n\n<Keeshan coughs up seawater, wiping his mouth dry with his sleeve.>\n\nUghh... I may need a little breather though. Here, take this flare gun and use it to call down artillery strikes on the beach. Rain hell on those worthless, half-goat bastards and I'll rendezvous with you back at the base when the mission is complete!", objectives = "" }
WordHunterWoW_QuestEN[45036] = { title = "Asgrim the Dreadkiller", description = "The spirit of one of our most honored warriors has disappeared from the Halls of Valor.\n\nAsgrim the Dreadkiller was a great warlord and king. For centuries, his spirit has dwelled in its rightful place within the Halls of Valor... until recently.\n\nCountless years ago, the Dreadkiller's bones were laid to rest not far from here by his warband. We will seek our answers there.\n\nSound Odyn's Horn upon the burial ground and summon his spirit before us.", objectives = "" }
WordHunterWoW_QuestEN[45037] = { title = "The Locket of Eldre'Thalas", description = "<Carefully prying open the locket, you find a portrait of Queen Azshara made entirely of precious stones.>\n\n<Highborne possessions like this are rare - to find one so pristine in the hands of the Legion is deeply troubling.>\n\n<You know the Kirin Tor in Dalaran may be able to tell you more.>", objectives = "" }
WordHunterWoW_QuestEN[45043] = { title = "The Glowing Bloodthistle Petal", description = "<It is exceedingly rare to find bloodthistle outside of Blood Elf lands, especially a petal as fresh as this one.>\n\n<Perhaps the Legion merely claimed it off of a fallen combatant, but that seems far too convenient an explanation.>\n\n<You figure the Kirin Tor in Dalaran would likely be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[45044] = { title = "Weapon No More", description = "The spear you found certainly has the makings of troll designs from other blacksmithing crafts.\n\nPerhaps somebody at one of the camps here in Un'Goro will know more about it.", objectives = "" }
WordHunterWoW_QuestEN[45045] = { title = "The Vial of Ancient Mana", description = "<Upon closer inspection, this vial appears to be filled with moonwell water, well-known for its potent arcane properties.>\n\n<Interestingly, it does not seem to have been tainted by its previous owner. Though that should be comforting, it only broods suspicion as to its origin.>\n\n<Someone among the Kirin Tor in Dalaran would definitely be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[45050] = { title = "Infiltration Plans", description = "While the text is hard to follow and covered in demonic runes, it appears to be plans to infiltrate Dalaran. The Council of the Six will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[45051] = { title = "Reverse Blacksmithing", description = "And 'ere I thought I'd never see dis ting again!\n\nAlthough, it don't look like it used to. Aw mon, I'm gonna be in big trouble if I show up wit dis in my hand.\n\nDo ya tink you could help me fix it? I don't have da plans for it, cause you see, da first night I spent here, da creatures came up and stole all me tings.\n\nBut whadd'ya say? Help a bruddah out?\n\nI tink if you can figure out what it's made from, den you can fix it and I can write down da details on how it's made.", objectives = "" }
WordHunterWoW_QuestEN[45052] = { title = "Depleted Nether Crystal", description = "This crystal looks like something used in rituals of dark magic. Given that its energy is depleted, whoever this belongs to must have been successful in whatever ritual they were performing.\n\nThe mages of the Kirin Tor would likely be interested in investigating this.", objectives = "" }
WordHunterWoW_QuestEN[45053] = { title = "Thief's Instructions", description = "The hastily scrawled note reads:\n\n\"I require the Focusing Iris for one of my spells. Show that you are truly the greatest of my apprentici and fetch it for me.\n\nOh, and make sure you don't leave this note lying around for some adventurer to find!\"\n\nIf someone is looking to steal the Focusing Iris, the Kirin Tor will likely want to know.", objectives = "" }
WordHunterWoW_QuestEN[45054] = { title = "\"Ancient\" Elven War Orders", description = "These orders look official and bear the Ravencrest sigil, but they are far too new. There is also a hint of fel magic glimmering around the sides.\n\nThe Council of Six would be interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[45055] = { title = "A Taste of Their Own Medicine", description = "I been at dis camp for some time now, an' I know for a fact dat dose materials can be found right here in Un'Goro.\n\nTime ta give da creatures here some payback. Take from dem just like dey took from me! At least, you could do dat for me, right bruddah?\n\nI'll just wait here for ya to return wit' all da stuff.", objectives = "" }
WordHunterWoW_QuestEN[45056] = { title = "Noressa", description = "She is still in there, {name}. Noressa, my wife.\n\nShe is in the Promenade while we wait outside, preparing to strike. Who knows what has happened to her?\n\nPlease, friend, I fear the worst. Tell her there is hope outside.\n\nWe had a small house in the south of the Grand Promenade, by the water gardens. She will probably be there during this madness.", objectives = "" }
WordHunterWoW_QuestEN[45057] = { title = "Saving My Head", description = "Seeing as how you're a blacksmith, I figured it'd be best if ya made da spear. You can use dis forge here to do what ya need to to do.\n\nI'll start writin' down what ya do and den we'll have us both da spear and da recipe!", objectives = "" }
WordHunterWoW_QuestEN[45059] = { title = "Fel Infused Totem Fragment", description = "This appears to be a fragment of a relic or totem from Highmountain. It glows eerily with fel power. This should be brought to the Council of Six in Dalaran at once!", objectives = "" }
WordHunterWoW_QuestEN[45060] = { title = "Damaged Kirin Tor Insignia", description = "Whether it was lost or stolen, it is odd that a demon would possess an insignia of the Kirin Tor. \n\nThe Council of Six would no doubt be interested in this finding.", objectives = "" }
WordHunterWoW_QuestEN[45061] = { title = "Scrolls of the Faldrottin", description = "While it is definitely odd that a demon would carry a scroll of vrykul writings, what is even more interesting are the contents. \n\nThe writings appear to reference a vrykul prophesy of one who would unite the Tideskorn against the Burning Legion. This information should be brought to the Council of Six immediately.", objectives = "" }
WordHunterWoW_QuestEN[45062] = { title = "Resisting Arrest", description = "Your findings do not disappoint, {name}.\n\nMake your way to the soul engine and use our newly acquired weapons to dismantle the power source.", objectives = "" }
WordHunterWoW_QuestEN[45063] = { title = "The Felsoul Experiments", description = "Andaris's control over the withered poses a real threat. If we are to increase the withered's resistance against these effects, we must do so in an environment built from this very magic.\n\nHead for Felsoul Hold at once. When you arrive, I will send withered to aide in your efforts. It is of the utmost importance you do not leave until you are certain the experiments yield the appropriate results.", objectives = "" }
WordHunterWoW_QuestEN[45064] = { title = "Felborne No More", description = "The Felborne have begun to expand their grasp beyond the city's reach. A camp to the east in the Crimson Thicket is of a particular interest to us. Their outpost leader, Valthis Ama'ran, serves Andaris directly.\n\nNow is the time to put our withered training and Oculeth's device to the test. We cannot allow them to advance any further, {name}.\n\nHead for the camp and use the orb to sever the head of the beast. The time has come to begin our advance.", objectives = "" }
WordHunterWoW_QuestEN[45065] = { title = "Survey the City", description = "Never a dull moment! Well... perhaps this is not entirely true.\n\nI'm afraid I must ask you once more to return to the city to gather information. But this is not just any information - this is information extraction!\n\nI require specific coordinates to allow me to focus my teleportations with extreme accuracy. It will, unfortunately, take a bit of time to dig through the information once retrieved, but no matter. We have plenty else to do in the meantime.", objectives = "" }
WordHunterWoW_QuestEN[45066] = { title = "Experimental Instability", description = "In order to advance our studies I must ask you to recover a few particular items from my long-forgotten chambers.\n\nI assure you it is... mostly safe there, aside from a few unstable elements.\n\nMake your way to my workshop and locate the teleporter. I'll disable its cloaking device when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[45067] = { title = "Telemantic Expanse", description = "Understanding fel magic alone may not be enough, {name}.\n\nSpeak with Oculeth about diversifying our efforts. I hear he's got something... unique planned for us.", objectives = "" }
WordHunterWoW_QuestEN[45073] = { title = "Loot and Plunder!", description = "I'm bein' honest here matey, I've got me own motives fer bein' here. Last time there was a bit of a debacle. Some drinkin', some gamblin', and a bit too much rum if ye catch me meanin'. Some words were said, some fists were thrown and... honestly it was quite a haze. I'm not the most welcome pirate here after that.\n\nBut they took me stuff! These lyin', dirty ol'... ahem. Could ye just take this torch and... burn their belongin's? I'd be grateful.", objectives = "" }
WordHunterWoW_QuestEN[45079] = { title = "The Village of Glenbrook", description = "<The book is a register of the inhabitants of Glenbrook.\n\nAll but a few of the names are crossed out.>", objectives = "" }
WordHunterWoW_QuestEN[45083] = { title = "Crysa's Flyers", description = "I have obtained some of the most exotic species of carrion bird ever seen on Azeroth. Do you think you can stand up to them?", objectives = "" }
WordHunterWoW_QuestEN[45088] = { title = "Trial of Valor: The Lost Army", description = "While Helya's defeat is your primary objective, I require more of your aid. Helya has gained the ability to steal and corrupt the souls of my Valarjar. Her minions hold these souls, corrupting them. I am certain Helya herself hordes the greatest Valarjar souls to herself. You must recover these lost souls, then return them to me.\n\nDo this and I will reward you with blessed guard from the hall's armory.", objectives = "" }
WordHunterWoW_QuestEN[45098] = { title = "Orders of Magnitude", description = "We've come across an alarming number of unauthorized orders for war munitions in the past few days, including an advanced long-range targeting device and a large amount of military grade explosives.\n\nThe targeting device in particular was ordered from Mux Manascrambler - he's something of a master of tracking technology.\n\nHead out to his shop in Gadgetzan and see if you can obtain the identity of the buyer. We have to get to the bottom of this before those goods are put to use.", objectives = "" }
WordHunterWoW_QuestEN[45099] = { title = "Hot On The Trail", description = "Targeting device, eh?\n\n<Mux eyes you warily for a moment.>\n\nYeah, I sold one. Never saw the guy's face, though. Real private fella.\n\nA punch card fell out of his pocket as he was leavin', though. I had one of my lackeys tail him out of town in one of my rocket cars to return it.\n\nCustomer service, y'know?\n\nLouse never came back! But hey, if you're lookin' for trouble, they were headed west. That's all I can tell ya.", objectives = "" }
WordHunterWoW_QuestEN[45101] = { title = "Imminent Launch", description = "This is not good.\n\nWe have alarms set up throughout Gnomeregan to detect any unauthorized personnel while we finish de-irradiating it.\n\nJust about every single one was tripped in the past few hours.\n\nBased on your recon, it's a safe assumption that Thermaplugg is down there, and he has enough firepower with him to decimate anywhere he pleases!\n\nThat's where you come in. I'll get you to Gnomeregan. Talk to the High Tinker once you're there and do whatever it takes.\n\nFor Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[45102] = { title = "Begin the Assault", description = "The battle for our world has been hard fought, but with the power of your weapon and the combined forces of Azeroth, we have driven the demon invaders back at every turn.\n\nNow we stand once again upon the Broken Shore, poised to do that which we previously failed to accomplish. Let us not forget those who sacrificed everything to give us this chance. \n\nOur first objective is to take the hill before us, so that we may build a stronghold. Steel yourself, {name}. The assault on the Broken Shore begins now.", objectives = "" }
WordHunterWoW_QuestEN[45103] = { title = "We Ride!", description = "The time has come, Deathlord! Our scouts have marked a large amassing of demons not far from here. Lead us to victory, and show these demons the power of undeath!", objectives = "" }
WordHunterWoW_QuestEN[45105] = { title = "Lord Raz'gor", description = "The pit lord, Raz'gor, oversees this bulwark. If you wish to break the Broken Shore, Raz'gor must be defeated.\n\nFight you way past the demon blockade and find Lord Raz'gor. Slay the demon and you will strike a heavy blow to the Burning Legion's plans on the Broken Shore.", objectives = "" }
WordHunterWoW_QuestEN[45111] = { title = "Everyone Loves a Good Fight", description = "The note reads:\n\n\"You shouldn't have blabbed about the brawlers, especially to those champions. Now that you have though, I suppose it's ok that they fight here on occasion, but you better prove yourself a true brawler first!\"", objectives = "" }
WordHunterWoW_QuestEN[45112] = { title = "Signs of Madness", description = "<Whoever this buyer is, they seem to have left in a hurry. Acrid fumes sit heavy in the air around you, and a campfire in the center of the area smolders.>\n\n<Perhaps something here can point you in the right direction?>", objectives = "" }
WordHunterWoW_QuestEN[45118] = { title = "Helya's Horn", description = "{name}, we need to bolster our army by any means necessary. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. \n\nThey are eternally bound to obey Helya even through her death. If we can call them using her voice, they will follow us instead! \n\nWe recovered Helya's Horn from her corpse. Empower it so you can call the kvaldir when we have need of them.", objectives = "" }
WordHunterWoW_QuestEN[45123] = { title = "Elemental: The Folly of Levia Laurence", description = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.\n\nShe was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail.\n\nSpecialization: Elemental Shaman", objectives = "" }
WordHunterWoW_QuestEN[45125] = { title = "Dabbling in the Demonic", description = "Levia must have used these runes to aid her ritual. Even if she is as powerful as Modera says, she was a novice in demonic magic, so the runes must have helped stabilize the portal.\n\nI'll need you to find out what runes need to be activated to recreate her ritual. There are several books on runic magic in this room, which she no doubt studied for her ritual.\n\nOnce you have activated the runes, I will complete the spell.", objectives = "" }
WordHunterWoW_QuestEN[45126] = { title = "Unlikely Seduction", description = "Mo... Modera sent you?\n\nNo...  you must... leave!  Agatha will be back any moment!\n\nSave... yourself...", objectives = "" }
WordHunterWoW_QuestEN[45127] = { title = "Fel-Crossed Lovers", description = "That vile imp mother! If I wasn't so weakened I would dive down that pool and give her a piece of my mind!\n\n<Levia takes a deep breath to regain her composure.>\n\nIt's only a matter of time until Agatha can make use of the power she stole from me. We had best not be here when she does.", objectives = "" }
WordHunterWoW_QuestEN[45128] = { title = "A Glorious Reunion", description = "You have done well, Battlelord {name}. Let us return to Skyhold. Odyn will want to hear of your success here.", objectives = "" }
WordHunterWoW_QuestEN[45132] = { title = "Before It's Too Late", description = "<If the infamous Sicco Thermaplugg is behind this, the implications are dire indeed.>\n\n<Worse still, he appears to have allied himself with the Legion - who knows what 'gifts' they have given the mad mekgineer.>\n\n<Mux back in Gadgetzan can hopefully help you track down Thermaplugg before it's too late.>", objectives = "" }
WordHunterWoW_QuestEN[45133] = { title = "Signs of Madness", description = "I'm tellin' you, I already told ya everything I know!\n\nIf you want any info on the fella that bought that targeting system, you'll have to follow my assistant out west.\n\nThe buyer's camp is somewhere out that way...\n\nI think.", objectives = "" }
WordHunterWoW_QuestEN[45143] = { title = "Judgment Awaits", description = "Our ongoing offensive within the Broken Shore has drawn the interest of many paladins who wish to fight under your leadership. Some are more worthy than others, but only you can be the judge of that.\n\nThe new recruits are lingering in the camp just outside the chapel, awaiting your judgment.", objectives = "" }
WordHunterWoW_QuestEN[45145] = { title = "Moonfang Family Relics", description = "As promised, here is the crescent key that will open my family's lockboxes, though nothing of value remains.\n\nI trust whatever you find you'll deliver to Delas? Our ancestor's things, whatever their worth, should remain in our family.", objectives = "" }
WordHunterWoW_QuestEN[45146] = { title = "Runic Reading", description = "There is something curious about this scroll. It appears to be an empty page to the untrained eye, but I can see a shimmer of runes appear briefly when I hold it up to the light.\n\nAs with most demonic runes, I will need fel blood to undo the magic that's been used to conceal whatever message is within this scroll.", objectives = "" }
WordHunterWoW_QuestEN[45147] = { title = "Felstone Destruction", description = "<Delas' mouth drops open as the scroll falls from her hands and onto the floor.>\n\nThis cannot be... the runes... they detail a pact between the Burning Legion and my ancestors. A dark deal that would grant my ancestors protection from demons in this life, but in return, their spirits would belong to the Legion.\n\nThis fel pendant is an embodiment of the pact, and cannot be removed once worn.\n\nQuickly, {name}. You must use your artifact to destroy that cursed piece of jewelry!", objectives = "" }
WordHunterWoW_QuestEN[45148] = { title = "Oath Breaker", description = "Many years ago I made a pact with a man I thought not to be unlike myself. His promise of protection seemed too good to be true, but it was a deal I was desperate to make.\n\nIt wasn't until I had signed in blood that the dreadlord Zorak revealed himself.\n\nAs long as he lives, my ancestors will remain bound to the Burning Legion, allowing our enemies to amass an army of unwilling soldiers.\n\nHead to the Broken Shore and slay Oathbinder Zorak. His death will break the hold he has over my ancestors.", objectives = "" }
WordHunterWoW_QuestEN[45149] = { title = "Ending the Crescent Curse", description = "We must do whatever we can to break the curse that befalls my ancestors. \n\nThe Burning Legion have set up camp within the ruins that house our dead, ready to make good on the dreadful pact that was drafted so long ago.\n\nEach of my ancestor's is burdened with a pendant that binds them to their demonic overlords. It cannot be removed, but as you have shown, with enough power it can be destroyed. \n\nEnd the curse that plagues my ancestors and set their spirits free!", objectives = "" }
WordHunterWoW_QuestEN[45159] = { title = "Cubic Conundrum", description = "<You find a mysterious cube. Its design is unfamiliar, but unmistakably ancient. \n\nThe cube's surface is inlaid with magical runes. Though inert, its properties may be worth investigating.\n\nPerhaps if you show it to Dariness the Learned in Dalaran, she could tell you more about it.>", objectives = "" }
WordHunterWoW_QuestEN[45160] = { title = "Cubic Currents", description = "To determine this cube's purpose, we need to power it up. Hmm, I have an idea...\n\nThe Nightborne covet a substance you are no doubt familiar with called ancient mana. Should be just the thing for a relic this old. Gather a sufficient quantity and we'll attempt to get it working.\n\nBe careful in Suramar! It would be a shame if this curious cube were lost and became a memory once more.", objectives = "" }
WordHunterWoW_QuestEN[45162] = { title = "We Brought the Hammer", description = "Your champions found success in the brawl against the Warhammer Council. Bring this \"token\" to the Brawler's Guild as proof.", objectives = "" }
WordHunterWoW_QuestEN[45163] = { title = "Cleaning Up", description = "Your champions return successful. They tell a grand tale of how they really cleaned up against Bill the Janitor.", objectives = "" }
WordHunterWoW_QuestEN[45167] = { title = "REUSE ME", description = "{name}, we will need to bolster our army by any means necessary to have any hope of driving back the legion. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. They are bound to obey whomever posesses Helya's Horn. You must obtain it. \n\nHer so-called helarjar were tasked with guarding it. You will have to take it from them.", objectives = "" }
WordHunterWoW_QuestEN[45172] = { title = "To Battle!", description = "Your champions have returned from exploring the battleground with a report detailing wild adventures and death-defying feats of strength and honor. In these ever shifting battles of conquest, more assistance is always required.\n\nWill you answer the call?", objectives = "" }
WordHunterWoW_QuestEN[45174] = { title = "The Hunt for Illidan Stormrage", description = "Allari the Souleater, an oracle of the Illidari, has been on the hunt for Illidan's soul for quite some time. She now believes that she has discovered its location and requires your assistance in its recovery.\n\nFind Allari at Illidari Stand in Azsuna and aid her in any way possible.\n\nIf Sargeras truly plans to use Illidan's body as a vessel for his own return then returning Illidan's soul to his body is integral in preventing the dark titan from returning to our world!", objectives = "" }
WordHunterWoW_QuestEN[45175] = { title = "Soul Prism of the Illidari", description = "Alas, I will not burden you with the location of the master's soul just yet, {name}. First we must craft a soul prism powerful enough to hold the master's boundless chaotic energies.\n\nTo do this I require lingering soul fragments from powerful beings found across this world. Bring me enough and I will craft a soul prism capable of holding the soul of the master - at least long enough to transfer into the naaru.", objectives = "" }
WordHunterWoW_QuestEN[45176] = { title = "Trial of Valor: The Once and Future Lord of Shadows", description = "While tracking the master's physical body proved challenging, we were able to locate it in the Nighthold of Suramar. Our intelligence reports that Gul'dan is making final preparations to the Nightwell in order to use its power to usher the soul of Sargeras into Illidan's body.\n\nThe only way to stop that from happening is to put Illidan's own immortal soul back.\n\nTake the Soul Prism of the Illidari and venture to Helheim. Defeat Helya and use the prism on Illidan's soul! Return it to Light's Heart.", objectives = "" }
WordHunterWoW_QuestEN[45177] = { title = "The Nighthold", description = "Illidan's soul rests safely within Light's Heart. Take this vessel and deliver it to Khadgar with the following instructions:\n\nWhen Gul'dan attempts to tear the sky asunder and bring the dark titan into our world, call forth the power of this vessel and release Illidan's soul into his body.\n\nGo now, {name}. We do not have much time. The dark ritual will begin soon.", objectives = "" }
WordHunterWoW_QuestEN[45182] = { title = "Frost: The Twisted Twin", description = "I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.\n\nOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.\n\nFind Karam in the Legerdemain Lounge and see if you can lend a hand.\n\nSpecialization: Frost Mage", objectives = "" }
WordHunterWoW_QuestEN[45185] = { title = "Message from the Shadows", description = "I know my brother has been misguided in the past, but I fear that he may have fallen in with an unthinkable evil. He recently began meeting in secret with a dark cult, hidden amongst the people of Dalaran.\n\nI travelled here to try to convince him of the error in his ways, but he would not be shaken from his course. Now, he has disappeared. \n\nWhen I last saw him, Raest was staying in a room upstairs. I was unable to find any clues there, but you might fare better.", objectives = "" }
WordHunterWoW_QuestEN[45187] = { title = "Secrets in the Underbelly", description = "So my brother has gone off to perform some ritual with these cultists? That explains why he left, but still not to where...\n\nWait! This letter mentions some of these \"Nethersworn\" cultists seeking reagents in the Underbelly. Perhaps we still may be able to find them if we hurry!", objectives = "" }
WordHunterWoW_QuestEN[45188] = { title = "The Wisdom of the Council", description = "I'm sorry, {name}, but I can't make heads nor tails of this. Riddles have never exactly been my strength.\n\nWe should take this cultist's writings to the archmage. Perhaps he could shed some light on this.", objectives = "" }
WordHunterWoW_QuestEN[45190] = { title = "Where it's Thinnest", description = "Though I have never heard of this \"Nethersworn\" cult, what this manifesto speaks of can't be good.\n\nI do have a theory, however. The writing speaks of \"the place its skin is thinnest.\" I think they might be referring to the place where the veil between Azeroth and the Twisting Nether is weakest - the Tomb of Sargeras. \n\nWith our forces having established a foothold at the Broken Shore, this would be an opportune time for Raest and his cultist allies to reach the tomb. I would suggest you stop them.", objectives = "" }
WordHunterWoW_QuestEN[45192] = { title = "Runes of Rending", description = "My brother and his cultists are engaged in some kind of ritual at the far end of the cave. I tried to intervene, but my brother has left magical wards to block the way.\n\nIf you can find a way past them, we may be able to stop him in time!", objectives = "" }
WordHunterWoW_QuestEN[45193] = { title = "One Step Behind", description = "It looks like Raest is out of our reach, but at least his cultists should prove less of a threat.\n\nWe should return to the Kirin Tor. They should be able to help us plan our next move.", objectives = "" }
WordHunterWoW_QuestEN[45207] = { title = "The Nightborne Apprentice", description = "I would be happy to introduce you to my new apprentice if you do not mind traveling a bit. She is currently in the field keeping an eye on an enclave of Felborne resistance fighters who have sworn loyalty to the Legion. \n\nAs the first nightborne to join the Tirisgarde, I am sure she is eager to prove her skills!", objectives = "" }
WordHunterWoW_QuestEN[45209] = { title = "Those Scrying Eyes", description = "Until recently, Ly'leth was sending magical messages to us regularly from within the Nighthold. She took care to hide these messages - only the most vigilant scryers could have detected them.\n\nThey could not be within the palace... too much interference from the Nightwell...\n\nOf course! The Terrace of Enlightenment! The Duskwatch must have set up a listening post there.\n\nCheck the scrying orbs for traces of Ly'leth's messages. We must learn what she was trying to tell us!", objectives = "" }
WordHunterWoW_QuestEN[45238] = { title = "Return to Karazhan: Cubic Cynosure", description = "Drat! The ancient mana doesn't seem to be working. I need to think the problem through, focus and...\n\nWait, that's it! Focus! We need to focus the energy of the ancient mana to activate the cube.\n\nI've heard tell of a mana wyrm in Karazhan with the means to focus its powers. Might be just what we need!\n\nWatch out, though. My sources tell me this wyrm is humongous!", objectives = "" }
WordHunterWoW_QuestEN[45239] = { title = "Cubic Coalescing", description = "Success! The cube's magic has been restored! I'm excited to see what it does!\n\nSince you did all the legwork, you should have the honor of activating it. Care to give it a try?", objectives = "" }
WordHunterWoW_QuestEN[45240] = { title = "Making Preparations", description = "Deathlord, we have uncovered an heirloom of great significance and power. Rimefang's harness has appeared in Icecrown Citadel. We must obtain it, rather than let it fall into the hands of others.\n\nI assume you'd like to retrieve the harness personally? We've sent one of our own, Minerva Ravensorrow, ahead to scout. You've met her before, yes? She has impressed us greatly, and we believe she can become quite powerful under your tutelage.\n\nI will open a death gate for you. It is best you meet her there.", objectives = "" }
WordHunterWoW_QuestEN[45243] = { title = "On Daumyr's Wings", description = "The time is nigh, {name}. With these new dragons in our army, we are prepared for our assault on the Broken Shore. A large detachment of demons have appeared near one of our camps, and there are far too many of them for any of our allies to overcome.\n\nWho better to defeat these demons than those without fear of death? Those with quite the large secret weapon?\n\nTake Daumyr. We will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[45251] = { title = "Redundancy", description = "A construct progenitor? What a creative solution to our problem!\n\nWe probably could channel Kathra'natir's power without releasing him now, but I want to add another layer of protection before we try, just in case. I will not have anyone accusing me of subterfuge!\n\nMeet me on the Broken Shore when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[45260] = { title = "One Day at a Time", description = "Thank you for coming, outlander. It is good to see you again.\n\nI have a situation in the city that needs your attention, but first... \n\nLet us talk of hope.\n\n<Thalyssra gestures toward the arcan'dor.>\n\nThe fruit of the arcan'dor can truly free my people from the Nightwell. However, it only grows so fast. It will take time to distribute this cure.\n\nI think it only right that you help me pass out the fruit as it is ready. Please take this, and give it to anyone.", objectives = "" }
WordHunterWoW_QuestEN[45261] = { title = "Continuing the Cure", description = "Given the events at the Waning Crescent, the refugees here are more eager than ever to receive the gift of the arcan'dor and be free of the Nightwell forever. \n\nFortunately, the tree has borne more fruit. Again, I ask that you honor us by giving this fruit to anyone here in Shal'Aran.\n\nWhen you are finished, we shall discuss further developments within the city. Silgryn reports that Arluelle has proven a fine student, and the two are making progress in evacuating citizens.", objectives = "" }
WordHunterWoW_QuestEN[45262] = { title = "A Message From Ly'leth", description = "The arcan'dor bears fruit once again. Just in time, too - Ly'leth has sent us a message, and it seems she may have a lead on Vanthir. He is long overdue for this gift, assuming we manage to find him.\n\nGive a fruit to another citizen here in Shal'Aran while I finish decrypting Ly'leth's message.", objectives = "" }
WordHunterWoW_QuestEN[45263] = { title = "Eating Before the Meeting", description = "Having Vanthir around has done much to lift the spirits of the people here. I dare say some have begun to relish their newfound freedom, even if they miss their beloved city.\n\nI will not rest until I can give it back to them.\n\nYou and I have an important meeting to attend. Before we go, let us distribute more of the arcan'dor's fruit. \n\nI want people to know that although I must leave for now, I have not abandoned them.", objectives = "" }
WordHunterWoW_QuestEN[45265] = { title = "Feeding the Rebellion", description = "More nightborne flee Suramar every day to join our cause.\n\nOur ranks are swelling, and with the aid of great heroes like yourself and the armies of the Horde and Alliance, our chances have never been better.\n\nHelp me hand out more fruit of the arcan'dor - each one is a life free from slavish dependence on the Nightwell!\n\nAfterwards, we shall speak on how best to assist our new allies in their siege.", objectives = "" }
WordHunterWoW_QuestEN[45266] = { title = "A United Front", description = "Our rebel fighters have been armed and morale is high - even the Alliance and Horde elves have ceased their squabbling.\n\nWe are nearly ready to march on the city.\n\nHand out this week's fruit, and then we can begin preparations.", objectives = "" }
WordHunterWoW_QuestEN[45267] = { title = "Before the Siege", description = "So many years of my life spent studying within the Nighthold... \n\nNever had I considered that I would one day have to fight my way back in.\n\nTime is short. The battle will be upon us soon. \n\nPlease, continue our tradition and feed another refugee the fruit of the arcan'dor.", objectives = "" }
WordHunterWoW_QuestEN[45268] = { title = "The Advisor and the Arcanist", description = "This new First Arcanist appointed by Elisande. This... Andaris. If she is as dangerous as I have heard, then Ly'leth may well be lost.\n\nI am sorry, I should not entertain such thoughts. It is just that we have received a troubling message.\n\nHelp me distribute the latest batch of the arcan'dor fruit, then we will discuss the message.", objectives = "" }
WordHunterWoW_QuestEN[45269] = { title = "A Taste of Freedom", description = "We are as ready as we will ever be. Once we put Valtrois' plan into action, we can attack the Sanctum of Order and put an end to Andaris. She will never expect us to have trained our withered against fel magic, and her hubris will be her downfall.\n\nCome, let us feed the people one last time.", objectives = "" }
WordHunterWoW_QuestEN[45271] = { title = "Insurrection", description = "First Arcanist Thalyssra has received dark tidings regarding the Nightfallen rebellion and requires your assistance.\n\nJourney to Shal'Aran in Suramar and meet with her.", objectives = "" }
WordHunterWoW_QuestEN[45272] = { title = "Insurrection: Missing Persons", description = "First Arcanist Thalyssra has requested your aid in searching for her missing people.\n\nShe has a lead from a very unexpected ally.\n\nMeet with her at Shal'Aran in Suramar.", objectives = "" }
WordHunterWoW_QuestEN[45277] = { title = "Insurrection: Waxing Crescent", description = "First Arcanist Thalyssra has sent word: there has been communication from Ly'leth. Your help is needed.\n\nJourney to Shal'Aran in Suramar and lend what aid you can.", objectives = "" }
WordHunterWoW_QuestEN[45278] = { title = "Insurrection: An Elven Problem", description = "The Alliance and Horde have arrived in Suramar. First Arcanist Thalyssra needs your help in providing an introduction.\n\nMeet with Thalyssra in Shal'Aran.", objectives = "" }
WordHunterWoW_QuestEN[45280] = { title = "Insurrection: Crafting War", description = "Refugees are flooding in to Shal'Aran, and many are willing to fight for Thalyssra's rebel army.\n\nThey need weapons, training and help from anyone who can provide it.\n\nGo to Shal'Aran and lend your assistance.", objectives = "" }
WordHunterWoW_QuestEN[45281] = { title = "Insurrection: March on Suramar", description = "First Arcanist Thalyssra has sent word: the time has come to launch our assault on Suramar. The elven armies of the Horde, Alliance, Kirin Tor and Nightfallen are assembled.\n\nThey only await your arrival to begin their assault.\n\nReport to Shal'Aran and meet with First Arcanist Thalyssra and prepare for battle.", objectives = "" }
WordHunterWoW_QuestEN[45282] = { title = "Insurrection: Elisande's Retort", description = "The combined forces of the elves stand ready to begin their siege on the gates of the Nighthold.\n\nReport to First Arcanist Thalyssra in Shal'Aran to begin the siege.", objectives = "" }
WordHunterWoW_QuestEN[45285] = { title = "Insurrection: As Strong As Our Will", description = "In the wake of Elisande's attack, the need is stronger than ever to add to the ranks of the Nightfallen rebellion.\n\nPlans are in motion that may help with this in an unconventional way.\n\nReport to First Arcanist Thalyssra in Shal'Aran for more details.", objectives = "" }
WordHunterWoW_QuestEN[45287] = { title = "Insurrection: Breaking the Nighthold", description = "First Arcanist Thalyssra sends word that her forces are ready. It is time for you to lead the attack against the Nighthold.\n\nReport to Shal'Aran in Suramar for details.", objectives = "" }
WordHunterWoW_QuestEN[45291] = { title = "Return to Karazhan: Book Wyrms", description = "My incorporeal condition has allowed me to enter the tower safely for the first time. I must say, it's a bit of a shambles in there!\n\nI could use some help tackling my cleaning checklist. We should start with the library. All those musty tomes are bound to attract mana wyrms!\n\nPlease shelve any books that have fallen to the floor, or worse, taken flight. And if you find mana wyrms nibbling at the pages... step on them!", objectives = "" }
WordHunterWoW_QuestEN[45292] = { title = "Return to Karazhan: Rebooting the Cleaner", description = "The Guardian Medivh created the Curator to watch over Karazhan, but I fear the unit is behaving erratically. Prolonged periods of operation may have caused a malfunction.\n\nPlease go up to the Menagerie and disable the Curator. Also, search the area for a box of spare motivator crystals and return to me.\n\nEven with my basic knowledge I should be able to replace its motivator, and we can enlist the Curator's help in cleaning up the tower.", objectives = "" }
WordHunterWoW_QuestEN[45293] = { title = "Return to Karazhan: New Shoes", description = "Thus far my Karazhan cleanup project hasn't exactly been a rousing success. Time to try something new.\n\nNew, as in new shoes... horseshoes, that is! A box of horseshoes was left outside the tower. It's a problem finding a delivery person willing to set foot inside... mortality rates being what they are.\n\nIf you would, grab the crate and take it to Koren in the stables. Just be careful passing Attumen. The huntsman doesn't take kindly to outsiders.", objectives = "" }
WordHunterWoW_QuestEN[45294] = { title = "Return to Karazhan: High Stress Hiatus", description = "The new plays in the opera house have been well received by everyone... except cast members of the older shows. Egos are bruised and tensions are running high!\n\nRomulo and Julianne are ready to poison each other.\n\nTinhead is rusting with tears over his lack of adoration.\n\nLittle Red's cape was stolen by a disgruntled understudy, who ran off to play chess of all things.\n\nActors, am I right? We need them ready to perform in case the audience demands a revival. Please, help me calm their nerves!", objectives = "" }
WordHunterWoW_QuestEN[45295] = { title = "Return to Karazhan: Clearing Out the Cobwebs", description = "I admit it... even as a spirit, I am deathly afraid of spiders. All those legs! Dripping fangs! Sticky webs coming out of their...\n\n<Darius does a squirming sort of shimmy that is uncomfortable to watch.>\n\nI'm sure a world-saving hero like you doesn't mind them, though. Which is good, since a whole brood of spiders has taken over the Servant's Quarters.\n\nYou'll handle this, right? If you don't get them all, they'll keep multiplying.", objectives = "" }
WordHunterWoW_QuestEN[45296] = { title = "No Bones About It", description = "The Charred Bone Fragments still smolder with ancient power. Darius would be extremely interested in examining them and hearing of your defeat of Nightbane.", objectives = "" }
WordHunterWoW_QuestEN[45301] = { title = "Taking Charge", description = "Mardum has been quiet for months. I wonder why the Legion is attacking us now? Could be in retaliation for destroying their battleship on the Broken Shore...\n\nWe had better head down ourselves and save the day, don't you agree?", objectives = "" }
WordHunterWoW_QuestEN[45304] = { title = "Attacking the Darkness", description = "Your champions have returned looking somewhat shaken by their encounter with the Shadowmaster.", objectives = "" }
WordHunterWoW_QuestEN[45312] = { title = "You Beat the Ball of Meat", description = "Your champions return with a scrap of bloody, tangled, and quite smelly hair.", objectives = "" }
WordHunterWoW_QuestEN[45316] = { title = "Stabilizing Suramar", description = "Elisande's plan has backfired. She thought to stamp out our rebellion by making an example of the Waning Crescent. \n\nInstead, she ignited the flame of the shal'dorei better than I ever could.\n\nWe must maintain a cohesive campaign against Elisande and the Legion by fighting them in every corner of Suramar. \n\nShow the people that there is still hope - that there are still heroes willing to fight for them!", objectives = "" }
WordHunterWoW_QuestEN[45317] = { title = "Fighting on All Fronts", description = "We are nearly ready to siege the gates. Your efforts here have been monumental, {name}.\n\nBut let us not forget that you are also the {class}t. Your forces rely on you to command them. No single person can stand against the Legion.\n\nContinue your duty. Guide the {class}s of Azeroth, and victory will be assured.", objectives = "" }
WordHunterWoW_QuestEN[45329] = { title = "Operation: Portals", description = "This is a serious invasion, but nothing a Slayer like you can't handle. Time to put those weapons to work!", objectives = "" }
WordHunterWoW_QuestEN[45330] = { title = "Scouting Party", description = "We will have our work cut out for us finding the missing scouts and Lady S'theno. I suspect that one does not wish to be found.\n\nDo your best, {name}!", objectives = "" }
WordHunterWoW_QuestEN[45331] = { title = "Return to Acherus", description = "You've grown a lot since we last met, {name}. Now that we have the harness, let's see if Mograine has a plan to use it.", objectives = "" }
WordHunterWoW_QuestEN[45339] = { title = "Defense of the Fel Hammer", description = "We need to get back to the Fel Hammer ASAP!", objectives = "" }
WordHunterWoW_QuestEN[45342] = { title = "Administering Aid", description = "Unfortunately, it would seem many of your allies have already taken to fighting on these fel corrupted shores. \n\nThey will never be able to gain the upper hand in battle while so many are suffering from the contagion. \n\nTake the counteragent and use it to administer aid to your allies. \n\nRoland and I will handle the injuries here.", objectives = "" }
WordHunterWoW_QuestEN[45343] = { title = "A Curious Contagion", description = "It has been brought to my attention that a rather curious contagion is spreading through a small coastal region within Highmountain.\n\nThe local tribes have abandoned the area for fear of catching this ailment that currently has no known cure.\n\nOne of our own was traveling through the area when her companion fell ill. She has requested the Conclave's assistance. Seek her out, High Priest, and do whatever you can to stop this sickness from spreading.", objectives = "" }
WordHunterWoW_QuestEN[45344] = { title = "Sampling the Source", description = "My companion has fallen terribly ill, as you can see. \n\nHe must have caught whatever these taurens had. Their entire camp has been wiped out!\n\nIt appears to be fel in origin, and impervious to all known treatments. \n\nI've been working tirelessly to find a cure, but I don't think Roland here has much time left. \n\nI could use an extra hand. Some samples from the source should speed things up. \n\nJust be sure to avoid direct contact with the contagion. Levitate should be helpful.", objectives = "" }
WordHunterWoW_QuestEN[45345] = { title = "Mischievous Sprites", description = "It's a little-known secret that the dust sprites use for their various tricks has restorative properties.\n\nSome within the alchemy community balk at this claim, but they only refute it because they've never been able to get their hands on the rare ingredient.\n\nSprites often shroud themselves in illusions to avoid detection.\n\nThe nearby goats have a curious shimmer about them that suggests they may be sprites in disguise.\n\nDispel whatever magic surrounds them to reveal their true form.", objectives = "" }
WordHunterWoW_QuestEN[45346] = { title = "Shambling Specimens", description = "This fel contagion appears to have three stages.\n\nThe first is marked by a persistent, phlegmy cough.\n\nThe second shows the skin turning a sickly shade of green.\n\nThe third involves a complete transformation where the victim turns into a mindless corpse. It is within this stage that I believe the most information about the sickness can be gathered.\n\nI have a contraption that can safely store the specimens, but they will need to be shackled before they can be collected.", objectives = "" }
WordHunterWoW_QuestEN[45347] = { title = "Crafting a Cure", description = "I used what you gathered for me to craft what I hope will be a reliable cure. The only thing that's missing is some powerful magic, which I hope you'll be able to provide.\n\nThe concoction is there on my alchemy table.\n\nPlease hurry, {name}. Roland grows weaker by the minute.", objectives = "" }
WordHunterWoW_QuestEN[45348] = { title = "Safekeeping", description = "It would seem that a delicate balance of holy and shadow magic is the key to curing this contagion. Obviously the remedy will need a bit of work to reduce undesired side effects, like dying.\n\nIn the meantime, take the counteragent back to Netherlight Temple and keep it safe. I will work diligently on discovering the source of this contagion.", objectives = "" }
WordHunterWoW_QuestEN[45349] = { title = "To the Broken Shore", description = "We've received word from those fighting on the Broken Shore. It seems the source of the contagion can be pinpointed to a specific island off the western coast.\n\nMany of our allies have already been infected. We must work quickly to ensure that the contagion doesn't spread.", objectives = "" }
WordHunterWoW_QuestEN[45350] = { title = "Countering the Contagion", description = "I have tracked the source of the contagion to these very shores. The Burning Legion are using fel spreaders to pump out infectious fel creep, causing anyone who comes into contact with it to become sick.\n\nTake out Ozzuk the Corrupter and his fel spreaders so that the contagion can be contained.", objectives = "" }
WordHunterWoW_QuestEN[45354] = { title = "Dispersion of the Discs", description = "These discs are radiating with power! It must be their proximity to one another. We must take them from here should they resonate further and cause a catastrophe in these sacred halls.\n\nI'll send them to the one place I know where we can reign their energies in, preventing any sort of explosion. I'm speaking of the Eye of Eternity.\n\nThere we will be able to safely finish what Antonidas was unable to complete. Speak with me again when you're ready to leave.", objectives = "" }
WordHunterWoW_QuestEN[45372] = { title = "Fate of the Nightborne", description = "Shortly after your victorious return from the Nighthold, urgent business took Thalyssra back to the palace.\n\nShe has requested that you meet her there.\n\nSpeak to me when you are prepared to join her.", objectives = "" }
WordHunterWoW_QuestEN[45381] = { title = "The Nighthold: Talisman of the Shal'dorei", description = "When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman's power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell's power, we could locate the talisman and end this foolish war...", objectives = "" }
WordHunterWoW_QuestEN[45382] = { title = "The Nighthold: Talisman of the Shal'dorei", description = "When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman's power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell's power, we could locate the talisman and end this foolish war...", objectives = "" }
WordHunterWoW_QuestEN[45383] = { title = "The Nighthold: Talisman of the Shal'dorei", description = "When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman's power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell's power, we could locate the talisman and end this foolish war...", objectives = "" }
WordHunterWoW_QuestEN[45385] = { title = "We Must be Prepared!", description = "The Legion ships are gone, for now. It's only a matter of time before they attack again, and we must be prepared.\n\nWe need to get going on repairs immediately! Lady S'theno took the lead on the search for parts. That one will do anything to remain on solid ground, ha! \n\nShe is waiting for you on the Broken Shore.", objectives = "" }
WordHunterWoW_QuestEN[45386] = { title = "Imminent Launch", description = "Shadow {name}, what a relief!\n\nWe have alarms set up throughout Gnomeregan to detect any unauthorized personnel while we finish de-irradiating the city.\n\nJust about every single one was tripped in the past few hours.\n\nBased on your recon, it's a safe assumption that Thermaplugg is down there, and he has enough firepower with him to decimate anywhere he pleases!\n\nDon't worry, I can get you to Gnomeregan. Talk to the High Tinker once you're there and do whatever it takes.\n\nFor Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[45391] = { title = "Champion: Lady S'theno", description = "", objectives = "" }
WordHunterWoW_QuestEN[45392] = { title = "Dark Memento", description = "The flowers were... a nice gesture.\n\n<Velonara sniffs one of the black roses.>\n\nI have a spare hood. Nothing fancy, but perhaps Moorgoth would like to have it.\n\nJust don't let him get his hopes up or anything. I'm merely repaying a kindness.\n\nI would appreciate it if you kept all this between us. Giving presents to admirers falls a bit outside the dark ranger rules of conduct.", objectives = "" }
WordHunterWoW_QuestEN[45397] = { title = "Fire the Cannons!", description = "It will take more than a damn shipwreck to bring me down. Those overgrown, vomit-reeking, demon felbags have another thing coming if they think that's all it's gonna take to stop me.  \n\n<Keeshan coughs up seawater, wiping his mouth dry with his sleeve.>\n\nUghh... I may need a little breather though. Here, take this flare gun and use it to call down artillery strikes on the beach. Rain hell on those worthless, half-goat bastards and I'll rendezvous with you back at the base when the mission is complete!", objectives = "" }
WordHunterWoW_QuestEN[45398] = { title = "Harnessing Power", description = "These fools are using the power of Rimefang's harness to subjugate the frost wyrms. Their leader, Andjor, sits inside on the back of the broodmother and mocks us.\n\nHe should breathe no longer.", objectives = "" }
WordHunterWoW_QuestEN[45399] = { title = "Severing the Sveldrek", description = "So here's the order of things, as far as I've been told. Mortal walks into Icecrown. Mortal is brutally defeated. Mortal gets raised as Scourge.\n\nThese fools can't expect to trounce in here, do whatever they want, and leave without any consequence. Time to make them truly as mindless as they act.", objectives = "" }
WordHunterWoW_QuestEN[45404] = { title = "Panic at the Brewery", description = "We were not prepared for a surprise attack. I fear Brewmaster Blanche has been captured, or worse...\n\nPlease help me, Grandmaster!", objectives = "" }
WordHunterWoW_QuestEN[45405] = { title = "Breaching the Sanctum", description = "It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area.\n\nTake these telemancy orbs. If you find you need support, use them to summon Withered.\n\nWe must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.", objectives = "" }
WordHunterWoW_QuestEN[45406] = { title = "The Storm's Fury", description = "No longer do we have time to prepare, the moment of action is upon us!\n\nCome with me, little one. With you guiding my aim we shall cleanse this isle by thunder and lightning!", objectives = "" }
WordHunterWoW_QuestEN[45412] = { title = "Protection: Aid of the Illidari", description = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city.\n\nKor'vas Bloodthorn of the Illidari has taken to patrolling the city streets on her own to find the source behind the recent attacks.\n\nI do not entirely trust these 'demon hunters', but they have at least proved adept at their namesake. I suggest you find her and see what she has uncovered before the Legion strikes once more.\n\nSpecialization: Protection Warrior", objectives = "" }
WordHunterWoW_QuestEN[45413] = { title = "Gathering Information", description = "The Legion has sent one demon after another to try to break into the Kirin Tor vaults in the city, but we don't know what they're after.\n\nLooks like they finally made it in.\n\nWe need to find out what was taken, and quickly, before they get a chance to put whatever it is to use.\n\nProbe any survivors for information - I'll use my spectral sight to make sure there aren't still any straggling demons lurking about.", objectives = "" }
WordHunterWoW_QuestEN[45414] = { title = "Confirming Suspicions", description = "That heart is the last remaining piece of Highlord Kruul - once one of the Legion's best warlords.\n\nMany years ago Kruul's armies nearly descended upon the Dark Portal to crush the Azerothian assault on Outland. We Illidari intercepted before he could strike.\n\nI fear that the Legion aims to use the heart to hasten Kruul's resurrection in the nether. We must find the Prophet Velen at once - only he can tell us for sure.", objectives = "" }
WordHunterWoW_QuestEN[45415] = { title = "Between Worlds", description = "Kruul boasts damnation, but his power has not yet fully manifested. His minions have taken his heart to hasten his rebirth in the nether.\n\nWe do not have much time.\n\nGo to the place of Kruul's fall at the Stair of Destiny in desolate Outland, where the link to his soul is strongest. There you must pry open the way to his realm.\n\nI must prepare for the battle to come. Good luck, champion.", objectives = "" }
WordHunterWoW_QuestEN[45416] = { title = "The Highlord's Return", description = "I have a missive for you from Kor'vas, as well as instructions for getting you there.\n\nI can teleport you to them to begin the fight, but you will need some Nethershards to force your way into the Twisting Nether.\n\nWhen you have enough, speak with me and you can begin.", objectives = "" }
WordHunterWoW_QuestEN[45417] = { title = "The Nighthold: Lord of the Shadow Council", description = "As we speak, Gul'dan is using the Nightwell's power to pull Sargeras into our world.\n\nGather your companions and fight your way to the top of The Nighthold.\n\nI will prepare Light's Heart and join you when the time is right.\n\nTogether, we will put an end to Gul'dan once and for all.", objectives = "" }
WordHunterWoW_QuestEN[45420] = { title = "The Nighthold: The Eye of Aman'Thul", description = "The battle is won, but the war is far from over.\n\nIn order to stem the tide of demons flooding into Azeroth, we must use the Pillars of Creation to seal the Tomb of Sargeras.\n\n<Khadgar peers down at the Eye of Aman'Thul.>\n\nThat... might be difficult to carry.\n\nPerhaps I can use the power of the Eye itself to teleport it to Dalaran. I suppose there is only one way to find out!", objectives = "" }
WordHunterWoW_QuestEN[45423] = { title = "Wailing Critters", description = "I'm glad you're here, {name}.\n\nTiny wails have been heard in the caverns for some time since Naralex was awakened. At first, we suspected that some deviate critters had survived. Upon further investigation, we found them to be growing and multiplying beyond our wildest expectations. The corpse of Verdan the Everliving may have something to do with it, we're not sure. That's why we're sending you in.\n\nI've also seen suspicious footprints leading into the caverns recently. We may not be alone, be careful.", objectives = "" }
WordHunterWoW_QuestEN[45425] = { title = "Grovebound", description = "Now THAT was some good stuff right there. Now that we've taken out the commander, the druids and the ancients should be safe for a while. Revenge was an added bonus.\n\nWe should get back to Rensar and tell him what we accomplished.", objectives = "" }
WordHunterWoW_QuestEN[45426] = { title = "Nature's Advance", description = "{name}, you must return to the Dreamgrove and bring the news of my attack. Tell the other druids that aggressions such as this will continue against us unless we find a way to stop the Legion.\n\nI thank you for the aid. I feel the fel energies leaving my veins, though it may take some time.", objectives = "" }
WordHunterWoW_QuestEN[45437] = { title = "An Urgent Situation", description = "Archmage, {name}! We have an important guest. Please meet me in my chamber when you have a moment.", objectives = "" }
WordHunterWoW_QuestEN[45440] = { title = "A Brewing Situation", description = "Greetings, Grandmaster. I'm an expert at producing tricky brews, and Almai and I have been working with Stormstout Brewery to craft Storm Brew for the order. \n\nIn fact, we have already begun production!\n\nThat calls for a party, don't you think? We brought enough of my prized Celebration Brew for everyone!", objectives = "" }
WordHunterWoW_QuestEN[45441] = { title = "Adacic Grubs - REWORK", description = "Your request to harvest wood does not seem unreasonable, {name}. There is something you can do for me, too.\n\nThere is a species of moth whose grubs feed on trees. Normally their numbers are too low to cause damage, but once a century they reproduce in overwhelming numbers. \n\nThey have just begun their mass emergence. All of my keepers are fighting the nightmare and cannot be spared. I fear I am unable to protect the forest giants on my own.\n\nWill you stomp the grubs out?", objectives = "" }
WordHunterWoW_QuestEN[45442] = { title = "Not Felling Well", description = "Let's see... Yseralline Seed for healing, Bruiseweed for curing poison, and Elemental Earth for disease resistance. Oh and just a touch of ground Felwort for attunement. \n\nYes, I think this will counteract the Legion's poison. It will probably taste terrible, but what medicine doesn't?\n\nHurry, Grandmaster {name}. Our most stricken friends don't have much time left.", objectives = "" }
WordHunterWoW_QuestEN[45449] = { title = "Alchemist Korlya", description = "The zealots within the Garrison of the Fel are led by Alchemist Korlya. It seems likely that's the Felskorn Brewmaster Blanche observed poisoning our brew.\n\nPlease kill her.", objectives = "" }
WordHunterWoW_QuestEN[45459] = { title = "Storming the Legion", description = "I did my best to fight the demons off, but there were too many even for my skill...\n\nAs I lay dying, I overheard the dreadlord commanding a Felskorn alchemist to contaminate my brew and then return to the Broken Shore. \n\nIf you could acquire some of the poison, I'm sure we can concoct an antidote!", objectives = "" }
WordHunterWoW_QuestEN[45482] = { title = "Arcane: Fate of the Tideskorn", description = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion.\n\nIt complicates matters that this vrykul may in fact be Skovald's heir.\n\nTake the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start.\n\nSpecialization: Arcane Mage", objectives = "" }
WordHunterWoW_QuestEN[45486] = { title = "The Reluctant Queen", description = "Wait, how is it you know about my parentage? Be careful what you say around here, there are those who would hunt me down if they knew my bloodline.\n\nI don't know who you are, nor do I believe I'm part of any prophecy. However, if you seek to undo the damage my father has wrought on the Tideskorn, then I feel obliged to assist you.\n\nMeet me in Valdisdall, {class}. From there we can make our way to Skold-Ashil and request an audience with Eyir. Perhaps she can shed some light on this prophecy.", objectives = "" }
WordHunterWoW_QuestEN[45498] = { title = "Let Sleeping Dogs Lie", description = "You see those big eredar guys? That's the barrow that Goldrinn is in! I don't know what the Legion is doing to him in there, but I'm sure we don't want them to succeed.\n\nLet's get in there and save Goldrinn!", objectives = "" }
WordHunterWoW_QuestEN[45522] = { title = "To Silence the Bonespeakers", description = "Sigryn's claim to the throne will be challenged by two rivals - Runeseer Faljar of the Bonespeakers and Jarl Velbrand of the Drekirjar.\n\nI would begin in Haustvald with the Runeseer. He was a close ally of Skovald and is a powerful mystic. With the Bonespeakers at his charge, he would prove a staunch opponent if he cannot be made to yield.\n\nGo now, and claim your destiny in the name of the Valkyra!", objectives = "" }
WordHunterWoW_QuestEN[45523] = { title = "To Tame the Drekirjar", description = "The Bonespeaker's words trouble me, outsider. The darkness he speaks of, Skovald's fel curse, could he have passed it onto me somehow?\n\nNo, it cannot be so. The Runeseer must be mistaken...\n\nCome, the next challenger awaits. I will no doubt need your assistance bringing him to heel as well.", objectives = "" }
WordHunterWoW_QuestEN[45524] = { title = "The Forgotten Heir", description = "My brother... lives?\n\nThe last time I saw him, the assassins were closing in on him. I can't imagine how he defeated them...\n\nWe should travel to Vrekt. I would look upon my brother with my own eyes.", objectives = "" }
WordHunterWoW_QuestEN[45525] = { title = "Unanswered Questions", description = "What is done, is done. There are none left to challenge the throne of the Tideskorn. \n\nMy brother's words still haunt me, though. If Eyir knows who ordered my family killed, I deserve to know it.\n\nCome, let us return.", objectives = "" }
WordHunterWoW_QuestEN[45526] = { title = "The God-Queen's Fury", description = "{class}t, the Kirin Tor have found a way to get you into the Halls of Valor to pursue the God-King's heir. Archmage Khadgar has asked me to stress upon you the importance of stopping Sigryn, as the prophecies hint that she may still be the key to uniting the Tideskorn against the Legion.\n\nIt will require an incredible amount of energy to teleport you directly to the Halls, so be sure that you are prepared. It may be some time before we can send you again.\n\nSpeak to me when you are ready to proceed.", objectives = "" }
WordHunterWoW_QuestEN[45527] = { title = "Eyir's Forgiveness", description = "I'm sorry for everything I've put you through, outsider. After my actions here, I fear all of this may have been in vain.\n\nCome with me back to Skold-Ashil. There I will accept whatever judgment Eyir  deems fit of me.", objectives = "" }
WordHunterWoW_QuestEN[45528] = { title = "The Befouled Barrows", description = "You were taking too long, so I took the liberty to scout out the barrows in advance. The Legion has set up portals, pulling more and more demons through them by the second. We need to shut them down so we can save Goldrinn!\n\nI'm not sure my usual methods are going to do much to take them down, but I think you can do it! I think some nice vine-work is in order.", objectives = "" }
WordHunterWoW_QuestEN[45532] = { title = "Mother's Orders", description = "That big ugly thing looks like it's leading the attack here. Let's take her down!", objectives = "" }
WordHunterWoW_QuestEN[45534] = { title = "A Common Enemy", description = "I have one more request to ask of you, outsider.\n\nReturn to your leaders and report to them what transpired here.  Though your people may never truly be allies with the Tideskorn, know that we have a common enemy - one which my people will fight to the last vrykul. \n\nWhen the time comes, I hope to see you on the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[45536] = { title = "2v2 Weekly Quest UI", description = "", objectives = "" }
WordHunterWoW_QuestEN[45537] = { title = "3v3 Weekly Quest UI", description = "", objectives = "" }
WordHunterWoW_QuestEN[45538] = { title = "10v10 Weekly Quest UI", description = "", objectives = "" }
WordHunterWoW_QuestEN[45539] = { title = "Pet Battle Challenge: Wailing Caverns", description = "The deviate critters of the Wailing Caverns continue to flourish in the damp darkness, but I've been doing my best to keep their numbers down.\n\nI've found a few pets and supplies while clearing out the caverns, I might be willing to part with a sack of supplies if you can beat my best run.\n\nYou'll have to clear out the cavern without healing or reviving any of your pets to best me. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[45540] = { title = "A Call from the Caverns", description = "Oh, good, I'm glad you stopped by. We've heard disturbing rumors of corruption continuing to flourish in the Wailing Caverns. You seem like just the right person to investigate.\n\nSince Naralex's awakening, one of his disciples has been watching over the area to ensure that deviate creatures remain in check. She is the one that has been sending us these dire warnings.\n\nMeet up with her in the eye of the skull-shaped rock above Wailing Caverns and see if you can help her handle this situation.", objectives = "" }
WordHunterWoW_QuestEN[45545] = { title = "Barrel Toss", description = "The Legion is defending the Felskorn lair with fel emitters. Fortunately we have Storm Brew to spare, so there should be plenty available with which to destroy them. \n\nTake this barrel, throw it at the spreaders, and watch them go BOOM!", objectives = "" }
WordHunterWoW_QuestEN[45551] = { title = "Devastating Effects", description = "The Burning Legion will not rest until they have destroyed everything and everyone. Their presence here has had a devastating effect on our lands, and now it seems our wildlife as well. \n\nI have heard numerous reports of sickly animals in the thicket that surrounds the demon-infested city of Suramar. \n\nMake your way there and see if the rumors are true.", objectives = "" }
WordHunterWoW_QuestEN[45552] = { title = "Soothing Wounds", description = "<D'Bynn's injuries prevent him from moving.>\n\nPerhaps you can forage something nearby that will soothe the manasaber's wounds?", objectives = "" }
WordHunterWoW_QuestEN[45553] = { title = "The Nighthuntress Beckons", description = "<D'Bynn becomes alert at the sound of his master's voice. Using his muzzle, he nudges your hand with a sense of urgency, inviting you to hop on his back.>", objectives = "" }
WordHunterWoW_QuestEN[45554] = { title = "Taking Control", description = "I've been withering away in this cage, prisoner to a wretch called Reyln.\n\nHe leads a group of nightborne that are using fel magic to corrupt and control the native wildlife.\n\nThe Burning Legion's reach has already spread too far for my liking.\n\nKill him and recover his control orb, so I can be released from this arcane prison!", objectives = "" }
WordHunterWoW_QuestEN[45555] = { title = "Felbound Beasts", description = "So Reyln is taking orders from Lexera? Why am I not surprised. She seemed far too comfortable with the demons who infested our city.\n\nWe cannot let her succeed in corrupting Suramar's wildlife. I swore to protect the city of Suramar from all enemies, even those within its walls.\n\nIf you can deal with her trappers, I will do my best to track Nighthuntress Lexera down.", objectives = "" }
WordHunterWoW_QuestEN[45556] = { title = "Ready to Strike", description = "I followed one of the trappers, who unknowingly led me to the Broken Shore. \n\nLexera was there, surrounded by an army of demons and loyal nightborne.\n\nI wasn't able to get close, but from what I could tell, she and her army of trappers are taming the fel-corrupted beasts.\n\nIt is an abomination of nature, and she must be stopped!\n\nMeet me on the Broken Shore and be ready to strike. I will gather additional manaroot. I have a feeling we'll need it.", objectives = "" }
WordHunterWoW_QuestEN[45557] = { title = "Unnatural Consequences", description = "Lexera and her trappers have taken over the valley.\n\nShe is stronger than she looks, {name}, and she fights with the strength of a dreadlord. Do not go in unprepared. \n\nI can handle these demons. Go, find Lexera, and make her feel the consequences of her unnatural endeavors.", objectives = "" }
WordHunterWoW_QuestEN[45560] = { title = "Destruction: Rumblings Near Feltotem", description = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later.\n\nThe drogbar chieftain, Navarrogg, is handling this personally and we'd like you to meet him near the Feltotem village.\n\nSpecialization: Destruction Warlock", objectives = "" }
WordHunterWoW_QuestEN[45561] = { title = "Seek Me Out", description = "The letter from Maximillian is written on something which looks to be torn off a ship's sail. Included are directions to the beach in northern Highmountain.", objectives = "" }
WordHunterWoW_QuestEN[45562] = { title = "Kneel and Be Squired!", description = "You must kneel before me if we are to begin our journey together once more. Kneel, squire, and be squired!", objectives = "" }
WordHunterWoW_QuestEN[45563] = { title = "The Shrouded Coin", description = "A swirling mist envelops the coin and it begins to float above your hand. The mist briefly parts to reveal a shiny new coin, yet in the next instant the coin appears worn from years of exchange. As the coin settles back in to your hand, visions of jungles and mist shrouded peaks waft into your mind, and through the vision you recognize the four Celestials gathered in the courtyard of an island.", objectives = "" }
WordHunterWoW_QuestEN[45564] = { title = "The Burning Birds", description = "The Feltotem are experimenting on these falcosaurs! They didn't get the results that they wanted and have carelessly left their experiments lying around to further poison the animals.\n\nWe should collect their leftover totems to prevent further corruption and to find out what they were doing.", objectives = "" }
WordHunterWoW_QuestEN[45565] = { title = "Further Training", description = "The journey here was perilous, Squire. It was fraught with danger. Storms, demons, storm demons... I shudder at the memory. Of course, I overcame all such dangers at great loss to my person. This is where I need your assistance.\n\nYou must venture forth--nay, sally forth--and recover my armor, my weapon, and of course my grand steed. Once you have successfully completed these tasks three, will you be promoted to Squire, First Class!", objectives = "" }
WordHunterWoW_QuestEN[45566] = { title = "A Knight's Belongings", description = "Amidst the squalls and the crashing waves, my mighty ship swayed and tumbled. Lesser knights would have trembled in terror, frozen stiff. Not me! Nay! Heroically, I stripped my armor off my back and stored it safely in my sack. \n\nWhy did I strip down to these simple undergarments, you ask? Only an ignorant squire would. I was wary of sinking to the bottom should my ship fall foul of course! Ha ha! \n\nUnfortunately, the sacks of armor were thrown overboard by the waves.", objectives = "" }
WordHunterWoW_QuestEN[45567] = { title = "My Kingdom for a Horse", description = "Oh, woe is me! Soon after making landfall I began exploring, riding my trusty steed Pimento into the heart of a demon infested village to the north. While performing my investigations, I tied Pimento up to go further on foot, only to return and discover a powerful demon had captured her! There he was, riding her like she was his own. Please find her and send her back to me.", objectives = "" }
WordHunterWoW_QuestEN[45568] = { title = "They Stole Excaliberto!", description = "I was scouting the nearby demon village when I was attacked. They took my artifact! Of course, if I leave here, the shore will be undefended. The nearby demons have it. Go, slay them and bring it back to me!", objectives = "" }
WordHunterWoW_QuestEN[45570] = { title = "In Safer Hands", description = "There is still the matter of the Focusing Iris. Please return it to  your Kirin Tor friends, with my apologies.\n\nAs for myself, I think I'm done chasing artifacts for a while. One possession by immortal shadowy evil is enough for me, thank you.", objectives = "" }
WordHunterWoW_QuestEN[45571] = { title = "A Bit of Espionage", description = "With the gunpowder in tow, it's time to move on to our next plan. Meet us on the Broken Shore. \n\nYou can get a flight directly to our next location from Krasus' Landing. We will meet you there, {class}t.", objectives = "" }
WordHunterWoW_QuestEN[45572] = { title = "Holding Our Ground", description = "Though we anticipated a strong Legion presence, our attacks on their camps have angered their forces even further than anticipated. Our forces rally on both land and in the skies above Thunder Totem in an attempt to regain our footing.\n\nDo what you can to reduce their forces. Once we've secured Thunder Totem we'll begin our plan for a final attack.", objectives = "" }
WordHunterWoW_QuestEN[45573] = { title = "Rise Up", description = "Here we are, {class}t. On this island is a cavern full of exceptionally powerful demons and their leaders. If our plan succeeds, these demons will be... \"blown to smithereens\", as Tethys so nicely put it.\n\nThere's no time to explain the plan in full right now, but Tess has agreed to walk you through it. First you must get up to the top of this ramp. Slaughter a few on your way.", objectives = "" }
WordHunterWoW_QuestEN[45574] = { title = "Fel Ingredients", description = "Our scouts have located a Felskorn encampment within the Garrison of the Fel. We will need as many samples of fel poison as we can find if we are to concoct a cure for our stricken monks.\n\nTake samples of anything that looks remotely useful!", objectives = "" }
WordHunterWoW_QuestEN[45575] = { title = "Village of the Corruptors", description = "The Feltotem continue to create these totems for further \"experiments\". Let us deal with these infusers in the traditional manner.\n\nTheir deaths will right a great wrong and provide clues as to their ultimate goal.", objectives = "" }
WordHunterWoW_QuestEN[45576] = { title = "Rise Up", description = "Here we are, {class}t. On this island is a cavern full of exceptionally powerful demons and their leaders. If our plan succeeds, these demons will be... \"blown to smithereens\", as Tethys so nicely put it.\n\nThere's no time to explain the plan in full right now, but Lilian has agreed to walk you through it. First you must get up to the top of this ramp. Slaughter a few on your way.", objectives = "" }
WordHunterWoW_QuestEN[45586] = { title = "Shield Amplification", description = "It will not hurt to reinforce the Nightborne Soulstone's shield just a bit more, and to do that we must infuse it with energy. \n\nRyanna has assured me that fel essence will work beautifully for our needs. Yes - this method IS rather distasteful. However as the sin'dorei well know, desperate times call for desperate measures.\n\nIt is as simple as this: we have an urgent need for magical energy, and our enemies possess it in abundance. \n\nDo what must be done.", objectives = "" }
WordHunterWoW_QuestEN[45587] = { title = "The Feltotem Menace", description = "If I had known Tugar was alive and behind this I would've alerted you sooner! He is a hateful creature, and an easy recruit to the Legion's cause.\n\nIf he is truly successful with his fel experiments we need to stop him now. He is taunting us from up there. Let's go!", objectives = "" }
WordHunterWoW_QuestEN[45614] = { title = "Lady Remor'za", description = "Our allies reported a coven of extremely powerful Felborne abjurers occupying the Weeping Terrace. \n\nTheir leader, Lady Remor'za, and her followers are specialists in ancient nightborne magic and can become nearly invincible to attacks. \n\nHowever, as mages, we should be able to defeat them using Spellsteal. Let us show them the power of the Tirisgarde!", objectives = "" }
WordHunterWoW_QuestEN[45615] = { title = "Finders Keepers", description = "Would you look at this place? It's a mess! Everywhere you look there's just pile after pile of arcane dust!\n\n<Akazamzarak smiles broadly.>\n\nThese poor saps don't realize what that stuff's worth!\n\nI tell ya what, if you help me summon up some brooms to collect this powdered gold, I'll split the profits with you 80/20.", objectives = "" }
WordHunterWoW_QuestEN[45627] = { title = "Feltotem's Fall", description = "Our Highmountain contact, Navarrogg, reports that Tugar Bloodtotem has finally resurfaced.\n\nHe's sent a message crystal along with some instructions for me.\n\nI can teleport you to Navarrogg and he will take you to Tugar's location, but there is one problem.\n\nNavarrogg requires additional magical power to fend off Tugar's fel magicks. You will need some Nethershards before you go.", objectives = "" }
WordHunterWoW_QuestEN[45628] = { title = "This Time, Leave a Trail", description = "Are you ready, {class}t? I will walk you through every step of the plan. You'll be perfectly safe! First thing's first: You see that rappel point behind me? That's your way down into the cave. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[45629] = { title = "This Time, Leave a Trail", description = "Here goes nothing, {class}t. If anybody can pull this off, you can! ...Probably. Just use the rappel point behind me to get into the cave.\n\nWhat? Don't make that face. I'll give you more instructions once you're in the cave.", objectives = "" }
WordHunterWoW_QuestEN[45630] = { title = "Servant to No One", description = "I like workin' with ya, {name}. How's about we keep this gold train a-rollin'?\n\nArchmage Khadgar spends an inordinate amount of time sending his servants off to do who knows what. What if an enterprising duo such as ourselves found a cheaper alternative?\n\n<Akazamzarak hands you a small crystal.>\n\nThis bad boy will form a servant right out of thin air - and a few pounds of the dust you swept up.\n\nWhy not take it into town and try her out? See for yourself!", objectives = "" }
WordHunterWoW_QuestEN[45632] = { title = "Missing in Action: Eitrigg", description = "Are you familiar with Eitrigg? He is the worthy orc warrior who was leading our forces against the Felrage naga nearby.\n\nUnfortunately the naga captured many of our soldiers during a recent skirmish. Eitrigg went after them and has not returned. I fear something terrible has happened to him.\n\nPlease try to find him!", objectives = "" }
WordHunterWoW_QuestEN[45633] = { title = "Operation Felrage", description = "I do not like to see naga aligned with the Burning Legion. That is something new and cannot be ignored.\n\nThe naga warlord, Kaz'jatar, and his skrog toady, Felbeard, are responsible for the Felrage's attacks on our forces.\n\nWe must teach them that it does not pay to consort with demons!", objectives = "" }
WordHunterWoW_QuestEN[45634] = { title = "Kvaldir on Call", description = "You empowered Helya's Horn in Helheim, and now is the time to use it. I have located three Legion portals we should eliminate. \n\nSeek out the vrykul shipwreck on Felrage Strand. Call the kvaldir and have them do what they do best: destroy!", objectives = "" }
WordHunterWoW_QuestEN[45644] = { title = "Oh Doloria, My Sweet Doloria", description = "What ho! We are quite the dashing pair of adventurers, aren't we?\n\nNow that we have secured my belongings, a new path unfolds before us. I did not journey here simply to thwart the demon invasion, no! I came here in search of my beloved, my loved, Doloria. Whilst resting between slaying of dragons, I had a dream, nay, a vision. It told me Doloria had been kidnapped and taken to a floating city in the sky!\n\nIt must be Dalaran. Quickly, squire! Mount up and meet me at Dalaran's famous inn. Make haste!", objectives = "" }
WordHunterWoW_QuestEN[45645] = { title = "A Fool's Errand", description = "Oh yea sure, I'm, um, held here against my, you know, will, or something.\n\nLook bud, between you and me old Max here has no chance, but his heart is in the right place. I keep trying to run away and hide but he keeps finding me! I just don't have it in me to upset him with the truth.\n\nI've got an idea. Why don't you go kill some of those really big two headed \"Hill Bandits\" for me. Let's say they stole some jewelery from me, and you can use it to buy my freedom.\n\nTake your time, don't get hurt. Much.", objectives = "" }
WordHunterWoW_QuestEN[45647] = { title = "Mission: Search and Rescue", description = "I will make these naga pay for their audacity. \n\nThey and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor!\n\nWe must rescue our fallen soldiers before they are sold as slaves, or worse...", objectives = "" }
WordHunterWoW_QuestEN[45648] = { title = "Missing in Action: Lord Darius Crowley", description = "Are you familiar with Lord Darius Crowley? He is the worthy Gilnean warrior who was leading our forces against the Felrage naga nearby. \n\nUnfortunately the naga captured many of our soldiers during a recent skirmish. Lord Darius went after them and has not returned. I fear something terrible has happened to him.\n\nPlease try to find him!", objectives = "" }
WordHunterWoW_QuestEN[45649] = { title = "Mission: Search and Rescue", description = "I will make these naga pay for their audacity. \n\nThey and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor!\n\nWe must rescue our fallen soldiers before they are sold as slaves, or worse...", objectives = "" }
WordHunterWoW_QuestEN[45650] = { title = "Operation Felrage", description = "I am very concerned to discover naga aligned with the Burning Legion. That is something new and cannot be ignored.\n\nThe naga warlord, Kaz'jatar, and his skrog toady, Felbeard, are responsible for the Felrage's attacks on our forces.\n\nWe must teach them that it does not pay to consort with demons!", objectives = "" }
WordHunterWoW_QuestEN[45652] = { title = "A \"Humble\" Request", description = "{class}t, we've received a... visitor. She orders entry, but the guards will not let her pass without approval.\n\nPlease head up to the overlook as soon as you are able.", objectives = "" }
WordHunterWoW_QuestEN[45706] = { title = "The Power of Thousands", description = "I know I am not well liked here, and my Grimtotem and I were not invited to join you and your shaman here. However, I come to you with a proposition.\n\nThe Legion is attacking my home. I've lost possession of some things that are... dear to me, and I have nowhere else to turn to. It pains me to ask... but I request your aid. If you help, I offer my people in service against the Legion.", objectives = "" }
WordHunterWoW_QuestEN[45723] = { title = "The Crone's Wrath", description = "These demons come into my home, take my things, and capture my people? They will see my wrath. Destroy them, child. Surely you are capable of at least that.", objectives = "" }
WordHunterWoW_QuestEN[45724] = { title = "Snakes and Stones", description = "When the demons attacked, they captured two very powerful possessions of mine: my companion Arikara and the Doomstone.\n\nWhile death matters not to Arikara, the Legion surely has ulterior plans for him. And the Doomstone... such an artifact of power belongs in my hands, not theirs. We must split up to find them.\n\nFor the world's sake, do be careful. I don't need you clumsily destroying everything.", objectives = "" }
WordHunterWoW_QuestEN[45725] = { title = "Breaking Chains", description = "The Legion shall not make fools of the Grimtotem. Free my people, and we will grace you with our aid in the coming battle.", objectives = "" }
WordHunterWoW_QuestEN[45726] = { title = "The Tainted Marsh", description = "I wasn't able to scout inside the village yet, however, there are more dangerous experiments going on to the south. They were befouling the unquiet spirits in the marshlands with more fel magic!\n\nI will rework this fel totem to draw out the fel energies they infused in those spirits.\n\nPlease, cure what spirits you can, perhaps it will even give them some peace.\n\nIf you want, I can even send you there!", objectives = "" }
WordHunterWoW_QuestEN[45727] = { title = "Uniting the Isles", description = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", objectives = "" }
WordHunterWoW_QuestEN[45747] = { title = "Cinder of Cynders", description = "The cinder seethes with the hatred that its former owner held for you.", objectives = "" }
WordHunterWoW_QuestEN[45748] = { title = "Pearl of Fathoms", description = "The pearl is immaculately smooth, and surprisingly dense.", objectives = "" }
WordHunterWoW_QuestEN[45749] = { title = "Salt of Shards", description = "The Abyssal Lord left behind a small pile of faintly-iridescent sand.", objectives = "" }
WordHunterWoW_QuestEN[45750] = { title = "Song of Zephyrs", description = "A swirling essence coalesces at the feet of the Duke.", objectives = "" }
WordHunterWoW_QuestEN[45751] = { title = "Coreforged Sigil of Skaldrenox", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was forged in flame.", objectives = "" }
WordHunterWoW_QuestEN[45752] = { title = "Glimmering Sigil of Whirlaxis", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved with biting winds.", objectives = "" }
WordHunterWoW_QuestEN[45753] = { title = "Diamondine Sigil of Kazum", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved from stone, then fused into a faultless diamond.", objectives = "" }
WordHunterWoW_QuestEN[45754] = { title = "Tidal Sigil of Skwol", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was crafted from coral and smoothed by the tides.", objectives = "" }
WordHunterWoW_QuestEN[45755] = { title = "Cinder of Cynders", description = "The cinder seethes with the hatred that its former owner held for you.", objectives = "" }
WordHunterWoW_QuestEN[45756] = { title = "Pearl of Fathoms", description = "The pearl is immaculately smooth, and surprisingly dense.", objectives = "" }
WordHunterWoW_QuestEN[45757] = { title = "Salt of Shards", description = "The Abyssal Lord left behind a small pile of faintly-iridescent sand.", objectives = "" }
WordHunterWoW_QuestEN[45758] = { title = "Song of Zephyrs", description = "A swirling essence coalesces at the feet of the Duke.", objectives = "" }
WordHunterWoW_QuestEN[45759] = { title = "Coreforged Sigil of Skaldrenox", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was forged in flame.", objectives = "" }
WordHunterWoW_QuestEN[45760] = { title = "Glimmering Sigil of Whirlaxis", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved with biting winds.", objectives = "" }
WordHunterWoW_QuestEN[45761] = { title = "Diamondine Sigil of Kazum", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved from stone, then fused into a faultless diamond.", objectives = "" }
WordHunterWoW_QuestEN[45762] = { title = "Tidal Sigil of Skwol", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was crafted from coral and smoothed by the tides.", objectives = "" }
WordHunterWoW_QuestEN[45763] = { title = "Demonic Disruption", description = "While scouting on the Broken Shore, we have stumbled upon something quite unsettling.\n\nThe Legion is attempting to harness the powers of Azeroth's elements. What is more, they are succeeding.\n\nWe must stop them at all costs. I can open a portal for you to meet Therazane at the Garrison of the Fel. She will update you on the situation.", objectives = "" }
WordHunterWoW_QuestEN[45764] = { title = "Restoring Equilibrium", description = "Kor'vass sent a report on the status of the Fel Hammer. It suffered major damage, and is now even uglier than before if that'ss even possible...\n\nIt hass also begun listing to one side - rather comically, I might add. For some reason, Kor'vass doesn't find this nearly as entertaining as she should.\n\nAnyway, there are stabilizer crystalss around the Tomb of Sargerass she could use for repairss.\n\nSay the word and I will direct a squadron of illidari batriderss to accompany you. I'd come too, but...", objectives = "" }
WordHunterWoW_QuestEN[45765] = { title = "Brothers and Sisters", description = "Your people were trying to stop the Legion before you arrived, but flesh is weak and they accumulated too many wounds. Without your aid, they will surely perish at the hands of the demons. Go, help them.", objectives = "" }
WordHunterWoW_QuestEN[45767] = { title = "Elemental Cores", description = "The eredar here are abusing the power of all of Azeroth's elements, forcing them to their command using their fel magics. They succeed to do this through curiosities the Legion has developed, cores of power that correspond to each element.\n\nDo not allow the Legion to continue abusing our world. Kill them and take the sources of their power.", objectives = "" }
WordHunterWoW_QuestEN[45769] = { title = "Conflagration", description = "That fiend! Up on the hill, a demon who calls himself \"The Flameripper\" is using the power of my realm. Your shaman die as he draws power from the Firelands, mixing the fire of our world with the unholy flame of his.\n\nHe is extremely powerful, Farseer. You must take him down, whatever the cost!", objectives = "" }
WordHunterWoW_QuestEN[45770] = { title = "Stirring in the Shadows", description = "We must now purify the barding by both material and immaterial means. For the material, we need to travel to Stratholme.\n\nWhen it thrived, before the plague, it produced holy water capable of cleansing even the darkest of magics. There still may be caches of it lying untouched there that we can use.\n\nThen it's just a matter of imbuing enough holy power into the barding to make sure it overcomes the will of Rivendare's mount, Shadowmane.\n\nTravel to the service gate of Stratholme when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[45771] = { title = "A Time for Everything", description = "Our order is recovering thanks to your quick actions, Grandmaster. \n\nThere is just one more monk we need to attend to before it is too late!", objectives = "" }
WordHunterWoW_QuestEN[45785] = { title = "Call of the Scarab", description = "The Call of the Scarab event is occurring today. Speak with your faction's leader near the Gates of Ahn'Qiraj.", objectives = "" }
WordHunterWoW_QuestEN[45787] = { title = "Call of the Scarab", description = "The Call of the Scarab event is occurring today. Speak with your faction's leader near the Gates of Ahn'Qiraj.", objectives = "" }
WordHunterWoW_QuestEN[45788] = { title = "The Speaker Awaits", description = "High Priest, we've received word from Netherlight Temple of a most curious visitor: Magni Bronzebeard, the very Speaker himself!\n\nWhat could he want from our order? You'd best head back to Netherlight, we'll hold down the front here.", objectives = "" }
WordHunterWoW_QuestEN[45789] = { title = "The Sunken Vault", description = "'Ello, High Priest. The Speaker has just been telling us of a calling of sorts, coming from deep in the core of Azeroth.\n\nThe voice is telling 'im there's a lost Titan vault out there, near the Maelstrom. We dun know what's inside, but he's got tha feelin' it's got somethin' ta do with the Light, and you!\n\nBrann's got a vessel waitin' for ye, off the coast of Azsuna. Of course, I'll be accompanying ye as well, for cataloguing purposes. Can't go and let a chance like this go to waste!", objectives = "" }
WordHunterWoW_QuestEN[45790] = { title = "Champion: Almai", description = "", objectives = "" }
WordHunterWoW_QuestEN[45794] = { title = "Informing the Council", description = "I'll deal with this prisoner, but you should head back to Dreadscar Rift. \n\nLet the others know what we've discovered. We will need their help dealing with Kanrethad on the Broken Shore.", objectives = "" }
WordHunterWoW_QuestEN[45795] = { title = "Presence of Power", description = "The demons appear to be harnessing an ancient power within the Temple itself. They've managed to twist and corrupt these sacred grounds with fel magic.\n\nWe must remove the demonic presence before we press our final advance.", objectives = "" }
WordHunterWoW_QuestEN[45796] = { title = "Destroying the Nest", description = "We have to put an end to Tugar's plot. These abominations must be destroyed, as well as their source!\n\nI think I know where. A group of neutral drogbar had a settlement nearby, but were pushed out by concerted demon and fel tauren attacks. That must be the place.\n\nGo there and stop their fel monster production at its source!", objectives = "" }
WordHunterWoW_QuestEN[45798] = { title = "War'zuul the Provoker", description = "There'ss some obnoxious demon lord up there who's been yelling for hourss. \n\nWould you please shut him up already? I'm getting a terrible headache!", objectives = "" }
WordHunterWoW_QuestEN[45812] = { title = "Assault on Val'sharah", description = "The Legion's moves across our lands. Find their forces and remove the threat before it is too late!", objectives = "" }
WordHunterWoW_QuestEN[45813] = { title = "Where Art Thou, My Sweet", description = "What poor fate! Here we are with the jewelry to buy my beloved's freedom, and she has disappeared! We must inquire of the patrons of this fine establishment. Perhaps they know what befell her.", objectives = "" }
WordHunterWoW_QuestEN[45816] = { title = "Choose Order Hall to Support", description = "", objectives = "" }
WordHunterWoW_QuestEN[45833] = { title = "The Pirate's Bay", description = "While we've made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned.\n\nWe've received word of a large cave off the main island, where powerful demons meet to plot our downfall. Tess and Tethys have formulated a plan, but they need your help to see it through.They are waiting for you at Dead Man's Bay in Azsuna.", objectives = "" }
WordHunterWoW_QuestEN[45834] = { title = "Stolen Souls", description = "Odyn's worthy are held captive by soul fonts scattered around the Eternal Battlefield. They were destined to become Valarjar before their futures were stolen.\n\nNow, you can restore them to their rightful places. Destroy the soul fonts to release them!", objectives = "" }
WordHunterWoW_QuestEN[45835] = { title = "False Orders", description = "As soon as you take down Prix, word will spread like wildfire amongst the crew in the area. I had Tethys forge some orders in her handwriting that should send them away and buy us some more time.\n\nPlant the orders in the marked locations. You should see the results rather quickly.", objectives = "" }
WordHunterWoW_QuestEN[45836] = { title = "Jorach's Calling", description = "And with that, the first phase of the plan is complete. It's best we return to Jorach and bring him the news.", objectives = "" }
WordHunterWoW_QuestEN[45838] = { title = "Assault on Azsuna", description = "The demons strike at the heart of our existence, posing a threat to all who inhabit our lands.\n\nRemove the threat before it is too late.", objectives = "" }
WordHunterWoW_QuestEN[45839] = { title = "Assault on Stormheim", description = "The eternal foe of our world, the Burning Legion, dare to attack the land of Stormheim!\n\nChampion, now is your call to valor! Find the forces of the Legion and eradicate them!", objectives = "" }
WordHunterWoW_QuestEN[45840] = { title = "Assault on Highmountain", description = "In my years I have seen disturbances and threats come and go, but never before have I seen such brazen disregard for life. \n\nThe demons may scorch our lands and cause suffering amongst our kin, but we must not stand idly by while they threaten what we have fought so hard to create.\n\nRise to the occasion, {name}. The time has come to stand against the Burning Legion!", objectives = "" }
WordHunterWoW_QuestEN[45841] = { title = "A Triumphant Report", description = "You should return to your Kirin Tor. I have no doubt they will want to hear the good news!", objectives = "" }
WordHunterWoW_QuestEN[45842] = { title = "A Gift From the Six", description = "{name}, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war.\n\nSuch a deed merits more than mere recognition.\n\nIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", objectives = "" }
WordHunterWoW_QuestEN[45843] = { title = "Dark Omens", description = "We won't be able to defeat Kruul alone.\n\nOnce the portal has stabilized I will send word so we can bring the Highlord to justice.\n\nIn the meantime, you should inform the Kirin Tor of Vazuun's death - and Kruul's return.", objectives = "" }
WordHunterWoW_QuestEN[45844] = { title = "Avocation of Antonidas", description = "Archmage Kalec has requested your presence back in the Hall of the Guardian. He's discovered something he wishes to urgently speak with you about.\n\nPlease see him at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[45845] = { title = "Burning Within", description = "The first piece he spoke of was that of fire. He imbued it while investigating the entrance to the Molten Core.\n\nHowever, the power surging through it was too great to control, so he asked Khadgar to take it to Karazhan and see if there were any books on the subject of controlling fire.\n\nPerhaps you should speak with Khadgar and find out what became of the disc.", objectives = "" }
WordHunterWoW_QuestEN[45846] = { title = "Chilled to the Core", description = "The next piece Antonidas made was imbued with frost magic. He wrote about a ritual to channel frost energy into the disc with his fellow Archmage, Cedric, but their combined strengths forced too much energy into the disc.\n\nIf I recall, Cedric is helping oversee the reconstruction of Dalaran near the crater where Dalaran once resided.\n\nHopefully he knows where to find the disc.", objectives = "" }
WordHunterWoW_QuestEN[45847] = { title = "Close to Home", description = "The third piece of the disc was infused with Antonidas' own arcane magic. He did this at the height of his power, but like the other two discs, was unable to finish his work on it.\n\nHe wrote that he gave the piece to Archmage Celindra...\n\nIsn't she the portal trainer here in Dalaran? She must know where the piece is!\n\nQuickly, go speak with her.", objectives = "" }
WordHunterWoW_QuestEN[45848] = { title = "Fit For a Pirate", description = "", objectives = "" }
WordHunterWoW_QuestEN[45856] = { title = "Battle for Val'sharah", description = "From the very start of these attacks I've felt as though the demons knew our plans, as if they anticipated our every move. If we are to put an end to this we must focus our attacks at the heart of the beast.\n\nYour efforts have shown these battles are not won by bravery alone, but willingness and sacrifice. I ask that you stand on the battlefield once more among allies to bring this madness to an end.", objectives = "" }
WordHunterWoW_QuestEN[45861] = { title = "A Gift From the Six", description = "{name}, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war.\n\nSuch a deed merits more than mere recognition.\n\nIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", objectives = "" }
WordHunterWoW_QuestEN[45862] = { title = "A Gift From the Six", description = "{name}, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war.\n\nSuch a deed merits more than mere recognition.\n\nIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", objectives = "" }
