WordHunterWoW_QuestEN[45864] = { title = "A Gift From the Six", description = "{name}, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war.\n\nSuch a deed merits more than mere recognition.\n\nIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", objectives = "" }
WordHunterWoW_QuestEN[45865] = { title = "A Gift From the Six", description = "{name}, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war.\n\nSuch a deed merits more than mere recognition.\n\nIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", objectives = "" }
WordHunterWoW_QuestEN[45866] = { title = "A Gift From the Six", description = "{name}, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war.\n\nSuch a deed merits more than mere recognition.\n\nIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", objectives = "" }
WordHunterWoW_QuestEN[45873] = { title = "Champion: Eitrigg", description = "", objectives = "" }
WordHunterWoW_QuestEN[45876] = { title = "Champion: Lord Darius Crowley", description = "", objectives = "" }
WordHunterWoW_QuestEN[45883] = { title = "The Firelord's Offense", description = "Smolderon calls from across the battlefield, shaman. Now it is his realm being violated.\n\nIt seems urgent. I will clean up here.", objectives = "" }
WordHunterWoW_QuestEN[45890] = { title = "Ancestors and Enemies", description = "I want nothing more than to prove myself by joining our offensive on the Broken Shore, but I'm beginning to doubt my worthiness.\n\nYou see, I found my family's sigil among the demonic runes I've been deciphering. Why the Moonfang crest would be known to the Legion is a mystery to me, but I trust you'll be able to find what connection lies between my ancestors and my enemies.\n\nWhat's left of their village can be found in Val'sharah.", objectives = "" }
WordHunterWoW_QuestEN[45902] = { title = "The Imp Mother's Gift", description = "While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact.\n\nOn behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[45904] = { title = "The God-Queen's Gift", description = "While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact.\n\nOn behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[45905] = { title = "Kruul's Gift", description = "While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact.\n\nOn behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[45906] = { title = "Jarod's Gift", description = "While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact.\n\nOn behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[45908] = { title = "Xylem's Gift", description = "While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact.\n\nOn behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[45909] = { title = "Navarrogg's Gift", description = "While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact.\n\nOn behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[45910] = { title = "Raest's Gift", description = "While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact.\n\nOn behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[45915] = { title = "The Folly of Levia Laurance", description = "Levia Laurance was once a member of the Kirin Tor, long ago, and a good friend. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous for all of us if her knowledge fell into their hands.\n\nShe was last seen at the Militant Mystic. Ask around there and see if you can pick up her trail.", objectives = "" }
WordHunterWoW_QuestEN[45916] = { title = "The Acolyte Imperiled", description = "Truthfully, the Council knows little of Agatha, but she is more than just your average succubus. She has many allies within the sayaad, and is known to command armies of imps that swarm and overwhelm her foes.\n\nTo seek her out is folly, but Ritssyn Flamescowl repays his debts.\n\nCome, let us examine what manner of fel powers this little mage of yours was stumbling her way through...", objectives = "" }
WordHunterWoW_QuestEN[45917] = { title = "Following the Scent", description = "You will have to continue through the portal without me, {class}. I have assisted you in locating your mage's whereabouts, so I consider my debt to Modera paid.\n\nHowever, I will lend you one of my felhounds to help track this mage down. If she is as powerful as Modera says, then it would be in everyone's best interest that Agatha not be allowed to keep her.\n\nBest of luck, {class}, and try to bring Fhambar back in one piece.", objectives = "" }
WordHunterWoW_QuestEN[45971] = { title = "Infernal Phenomena", description = "Do you hear that, shaman? The rumble of the earth as it tries to fight against the Legion's will. Their half-witted eredar are attempting to bend the forces of Azeroth to their will.\n\nHow dare the Legion think they can corrupt my domain? They have assembled their infernals from Azeroth's stone - MY stone! Now they try to bring these new infernals to life.\n\nSabotage their foolish rituals. Crush them! Show them Azeroth's true power!", objectives = "" }
WordHunterWoW_QuestEN[45975] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Tyrosus turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[45987] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Ghrent turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[45990] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Gakin turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[45992] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Jorach turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
