WordHunterWoW_QuestEN[45996] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Sevel turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[45998] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Melis turns her eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[46000] = { title = "Arming Dalaran", description = "Kathra'natir is powerless to stop us from harnessing his energy within the Nightborne Soulstone. We have been lucky thus far - our allies have kept news of the sabotage from spreading. \n\nWe should repair Dalaran's weapons array immediately while luck is still on our side.\n\nOh - the weapon platform is a bit inaccessible. I trust you are not afflicted by a fear of heights? I will open a portal.", objectives = "" }
WordHunterWoW_QuestEN[46020] = { title = "Crystal Containment", description = "Kanrethad will be safe in my care, but something must be done about these crystals that hold his fel magic.\n\nIf any should break, the energy inside would find its way back to our friend. I shouldn't need to tell you how devastating it would be if that were to happen.\n\nI will gather the crystals and meet you back at Dreadscar Rift.", objectives = "" }
WordHunterWoW_QuestEN[46023] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Tinderfell turns her eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[46025] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Master Hsu turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[46027] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Skylord Omnuron turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[46029] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Moira turns her eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[46031] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Siouxsie turns her eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "" }
WordHunterWoW_QuestEN[46034] = { title = "Champion: Aelthalyste", description = "", objectives = "" }
WordHunterWoW_QuestEN[46035] = { title = "End of the Risen Threat", description = "Commander Shadowsong sends word that he is prepared to face the late Lord Erdris. I have a letter from him for you.\n\nI'm prepared to teleport you to his location, but there's a snag.\n\nIn order to combat the worst of the fel corruption, you will need to use some Nethershards on the way in. Make sure you have some before speaking with me.", objectives = "" }
WordHunterWoW_QuestEN[46043] = { title = "Champion: Aethas Sunreaver", description = "", objectives = "" }
WordHunterWoW_QuestEN[46044] = { title = "Champion: Thisalee Crow", description = "", objectives = "" }
WordHunterWoW_QuestEN[46045] = { title = "Champion: Nerus Moonfang", description = "", objectives = "" }
WordHunterWoW_QuestEN[46047] = { title = "Champion: Kanrethad Ebonlocke", description = "", objectives = "" }
WordHunterWoW_QuestEN[46048] = { title = "Champion: Nighthuntress Syrenne", description = "", objectives = "" }
WordHunterWoW_QuestEN[46049] = { title = "A Gift From Your Tadpole", description = "", objectives = "" }
WordHunterWoW_QuestEN[46050] = { title = "Champion: Minerva Ravensorrow", description = "", objectives = "" }
WordHunterWoW_QuestEN[46057] = { title = "Champion: Magatha Grimtotem", description = "", objectives = "" }
WordHunterWoW_QuestEN[46058] = { title = "Champion: Lilian Voss", description = "", objectives = "" }
WordHunterWoW_QuestEN[46059] = { title = "Champion: Tess Greymane", description = "", objectives = "" }
WordHunterWoW_QuestEN[46060] = { title = "Salvation", description = "The valley is swarming with fel-corrupted creatures who are beyond saving, yet there still may be some that could use our help.\n\nTake this manaroot salve and apply it to any animals you see. If the fel magic hasn't taken hold, the salve might be able to mend their wounds.", objectives = "" }
WordHunterWoW_QuestEN[46061] = { title = "Adopt a Tadpole", description = "One day every year, usually in mid-spring, the Winterfin tadpoles are given free reign of the village. I'm not sure why this tradition persists, as it usually results in heavy damage to buildings and food stores.\n\nI usually try not to interfere too much with the goings-on of the tribe, but today, I take exception. Go out and see if you can keep an eye on one of the tadpoles.", objectives = "" }
WordHunterWoW_QuestEN[46062] = { title = "A Tadpole's Request", description = "Glrrrr! Mrr, mrr, glrrgli!\n\n<Your favorite little tadpole is getting reckless. Maybe he might like some clams?>", objectives = "" }
WordHunterWoW_QuestEN[46064] = { title = "The Ways of the World", description = "Mrrga!\n\n<Your tadpole cowers and hides, as he observes the shadowy figure of a large orca passing through the Westrift.>\n\nMrrga... Mrrga...", objectives = "" }
WordHunterWoW_QuestEN[46065] = { title = "An Impossible Foe", description = "{name}! We have just received word from the Council of Six. They have found Agatha!\n\nModera asked that she be able to brief you through this image crystal.  \n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[46069] = { title = "Worthy of the Title", description = "Highlord, Lord Grayson Shadowbreaker wishes to speak with you about an important matter.\n\nPlease seek him out at Light's Hope Chapel in your order hall at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[46070] = { title = "Preparations Underway", description = "As you may or may not recall, I once helped young paladins obtain their first armored mount.\n\nIt was a tedious task that involved months of obtaining materials and sending them all over Azeroth.\n\nThankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord.\n\nIn order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", objectives = "" }
WordHunterWoW_QuestEN[46071] = { title = "The Hammer of Dalaran", description = "Should we wish to make this barding worthy of the steed who will bear it, we'll need to upgrade it. Right now it's just good for not getting you kicked off your mount.\n\nSpeak with Alard Schmied in Dalaran. He's a fine smith and will know how to modify this barding into something more befitting our needs.", objectives = "" }
WordHunterWoW_QuestEN[46074] = { title = "Leather to Legendary", description = "Let's begin, shall we? I mean, I'll be doing all the work, but you get to watch!\n\n<Alard grins a wide smile at you and begins working.>", objectives = "" }
WordHunterWoW_QuestEN[46078] = { title = "Holy: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.\n\nSpecialization: Holy Priest", objectives = "" }
WordHunterWoW_QuestEN[46079] = { title = "Aid on the Front Lines", description = "When we settled here, that Hold was just a quiet creepy place that we avoided. Then the elves came back from the dead. With your help we thought it was mostly handled. But now it feels like an army is attacking us!\n\nWe could use more healing at our defense lines. More undead arrive and we have less and less protectors each wave. Any aid to our wounded would be welcomed!", objectives = "" }
WordHunterWoW_QuestEN[46080] = { title = "Quieting the Spirits", description = "An overwhelming attack on Bradensbrook is imminent. Together I believe we can blunt the spear before it is cast.\n\nWhile we are dealing with the commanders, we should put down as many unquiet spirits as we can.\n\nWith their leaders down and their numbers culled, that should give us time to find Erdris Thorn.", objectives = "" }
WordHunterWoW_QuestEN[46081] = { title = "Leather to Legendary", description = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this.\n\nThere is felslate, but that's a probably too tainted for what you're looking to do with this barding.\n\nYou know, I also like to adorn my pieces with something sparkly, like a jewel. I hear saber's eyes are especially sparkly. Why don't you grab one of those for this as well.", objectives = "" }
WordHunterWoW_QuestEN[46082] = { title = "Shadowsong's Return", description = "Well our lines are doing a lot better, thanks to you. A good thing too, because we need the rest!\n\nThat being said, we noticed a big group of bigger, meaner risen coming from the farmstead. They would've given us a hard time, but that Shadowsong fellow has returned and killed them all. He's holding off reinforcements coming from the hold.\n\nI'm guessing he could use a hand. We can hold here until you and Shadowsong sort this out.", objectives = "" }
WordHunterWoW_QuestEN[46083] = { title = "A Few Things First", description = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this.\n\nThere is felslate, but that's a probably too tainted for what you're looking to do with this barding.\n\nYou know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", objectives = "" }
WordHunterWoW_QuestEN[46089] = { title = "Hiding In Plain Sight", description = "Greetings, Shadowblade.\n\nI hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead.\n\nYes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord.\n\nAnd there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", objectives = "" }
WordHunterWoW_QuestEN[46103] = { title = "Dread Infiltrators", description = "Shadowblade, we have received a raven with most troubling news.\n\nOne of our own, an ally that walked our very Hall of Shadows, is not who they seem.\n\nI believe Lilian has already begun dissecting their corpse. You'd best hurry.", objectives = "" }
WordHunterWoW_QuestEN[46106] = { title = "Cutting off the Heads", description = "Erdris Thorn was a key commander of Ravencrest's forces. To hear him confusing us for the Legion fills me with a great sadness. He will be a difficult foe to defeat.\n\nWe must stop his squad leaders from forming up for a focused assault on Bradensbrook. Defeating them should delay his forces long enough for us to find and deal with him. Let us begin our grim task.", objectives = "" }
WordHunterWoW_QuestEN[46107] = { title = "Source of the Corruption", description = "There was something wrong with those three, they had a fel taint about them that was... unsettling. I believe they were somehow woken later than the other risen. Curse the Legion and their meddling!\n\nThe reinforcements are streaming out of Black Rook Hold from Heroes' Rest. We must make our way there and see if we can stop the source of these new troops.", objectives = "" }
WordHunterWoW_QuestEN[46110] = { title = "Battle for Stormheim", description = "Your efforts have destroyed the Legion's forces upon Shield's Rest, yet they continue to press their assault.\n\nThere is only one way to end this - you must venture into the midst of our foe, find their commander, and remove his vile head!", objectives = "" }
WordHunterWoW_QuestEN[46119] = { title = "Boon of the Builder", description = "", objectives = "" }
WordHunterWoW_QuestEN[46127] = { title = "Thwarting the Twins", description = "I have news from Archmage Karlain! The Kirin Tor have found Raest Magespear and can open up a portal to his location!\n\nIf you are ready to face him, I can have the mages here open the portal into the Twisting Nether.", objectives = "" }
WordHunterWoW_QuestEN[46128] = { title = "Time for a Recharge", description = "", objectives = "" }
WordHunterWoW_QuestEN[46145] = { title = "Sterile Surroundings", description = "With the threat of infection dismissed, your allies should be able to press their assault here on the Broken Shore and gain an advantage over the Burning Legion.\n\nLet's leave this place and speak somewhere more... sterile. I hear your order occupies an impressive temple.", objectives = "" }
WordHunterWoW_QuestEN[46159] = { title = "An Urgent Message", description = "We received an urgent message from one of Belath's scouts down on Mardum! I think you had better listen to it.", objectives = "" }
WordHunterWoW_QuestEN[46173] = { title = "Tactical Planning", description = "Battlelord {name}! We should discuss our next moves!", objectives = "" }
WordHunterWoW_QuestEN[46176] = { title = "The Archmage Accosted", description = "With the barrier dispelled, Archmage Xylem is finally within reach!\n\nHopefully he'll be cooperative in returning the Iris...", objectives = "" }
WordHunterWoW_QuestEN[46177] = { title = "A Portal Away", description = "Xylem may have escaped, but a trace of his portal remains.\n\nNow that you have freed his apprentices from his corruption, I will set them to work trying to find a way to reach him.  Once I find something, I will alert the Kirin Tor.\n\nI only ask that when you do confront the Archmage, that you try to spare his life. I believe that the good man he once was still exists beneath the shadow that has taken him.\n\nFarewell, {name}.", objectives = "" }
WordHunterWoW_QuestEN[46178] = { title = "Hiding In Plain Sight", description = "Greetings, Shadowblade.\n\nI hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead.\n\nYes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord.\n\nAnd there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", objectives = "" }
WordHunterWoW_QuestEN[46182] = { title = "Battle for Highmountain", description = "Our defenses have grown in strength, yet the Legion continues to press their assault on Thunder Totem. There is but one way to put an end to this madness - we must strike at the heart of their forces together and bring these attacks to an end.", objectives = "" }
WordHunterWoW_QuestEN[46199] = { title = "Battle for Azsuna", description = "The vile demon commanding the assault must be stopped. I can get us close, but once we're there I'll rely on you and your allies to help bring down the demonic forces.", objectives = "" }
WordHunterWoW_QuestEN[46200] = { title = "The Matter Resolved... For Now...", description = "You should return to the Kirin Tor. I have no doubt they will want to hear of our success. I will find Lord Erdris, and then I will contact you.", objectives = "" }
WordHunterWoW_QuestEN[46205] = { title = "A Conduit No More", description = "One final task remains to sever the Burning Legion's connection to other worlds.\n\nI'll provide you transportation to get you close to the source of power, but you must deliver the final blow to the conduit.", objectives = "" }
WordHunterWoW_QuestEN[46206] = { title = "Whispers of a Frightened World", description = "\"Champion! Azeroth needs our help.\"\n\n<Magni Bronzebeard's words echo in your mind, as if rising from somewhere deep and ancient. Azeroth's world soul seeks to deliver a warning to the Speaker, but some force is interfering with the message.>\n\n<Magni has urged you to travel to Sholazar Basin, the vibrant heart of frozen Northrend, to aid him.>", objectives = "" }
WordHunterWoW_QuestEN[46207] = { title = "The Trial of Rage", description = "I wish to extend to you a prestigious invitation.\n\nEvery year I hold a trial for my finest warrior to prove that I command the strongest in this land. I have chosen you to be my champion in this trial.\n\nShould you succeed in completing the trial, I have a prize that will be worthy of your accomplishments awaiting you at the end.\n\nTake what time you need to prepare yourself. Come back and speak with me when you're ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[46208] = { title = "A Godly Invitation", description = "Battlelord {name}, Odyn has requested an audience with you back in Skyhold.\n\nPlease meet with him at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[46213] = { title = "Crystals Not Included", description = "Turalyon is safe, and we can start to fight back.\n\nFirst things first, we must secure what supplies we can from the crash.\n\nEven though we are blessed by the Light, our ships still rely on crystal technology. From powering our defenses to arming our weapons, we will need to collect as much as we can to fight back against the enemy.\n\nVenture out into the crash and retrieve what crystals you can. While you are out there, keep an eye out for Y'mera. She was separated from us, and will need help.", objectives = "" }
WordHunterWoW_QuestEN[46235] = { title = "Secured Surroundings", description = "With Lexera defeated, her band of trappers will quickly disband. Those that refuse will meet my blade.\n\nThese shores will be free of those who wish to corrupt Azeroth's wildlife.\n\nOur work here is done for now. Let us meet at Deliverance Point. There is more I wish to discuss in secured surroundings.", objectives = "" }
WordHunterWoW_QuestEN[46237] = { title = "Bloodbringer's Missive", description = "Warlock! We have news from Dreadscar Rift. \n\nA message arrived by raven from Mor'zul Bloodbringer, with instructions that you meet him in Dreadscar Rift immediately!", objectives = "" }
WordHunterWoW_QuestEN[46238] = { title = "If You Build It", description = "If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground.\n\nI will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. \n\nHere's the list of what you'll need.", objectives = "" }
WordHunterWoW_QuestEN[46239] = { title = "Fel to the Core", description = "While it has become relatively easy for a warlock to open a brief window into the realms of the Legion, a sustained portal requires significantly more power.\n\nFor this, we will need a power source brimming with fel energy. \n\nI know that the commanders of the Legion use powerful fel cores to control their warships. If you can defeat the commander of one of these ships, you should be able to take their core.", objectives = "" }
WordHunterWoW_QuestEN[46240] = { title = "Give Me Fuel, Give Me Fire", description = "A powerful core will not alone be able to power the portal. Like any powerful engine, it will require fuel - though an engine of fel energy must burn life force to thrive.\n\nWe will need blood potent in magical energy to keep our fel core running and sustain our connection to Xoroth. Fortunately, I have experience in these matters, and I know just the place where we can get some.\n\nYou'll need a jar or something.", objectives = "" }
WordHunterWoW_QuestEN[46241] = { title = "The Minions of Hel'nurath", description = "The dreadlord Hel'nurath gifts his lieutenants with calling stones to call and bind the dreadsteeds of Xoroth to their service. I believe one such stone will help us draw out the Wrathsteed. \n\nSome Xorothian cultists have been spotted helping the Legion's efforts on the Broken Shore. It would be safe to assume their leader has one of Hel'nurath's stones.\n\nYour succubus should be able to entice the truth out of the cultists. Find one who knows of their leader's whereabouts.", objectives = "" }
WordHunterWoW_QuestEN[46242] = { title = "The Dreadlord's Calling", description = "According to the cultist, the leader you seek should be in her tower overseeing the operations in the Dark Stockades.", objectives = "" }
WordHunterWoW_QuestEN[46243] = { title = "The Wrathsteed of Xoroth", description = "The time has come and the preparations have been made. When you are ready, we will tear a hole into Xoroth, and force the Arax'ath and the Wrathsteed out of hiding.\n\nFollow me to the summoning platform. From there we will initiate the ritual.\n\nPrepare yourself, {name}. This will not be an easy undertaking.", objectives = "" }
WordHunterWoW_QuestEN[46244] = { title = "Cathedral of Eternal Night: Altar of the Aegis", description = "Champion, we are ready to assault the Tomb of Sargeras.\n\nI studied the writings of Aegwynn, the Guardian who defeated the Dark Titan's avatar. She said that if her wards were compromised, a failsafe could be triggered by placing the Aegis of Aggramar upon an altar in the Cathedral of Eternal Night.\n\nYou are the hero who acquired the Pillars of Creation, {name}. Gather your allies and enter the Cathedral. Be warned: Mephistroth will use all his power to stop you from placing the Aegis. You must prevail!", objectives = "" }
WordHunterWoW_QuestEN[46245] = { title = "Begin Construction", description = "We've got the supplies. Now someone needs to decide what to do with 'em.\n\nHmm. Looks like it's your call, being the {class}t and all!\n\nTime to pick a building to focus on.", objectives = "" }
WordHunterWoW_QuestEN[46246] = { title = "Strike Them Down", description = "The Felstorm continues to rain demon scum upon these shores. Kil'jaeden believes his army infinite, his resources inexhaustible.\n\nWe will show him how wrong he is.\n\nCut a swath of retribution through their ranks, {class}t. Strike down demon after demon, until your weapons are bathed in their blood. And when they cry out for mercy, send them screaming back into the Nether.", objectives = "" }
WordHunterWoW_QuestEN[46247] = { title = "Defending Broken Isles", description = "In our zeal to reclaim the Broken Shore from the Legion, we cannot allow the rest of this land to fall into the demons' foul grip.\n\nKil'jaeden has dispatched his forces across the Broken Isles, threatening the homelands of the allies you have made. You must answer their call in this hour of need.\n\nTurn back these demon assaults with haste, {class}t. The Armies of Legionfall will see that the Broken Shore remains secured.", objectives = "" }
WordHunterWoW_QuestEN[46248] = { title = "Self-Fulfilling Prophecy", description = "In my life, I have witnessed many visions. Some filled me with hope... others, with despair.\n\nVictory over Kil'jaeden lies within our grasp. I have foreseen it. But visions only show us where our path might lead. They require effort to become reality.\n\nThat effort falls upon your shoulders, {name}. You have done much, but more is needed. Fight on the battlefields of the Broken Shore and forge a destiny free from the Legion's grasp!", objectives = "" }
WordHunterWoW_QuestEN[46249] = { title = "Championing Our Cause", description = "Important work has been done by your order, {class}t. Your champions have succeeded time and again in undermining the Legion's invasion.\n\nAs we make preparations for our assault on the Tomb of Sargeras, we need to keep the demons off balance. By pressuring them at every turn, we will expose vulnerabilities that can be exploited to our advantage.\n\nSend out your order's champions, {name}. Their missions are vital to the success of our campaign... especially as our confrontation with Kil'jaeden draws closer.", objectives = "" }
WordHunterWoW_QuestEN[46250] = { title = "Take Out the Head...", description = "The Broken Shore swims with Legion filth, each demon deserving of a swift and merciless end.\n\nBut some are more insidious than the rest. Powerful combatants rallying others to their perfidious cause.\n\nStrike down these demon champions and you will fill the hearts of their kin with fear and doubt. Break the Legion's spirit and we will break its back.", objectives = "" }
WordHunterWoW_QuestEN[46251] = { title = "Shard Times", description = "As you have surely noticed, a slain demon leaves behind Nethershards, solidified residual energy from the Twisting Nether. I require a significant quantity of them for an experiment I'm conducting... oa shards, to be precise.\n\nWhy are you looking at me like that? We've had this conversation before. I did the math.\n\nI need exactly oa shards. Fewer would be inadequate. More would be absurd.\n\nDon't question my methods. Go!", objectives = "" }
WordHunterWoW_QuestEN[46252] = { title = "Intolerable Infestation", description = "While we purge Legion filth from the Broken Shore, the fiends maintain their hold on nearby lands. Their presence can no longer be tolerated.\n\nThe fetid strongholds of Faronaar and Felsoul Hold infest Azsuna and Suramar. Choose an attack point and cut a swath through their insidious ranks.\n\nReturn to me with demon blood on your hands, then we can resume our campaign to drive Kil'jaeden from the Tomb.", objectives = "" }
WordHunterWoW_QuestEN[46253] = { title = "Pillars of Creation", description = "Our campaign on the Broken Shore has reached a turning point. The Armies of Legionfall stand ready to breach the Tomb of Sargeras and seal the Legion's gateway to our world.\n\nThe time to strike is now, {name}.\n\nThe Aegis of Aggramar has been secured in the Cathedral. The echo of Magna Aegwynn said that the other Pillars of Creation are needed to seal the tomb. It is fitting that you have the honor of locking those ancient relics in place and closing down the Felstorm once and for all.", objectives = "" }
WordHunterWoW_QuestEN[46254] = { title = "TBD", description = "", objectives = "" }
WordHunterWoW_QuestEN[46255] = { title = "X Unstable Portals Disrupted, 1 World Boss Defeated", description = "", objectives = "" }
WordHunterWoW_QuestEN[46256] = { title = "X Treasures Found, 1 Challenge Attempted", description = "", objectives = "" }
WordHunterWoW_QuestEN[46258] = { title = "The Calm After the Storm", description = "You have saved the elements from the Legion's control, and for that we thank you. However, it came at a great cost to both your health and your fellow shaman. Many came back to us wounded, dragged along by their fellow shaman.\n\nWe have seen the havoc the Doomstone can wreak. It does not belong in the hands of any being, mortal or otherwise. While you were asleep, the elemental lords and I discussed its fate.\n\nBring it to Neptulon. He will explain.", objectives = "" }
WordHunterWoW_QuestEN[46259] = { title = "Darkbinder Dilemma", description = "Ah, Delas sent you. I see.\n\nIt's good she didn't come herself. It would break her heart to see what is happening to our family.\n\nA demon is defiling our dead in the ruins nearby. She's using her fel magic on our ancestors, turning them into mindless horrors that do the bidding of the Burning Legion.\n\nI can't deal with the harpies and this demon, but maybe you could help?\n\nGet rid of the darkbinder that torments our dead, and I will grant you access to whatever's left of the Moonfang family relics.", objectives = "" }
WordHunterWoW_QuestEN[46260] = { title = "Meld Into the Shadows", description = "We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.", objectives = "" }
WordHunterWoW_QuestEN[46266] = { title = "Return of the Slayer", description = "If you're anything like me, I'm sure you'd prefer to remain here on solid ground.\n\nUnfortunately, it is probably best to return to the Fel Hammer right away so Kor'vass can finish the repairss.", objectives = "" }
WordHunterWoW_QuestEN[46267] = { title = "Return of the Battlelord", description = "Battlelord {name}, Odyn will want to hear the tale of your glorious victories here!\n\nI will assist you in returning to Skyhold when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[46268] = { title = "A Found Memento", description = "<The trinket's fine brass exterior is inlaid with intricate filigree, though much of the detail has been battered by rocks and waves. Clearing away the grime and salt encrusting the clasp, you manage to open it.\n\nIt is a compass--or was, at least. The glass face is shattered, the needle bent, unmoving.\n\nSet into the lid is a portrait. The paint is faded and waterlogged, but the subject is unmistakable: the face of a young Anduin Wrynn.>", objectives = "" }
WordHunterWoW_QuestEN[46272] = { title = "Summons to the Keep", description = "Greetings, {name}.\n\nYour presence has been requested in the royal court. The crown has urgent need of you!\n\nPlease return to Stormwind at your earliest convenience.\n\nKing Greymane is anticipating your swift arrival.", objectives = "" }
WordHunterWoW_QuestEN[46274] = { title = "Consoling the King", description = "Anduin hasn't been the same since you brought him his father's compass. He has become listless... distracted.\n\nWe attempted to console him, to no avail. Yesterday morning, he left the keep without so much as a word.\n\nI ordered the guards to follow him, of course. He went to pray at the cathedral, where he's remained ever since.\n\nYou brought this melancholy upon him! You must convince the boy to resume his duties. There's a war to be won!", objectives = "" }
WordHunterWoW_QuestEN[46275] = { title = "A Kingdom's Heart", description = "My father was a legend. He oversaw the rebuilding of Stormwind, stood toe-to-toe with dragons, led the Alliance to numerous victories.\n\nThen, one day, he was just... gone.\n\nI wear his crown, I hold his title. But I've done nothing to earn them... or the faith of my people.\n\nI've spent the war sequestered in the keep, surrounded by guards and advisors. I need to walk the streets of Stormwind, to know whether it is hope or fear that beats in the hearts of my people.\n\nI welcome your company.", objectives = "" }
WordHunterWoW_QuestEN[46278] = { title = "Return to Sender", description = "You've arrived just in time!\n\nUnlike the mail as of late, I'm afraid.\n\nWe are severely understaffed, and demand is at an all-time high. We simply can't keep up!\n\nI'd love to chat, but I need help catching up before I can rest for even a moment.\n\nFirst thing's first. Several parcels of rejected mail have broken loose again; will you help me round them all up and return them to their senders?", objectives = "" }
WordHunterWoW_QuestEN[46282] = { title = "The King's Path", description = "Now that I have seen the Broken Shore and the terror of the Burning Legion first hand, my eyes have been opened to the truth.\n\nI speak not of the unfathomable evil of the enemy, but of the bravery and sacrifice that such evil brings about in the hearts of our people.\n\nMy father once told me that every king must carry the weight of his own crown. Mine has never felt heavier than it does at this very moment...\n\nPlease take me to the place where my father died, so that I may honor his sacrifice.", objectives = "" }
WordHunterWoW_QuestEN[46286] = { title = "Legionfall Supplies", description = "If we don't build up some respectable fortifications, we'll lose our foothold on the Broken Shore.\n\nThat ain't gonna happen on my watch, mate!\n\nWe started construction on three key structures: the Mage Tower, the Nether Disruptor, and the Command Center. Each will play a key role in helping us pound the tar out of the Burning Legion.\n\nTo make progress, we need Legionfall War Supplies... and I mean lots of 'em! You bring 'em to me, and I'll handle distribution. Got it?", objectives = "" }
WordHunterWoW_QuestEN[46290] = { title = "Return of the Archmage", description = "With Dalaran protected once again, we can all breathe a little easier. \n\nIt is time for us to return to the Hall of the Guardian. I'm sure Meryl is anxiously awaiting word of our success.", objectives = "" }
WordHunterWoW_QuestEN[46291] = { title = "The Deadmines Strike Back", description = "Breanni sent you? For her, info is always free. Just don't call me a snitch.\n\nI've been hangin' around the Deadmines for years. For the most part, it's a pretty easy livin'. But a few days ago, I started hearing noises of all sorts comin' from the mines. If you want to get in unnoticed, I'll grab us a mine cart and we can get most of the way down without so much as an awkward glace in our direction.\n\nJust let me know when you're ready to head in.", objectives = "" }
WordHunterWoW_QuestEN[46292] = { title = "Pet Battle Challenge: Deadmines", description = "The Deadmines could still use some cleaning up, seems you didn't clear the place out last time.\n\nWe'll use the ol' mine cart trick again. Cept, we're going to put some flair into it. How do you feel about fire? No? Okay, fine. Just let me know when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[46293] = { title = "Deadmines, Part Three?", description = "I've heard suspicious rumors of movement in the Deadmines. After everything you pulled off in the Wailing Caverns, you'd be the perfect person to look into this!\n\nI have a friend in Westfall. He may not look like much, but he's quick as a whip and may have more information on what is happening in Westfall. We've already dealt with the Van Cleefs... twice. So what could be making that sort of ruckus down there?", objectives = "" }
WordHunterWoW_QuestEN[46297] = { title = "Overwhelming Power", description = "We will find no sanctuary on this world. Even now the full might of the Burning Legion rises to defend Argus.\n\nThe siege camp below overflows with demon filth that stand between us and the weapon trained on the Vindicaar.\n\nThey must be dealt with before it can fully charge, or Argus will be our grave.", objectives = "" }
WordHunterWoW_QuestEN[46305] = { title = "Thorim's Flame", description = "Not too long ago, the Drekirjar and the Thorignir respected each other. This only changed when Skovald came into power. An ancient Drekirjar spirit watches over this peak, which seems to be a sacred graveyard of some sort. He is the keeper of the ceremonial flame, which happens to be exactly what we need to call down the broodmother.\n\nWhy don't we go convince him to let us take the flame? I'm sure he'll be nothing but... amiable.", objectives = "" }
WordHunterWoW_QuestEN[46314] = { title = "Vengeance: Seeking Kor'vas", description = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city.\n\nOne of your Illidari, Kor'vas Bloodthorn, has taken to patrolling the city streets on her own to find the source behind the recent attacks.\n\nI do not entirely trust your kind, but I will concede that you have at least proved adept at your namesake. I suggest you find Kor'vas and see what she has uncovered before the Legion strikes once more.\n\nSpecialization: Vengeance Demon Hunter", objectives = "" }
WordHunterWoW_QuestEN[46316] = { title = "Champion: Kanrethad Ebonlocke", description = "", objectives = "" }
WordHunterWoW_QuestEN[46317] = { title = "Talon's Call", description = "The Legion is launching a renewed assault against the Shrine of Aviana in Hyjal!\n\nThisalee Crow is organizing a counter-offensive, she requests your presence in the Dreamgrove at once.\n\nWe will handle the offensive here. Good luck, Archdruid!", objectives = "" }
WordHunterWoW_QuestEN[46318] = { title = "Defense of Aviana", description = "The situation is dire. The Legion is attacking the Shrine of Aviana in Hyjal, AGAIN! They must be after something specific, but I'm not sure what.\n\nUs Druids of the Talon are skilled scouts and infiltrators, but are lacking in... durability. They won't be able to hold out for long! We must go to help!", objectives = "" }
WordHunterWoW_QuestEN[46319] = { title = "You Can't Take the Sky from Me", description = "The Shrine of Aviana has fallen to the demons, and the Idol of Aviana has been stolen.\n\nThat idol acts as a link between the Druids of the Talon and the powers of flight granted to us by Aviana.\n\nThe Druids of the Talon have decided to rebuild a new shrine in a more secure location: here in the Dreamgrove.\n\nMeanwhile, I'm going to get our idol back. Meet me in Azsuna, near where we've tracked Infazzar to, if you want to help.", objectives = "" }
WordHunterWoW_QuestEN[46320] = { title = "Hope For a Cure", description = "Hopefully you found enough fel poison samples with which to brew a cure.\n\nLet's meet back to the Temple of Five Dawns!", objectives = "" }
WordHunterWoW_QuestEN[46322] = { title = "The Pirate's Bay", description = "While we've made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned.\n\nWe've received word of a large cave off the main island, where powerful demons meet to plot our downfall. One of our rogues, Lilian Voss, has formulated a plan with Tethys to take care of them, but they require your aid. They are waiting for you at Dead Man's Bay in Azsuna.", objectives = "" }
WordHunterWoW_QuestEN[46323] = { title = "What's the Cache?", description = "Our goal is to retrieve a cache of gunpowder which has been infused with some sort of fel power. I don't know how the pirates here acquired it, but it is more dangerous than they know. I assure you that it will be more... effective in our hands.\n\nMaster Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.", objectives = "" }
WordHunterWoW_QuestEN[46324] = { title = "False Orders", description = "We must take some precautions. As soon as you assassinate the gunner, the crew will be looking for you. I had Tethys forge some orders in her handwriting that should buy us some time.\n\nPlant the orders in the marked locations. That will take care of the danger.", objectives = "" }
WordHunterWoW_QuestEN[46326] = { title = "Jorach's Calling", description = "And with that, the first phase of my machination is complete. Let's return to Jorach and tell him it is time to continue.", objectives = "" }
WordHunterWoW_QuestEN[46327] = { title = "Bargaining with Shadows", description = "From the clues you've been able to piece together, it appears that Levia was looking to conduct a ritual in the libraries beneath Dalaran - most likely to summon this \"Agatha\" she has become so infatuated with. I'm afraid this is a little out of my area of expertise, so I'm going to have to call in a favor.\n\nI'll send for assistance from the Council of the Black Harvest. One of their warlocks will meet you in the Chamber of the Guardian to assist with your investigation.\n\nI hope we're not too late.", objectives = "" }
WordHunterWoW_QuestEN[46333] = { title = "Livin' on the Ledge", description = "Slayer {name}, Matron Mother Malevolence requests an audience with you back at the Fel Hammer. Please see her at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[46334] = { title = "To Fel and Back", description = "Mardum has its fair share of secrets, one of which we found not too long after we took control of the Fel Hammer. It's a breeding ground of sorts, festering with fel bats.\n\nWe've been capturing the pups and trying to train them up for our efforts against the Legion.\n\nBut the other day, we caught an even greater prize, something worthy of your position, Slayer.\n\nSpeak with Kyra and she'll provide you a ride to the ledge.", objectives = "" }
WordHunterWoW_QuestEN[46335] = { title = "The Vault of the Tirisgarde", description = "Dalaran's weapons are arcane in origin, but that doesn't mean we can't try something different. \n\nOur order's vaults contain a vast store of magical devices... Why don't you take a look around and see if there's anything we can use?", objectives = "" }
WordHunterWoW_QuestEN[46336] = { title = "A Golden Ticket", description = "Huntmaster, we've gotten word from the Lodge that there is a letter wrought from golden light sitting on one of the tables, and it's got your name on it.\n\nNo one is sure how it got there, and someone's wolf may have tried to open it and gotten a mouth full of singed fur. Seems like it's meant only for you.\n\nWe'll hold down the fort here while you investigate.", objectives = "" }
WordHunterWoW_QuestEN[46337] = { title = "Night of the Wilds", description = "<The letter is written in a flowing, golden script. You can practically hear Odyn's booming voice speak the words as you read it.>\n\nThe Night of the Wilds is upon us. \n\nTonight, we will feast in honor of the beasts of legend, and they will rise once more in the Fields of the Eternal Hunt.\n\nOne among us will set out into the fields to put their spirits to rest once more. \n\nMy herald awaits you, hunter, if you will join us.", objectives = "" }
WordHunterWoW_QuestEN[46338] = { title = "A Creative Solution", description = "The Nightborne Soulstone may be our best hope if we can come up with a way to safely use it without Kathra'natir escaping. If he were to get loose in Dalaran...\n\nWe should consult with our friend, Ari. She will know what modifications need to be done.", objectives = "" }
WordHunterWoW_QuestEN[46339] = { title = "Keymaster Orlis", description = "The Felborne insurgents appear to be guarding a teleporter pad within the glade ahead. I wonder where it leads?\n\nIt is probably safe to assume that we'll need to kill Keymaster Orlis in order to gain access.", objectives = "" }
WordHunterWoW_QuestEN[46340] = { title = "The Gates Are Closed", description = "Sigryn must be reached before she can confront Odyn, but our path is blocked. Odyn will close the Gates of Valor as soon as he becomes aware of Sigryn's assault. You will have to find another way into the Halls.\n\nI have no talent with portals, but your friends at the Kirin Tor seem to be very adept. Go now to them, and find a way through.\n\nI thank you for what you've done to help Sigryn this far, {class}. I only hope we can save her from herself.", objectives = "" }
WordHunterWoW_QuestEN[46341] = { title = "The Tale of Ban-Lu", description = "Oh, hello, you must be the new Grandmaster.\n\n<Master Bu squints at you and sniffs.>\n\nYou young ones have no patience these days, always running off to fight your great battles.\n\nNo time for stories, even good ones, eh?\n\nWhy don't you put your fists down for a moment and allow an old man to tell you a tale.\n\nMaybe buy an old man a drink while you are at it?", objectives = "" }
WordHunterWoW_QuestEN[46342] = { title = "Return to the Broken Peak", description = "Of course, this is no mere story. Ban-Lu served as the personal mount of each of the previous Grandmasters, accompanying them through their travels as a faithful and trusted companion.\n\nBut... he has not revealed himself since you have become Grandmaster. This is troubling.\n\nThe last time he was seen was at the Peak of Serenity, after the fall of Grandmaster Hight.\n\nIt is there that we must begin our search for him.", objectives = "" }
WordHunterWoW_QuestEN[46343] = { title = "The Trail of Ban-Lu", description = "It seems a lifetime ago that Grandmaster Hight was walking these grounds. \n\nWhile Ban-Lu has served every previous Grandmaster, he and Hight were the greatest of friends.\n\nFor many years they traveled the land, connecting with its people and maintaining our fragile peace.\n\nI cannot imagine how deeply Ban-Lu must have been affected by his passing.\n\nThere must be some clues to his whereabouts around here. Look sharply.", objectives = "" }
WordHunterWoW_QuestEN[46344] = { title = "Smelly's Luckydo", description = "You! Please help! Stupid hozen stole Smelly's luckydo! \n\nNow, Smelly always unlucky. Just turned around and look, pack is on fire.\n\nNot going to put fire out because then something ELSE unlucky happen. Maybe something worse!\n\nYou beat up hozen, yes? Get back luckydo? Smelly will help you, any way he can!", objectives = "" }
WordHunterWoW_QuestEN[46345] = { title = "Into the Hornet's Nest", description = "I hope you are up for an adventure. Shall we see where that teleporter goes?", objectives = "" }
WordHunterWoW_QuestEN[46346] = { title = "The Shadow of Ban-Lu", description = "That was good of you to assist Smelly Mountaintop, Grandmaster, and we have learned more about the fate of Ban-lu.\n\nI won't bother you with escorting me to Shado-Pan Monastery. I can manage on my own.\n\nMeet me there and we'll continue our search.", objectives = "" }
WordHunterWoW_QuestEN[46347] = { title = "Clean-up on Aisle Sha", description = "I've spoken with the Shado-pan and they are willing to give us information if we can assist them with a task of their own.\n\nSpeak with Commander Shen-Li. While you're assisting them, I shall continue to meditate.", objectives = "" }
WordHunterWoW_QuestEN[46348] = { title = "The River to Ban-Lu", description = "We still do not know where Ban-Lu has gone to, but I do know who might.\n\nTo the southeast lives a jinyu, Waterspeaker Ryuli.\n\nPerhaps he has seen Ban-Lu, or can ask him to inquire with the river about where Ban-Lu has been seen recently?\n\nAll this travel has done a number on my old joints, Grandmaster. I shall rest here a bit longer, and then catch up with you later on.", objectives = "" }
WordHunterWoW_QuestEN[46349] = { title = "Lilies for Ryuli", description = "I have not seen Ban-Lu, but the waters will surely know where he is.\n\nThere is a flower that grows in the lakes of the mountain slopes near the Temple of the White Tiger, that only blooms in the presence of someone pure of heart.\n\nBring me six of these Moon Lilies and I shall use them to speak to the river.", objectives = "" }
WordHunterWoW_QuestEN[46350] = { title = "The Trial of Ban-Lu", description = "Ah, the ripples I feel in the water are strong! The droplet does not fall far from our location.\n\nBan-Lu is quite close. \n\n<Ryuli closes his eyes and releases the lilies into the water. They drift slowly to the east.>\n\nHe waits for you now, at the bottom of the waterfall to the east.", objectives = "" }
WordHunterWoW_QuestEN[46351] = { title = "Keep it Secret, Keep it Safe", description = "The shield generator you found is much more than it appears. I do not think my elders would approve of such advanced technology being shared with outlanders...\n\nAnd yet... We owe you our lives and our freedom. \n\nYou may use it, with my blessing. Just... please be discreet about its existence, Archmage {name}.", objectives = "" }
WordHunterWoW_QuestEN[46353] = { title = "Master Who?", description = "Greetings. I've just received word that Master Bu has returned from a long spirit journey, and is currently resting his feet at Morning Breeze Village outside of the Temple of Five Dawns.\n\nIt's been quite a long time since anyone has seen or heard from him, but he's asking to speak to you.\n\nWe will handle the situation here while you are absent, Grandmaster.", objectives = "" }
WordHunterWoW_QuestEN[46499] = { title = "Spiders, Huh?", description = "I feel like they're still crawling all over me. I squished one egg and all of a sudden I'm covered head to toe in baby spiders.\n\n<Shivers>.\n\nThat treasure is just sitting there now. The next guy better not be arachnaphlipic... arachnaphonetic? Arachniphant? Afraid of spiders!", objectives = "" }
WordHunterWoW_QuestEN[46501] = { title = "Grave Robbin'", description = "I am not a grave robber, but is it technically grave robbing if the treasure is sitting on a field of bones? It's not like it's buried or nothin'. I'm just gonna sit this one out, just in case.", objectives = "" }
WordHunterWoW_QuestEN[46509] = { title = "Tomb Raidering", description = "I said to myself over and over, \"Don't go near the citadel. Don't go near the citadel.\" But what did I do? I went to the citadel. Almost had my hands on that sweet treasure chest before I got chased off by a bunch of crazy demons. I made it out of there with just my helmet and my life!", objectives = "" }
WordHunterWoW_QuestEN[46510] = { title = "Ship Graveyard", description = "I haven't told you that I was part of the original landing party when we lost almost everything.  I don't care what treasure is left there, I'll never go back to that beach. Never.", objectives = "" }
WordHunterWoW_QuestEN[46511] = { title = "We're Treasure Hunters", description = "I have a feeling you're just using me for tips on where all the best treasure is. From now on I'm naga tell you anything. Did I say, \"naga\" just then? I meant to say, I'm not gonna to tell you naga. I mean nada! Darn it!\n\nOkay. Seems you got me on this one. I'll tell you what, fetch me whatever is in that chest near those naga freaks and I'll make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[46666] = { title = "The Motherlode", description = "Pst... Come 'ere! I just got a tip about a cave on this island that is a treasure trove of loot! This could be my biggest score yet.\n\nProblem is, I uhh... sprained my ankle. Yeah, I would be right there with you battling those demons to get this treasure, but I shouldn't be putting any weight on this leg of mine. Shucks.\n\nHow about you go check on this cave and report back to me. I'll mark your map where the cave entrance is. I've been told it's pretty hidden, so you've got to look around.", objectives = "" }
WordHunterWoW_QuestEN[46674] = { title = "The Preservation of Nature", description = "I fear this attack on Goldrinn is only the beginning, {name}. Whoever is ordering these attacks must be found and defeated.\n\nWasn't Thisalee with you? She never returned... brash child. I assume she is already on the Broken Shore, trying to track down this commander. Please, find her. Do not let her take this on alone.", objectives = "" }
WordHunterWoW_QuestEN[46675] = { title = "To Track a Demon", description = "I took the initiative to scout around before I grabbed that wyrmtongue. It seems like their forces are holed up in a camp in Impsorrow Approach. What I've struggled to figure out, however, is who their commander is and if he's nearby.\n\nIf he's leading from elsewhere, the troops need to have some commands on them. Let's go see if we can find any... on their dead bodies!", objectives = "" }
WordHunterWoW_QuestEN[46676] = { title = "Nature's Touch", description = "Apparently we're not the only druids that have run into these demons. The Legion took a ton of captives and brought them back to their camp. Our brothers and sisters lay wounded and hurting...\n\nYou can heal! Let's go save them!", objectives = "" }
WordHunterWoW_QuestEN[46677] = { title = "Prick of a Thistle", description = "Their commander's name is Katith'rax. He's the one who organized these attacks, and now the one who leads them. Luckily, it doesn't seem as though he's far off.\n\nRight off the coast is a small island. Seems as though he hides there, barking orders without getting his hands dirty.\n\nI, on the other hand, enjoy getting my hands a little dirty. Don't you?", objectives = "" }
WordHunterWoW_QuestEN[46678] = { title = "The Legend of the Threads", description = "Tailoring is the noblest of professions because clothing is universal. Most dress with nary a thought. If you analyze the legends, some races stand out from all others. \n\nThe Nightborne are masters of style! Much of the brilliance is in their materials--in particular their thread and their looms. We will take advantage of both. Before you gather materials, I need to confirm my list. Find the fashion treatise I brought with me. Perhaps I dropped it by the flight master?", objectives = "" }
WordHunterWoW_QuestEN[46679] = { title = "The Thread of Shadow", description = "Vandros of the Nightborne. There is an elf who knows how to dress. Ever since he was a young noble in the Court of Farondis, Vandros has been known for snappy, fashion forward outfits. \n\nI've never been able to see his garments up close but my research tells me that his tailor's technique is not so much in the fabric as it is in the thread. It appears to be spun of the very shadows themselves. \n\nYou have your methods to obtain it, I'm sure. Get his robes and get the thread.", objectives = "" }
WordHunterWoW_QuestEN[46680] = { title = "The Thread of Starlight", description = "Melandrus of the Nightborne is First Blade of Elisande. Perhaps you've heard of him? He is a great hero to the Nightborne but, to be absolutely honest, he is a mess with regards to style. \n\nHis accoutrements are somewhat better and a particular pair or bracers are rather nice. In fact, the thead that binds them will be absolutely perfect for your pending outfits. Why don't you get that for me and we will talk further.", objectives = "" }
WordHunterWoW_QuestEN[46681] = { title = "The Thread of Souls", description = "Have you ever had a chance to lay eyes on Elisande, Grand Magistrix of the Nightborne? Stunning! Fashion-forward! Nice posture! \n\nYou'd do well to take a page from her book! In fact, you'd tell well to take the thread from her Suramari Soul Wraps! These hold great symbolic value to her people so it's doubtful she will give them willingly. \n\nSo be it, take her out and get that thread.", objectives = "" }
WordHunterWoW_QuestEN[46682] = { title = "Drapings of the Ancients", description = "{name}, we are going to need a high quality cloth to work with. Thankfully, the weaving quality of nightborne craftspeople from long ago was very good. It is a lost art to some degree but I feel like you can take their masterworks and do even more with it. \n\nSome of the hostiles in these parts still wear Ancient Imbued Silkweave Armor. Start to unstitch the silkweave cloth from any of that armor that you find on Broken Shore.", objectives = "" }
WordHunterWoW_QuestEN[46683] = { title = "Starweave and Shadowcloth", description = "At last, you are ready for true tailoring knowledge. I truly think you've earned it. \n\nI've fashioned the materials you've gathered into a satchel of Legendary Tailor's Materials. \n\nGo to the Queen's Grace Loom and weave two bolts of cloth. With my careful research of fashion, heroes, and legends. I believe the new cloth you will make will echo through the ages. Hurry!", objectives = "" }
WordHunterWoW_QuestEN[46684] = { title = "The Legend of the Elderhide", description = "Leatherworking is one of the oldest forms of craftsmanship in the world. Hides of animals were the first clothing. Legends tell of a particular form of leather curing that has been lost to us in modern times. \n\nCombining magic of the earth with some of the finest leathers ever found, this technique has been recreated by yours truly through careful analysis and my understanding of style. \n\nTo begin, you must capture some ancient wisps to channel the exact nature magic for the curing process.", objectives = "" }
WordHunterWoW_QuestEN[46685] = { title = "The Wisp and the Shadow", description = "{name}, have you heard of the nightmare lord, Xavius, whose shade haunts Darkheart Thicket? I have heard that this shade is sometimes seen wearing a colorless shroud. \n\nThis shroud is steeped in powerful magic and the wisp will draw it out for you. \n\nIf you can fight the shade, take the shroud, and use your skills to dye it, I will show you how to work wonders!", objectives = "" }
WordHunterWoW_QuestEN[46686] = { title = "The Wisp and the Sea", description = "Queen Azshara and her handmaidens are the subjects of many a tragic tale. Her power and her hubris lead her badly astray but, even so, her handmaidens are loyal to her to this day. There is power in such a thing.\n\nThe Wrath of Azshara is an abomination but, truthfully, it is actually one of her handmaidens who willingly gave her life to protect her queen. Few know this. The Ancient Wisp knows this truth and if you take it to battle the Wrath of Azshara, you may find the handmaiden's gloves. Restore them.", objectives = "" }
WordHunterWoW_QuestEN[46687] = { title = "The Wisp and the Nightmare", description = "Xavius, the Nightmare Lord in Val'Sharah, derives some of his power from his spellsash. It is enchanted and tied to the world beneath his feet and cannot be removed from his body. \n\nHowever, with the ancient wisp's help, the spellsash can be removed if you can but defeat Xavius in combat. Trivial for one of your skill, I'm sure. \n\nTake the wisp to the Emerald Nightmare, take the spellsash, and use your skills to repair any damage you've caused in the battle.", objectives = "" }
WordHunterWoW_QuestEN[46688] = { title = "Leather of the Ancients", description = "{name}, we are going to need high quality leather to work with. Ancient Dreadleather is the best hereabouts and local tanning techniques were exceptional in the past. To the untrained eye, it may look like normal dreadleather. That is where the wisp comes in. \n\nMany of your enemies across Broken Shore will have some amount of ancient dreadleather.  As you defeat them, you will start to recognize armor made from it and you can harvest the leather for our purposes.", objectives = "" }
WordHunterWoW_QuestEN[46689] = { title = "Wisp-Touched Elderhide", description = "Dreadleather, with knowledge carefully reverse-engineered from ancient texts, can be worked into elderhide. It is partly a matter of advanced craftsmanship and partly a simple magic of the earth. \n\nWith the ancient wisps you caught and the materials you've captured and the research I have done, I have put together a Legendary Tanner's Kit for you. Take it to the heirloom hides of Hrul Sharptooth in Thunder Totem. The wisp will help you use the kit there to create Elderhide.", objectives = "" }
WordHunterWoW_QuestEN[46690] = { title = "The Legend of the Wardenscale", description = "One of my favorite legends is of the Father of Owls on Isle of the Watchers. It is said that his spirit comes to comfort his creatures during times of trouble. \n\nWith the Legion's arrival on the Isle of Watchers, many of the owls are being slain so you can find him there. \n\nWe need to \"borrow\" him for a short time as he has seen many of the battles where famous warriors and villains have worn armor made of Wardenscale. With his spirit, you can identify items we can extract it from and use it for style!", objectives = "" }
WordHunterWoW_QuestEN[46691] = { title = "The Owl and the Traitor", description = "I've scoured the tales and legends for armor that might have Wardenscale components and one Cordana Felsong is a name that caught my attention. \n\nEvidently she has a family mantle that has what we need. Kill her and find it on her traitor's corpse. The owl will make sure that you spot it. \n\nIt is likely chipped from years of hard use so restore it to prime condition and bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[46692] = { title = "The Owl and the Dreadlord", description = "The demon Mephistroth is one of the most powerful of the Nathrezim--the dreadlords. I can see in your eyes that you know what I am going to ask you to do. But it is for your own good! You can't keep wandering the lands looking like you do. \n\nMost recently, Mephistroth has been dispatched by the Legion to the Cathedral of Eternal Night. No doubt, he will be wearing some legplates that I believe contain Wardenscale. Take them, shine them up, and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[46693] = { title = "The Owl and the Observer", description = "I've researched some foul creatures in my time but Viz'aduum the Watcher may top the list. I mean, he is a giant, disgusting, dangerous eyeball! \n\nCurrently he haunts Karazhan--do you know the place? In Medivh's time, much of our common knowledge was stored there. Alas, the time has passed... \n\nI digress. Viz'aduum is in possession of armor from the First War--bracers to be specific--and they are incredibly valuable. It pains me but take them, repair them, and then we must use their wardenscale.", objectives = "" }
WordHunterWoW_QuestEN[46694] = { title = "Mail of the Ancients", description = "There is some wardenscale scattered here and there in the Broken Isles. Various enemies and local monsters seeking to ape the superior races like ourselves will have picked it up and worn it. \n\nThe kind we need is amongst the oldest ever made. It is ancient gravenscale. Keep all that you find and and bring it to me. We will harvest what useful bits we can from it.", objectives = "" }
WordHunterWoW_QuestEN[46695] = { title = "Prime Wardenscale", description = "I feel like it is finally time for use to create something truly remarkable. To create the armor that will set you apart from the rest, we need to make the best wardenscale. \n\nFind the nightelf, Celea, in Azsuna. She has attuned and sanctified the ground where she waits to focus the magic of our world and only there can you make what we need. Go with speed, {name}.", objectives = "" }
WordHunterWoW_QuestEN[46696] = { title = "The Legend of the Four Hammers", description = "{name}, we should be honest with each other before we begin. You are a blacksmith by trade and this a noble profession. Yet I value style and fashion. Heavy armor and weapons create a certain bulkiness in a hero's profile that I think does no service whatsoever to the cut of one's clothes. \n\nFret not--I can at least teach you something about taste in finer materials. \n\nGo to Dalaran and find a book translated by my brother about 3 forgotten heroes. We will find the finest metals ever forged!", objectives = "" }
WordHunterWoW_QuestEN[46697] = { title = "The Godfighter", description = "The Godfighter championed the mortals against what he saw as oppression and abuse by immortal beings. The legends say the gods feared him but he did fall in time. \n\nMy research shows that the gods he fought were the gods of Stormheim. Odyn, in particular. The Godfighter's shield took so much damage from lightning bolts that it became lightningsteel. After the Godfighter died, Odyn took the shield and melted it down as a trophy. Get that lightningsteel from him and forge a hammer from it.", objectives = "" }
WordHunterWoW_QuestEN[46698] = { title = "The Dragonhunter", description = "The Dragonhunter lived in a time before history was written and her tale was passed down orally to us. \n\nIt seems that dragons tormented her people and after her village temple was destroyed, she rallied the local tribes, became a queen and killed all of the dragons. She was then banished for some reason and wandered until her death, alone. What proves the story is a piece of draconic slag from left over from a metal idol in her birth village. Dargul the Underking has it now. Forge a hammer from it.", objectives = "" }
WordHunterWoW_QuestEN[46699] = { title = "The Hellslayer", description = "The Hellslayer's tale is a classic story of revenge. Odyn wished to take the souls of the bravest as champions but Helya sent her kvaldir to take the souls first. The people of Stormheim suffered as their pawns. \n\nThe kvaldir came to the Hellslayer's ship at night and killed her son and took his soul to serve Helya for eternity. The Hellslayer took up her axe and the spear of her son and sought vengeance. Finish her quest. Defeat Helya and forge a hammer from the Frostveined Shale.", objectives = "" }
WordHunterWoW_QuestEN[46700] = { title = "Armor of the Ancients", description = "It is not just the hammers and my careful research that we need, {name}. We also need a lot of the very highest quality of ancient metal to make the final hammer. \n\nEnemies across Broken Shore that are able to wear armor often collect bits of Ancient Demonsteel here and there. Collect enough of it in your battles for our purposes.", objectives = "" }
WordHunterWoW_QuestEN[46701] = { title = "Hammer of Forgotten Heroes", description = "{name}, this is exciting, I have to admit. I've put everything you've gathered into this chest of supplies and the only place with the power and magic to handle the creation of the final hammer is the Firmament Stone. I believe that blacksmiths of your rarified skills will know it? \n\nI realize that there are dwarf stereotypes out there about smithing but I really don't care for all of the banging and heat. Suppose that is why I followed the scholarly path. Good luck to you!", objectives = "" }
WordHunterWoW_QuestEN[46705] = { title = "Retaliation", description = "Of course I will help you! Although to be honest, I am not certain where a new arcane shield generator can be found these days. So many of our craftspeople have been executed... I will think on it.\n\nWould you mind helping me as well? I have been observing a nearby group of Felborne for some time. Their activities have become increasingly brazen of late.\n\nI think it's time to teach them how it feels to be violently suppressed.", objectives = "" }
WordHunterWoW_QuestEN[46719] = { title = "Amal'thazad's Message", description = "Deathlord, Amal'thazad has requested your presence at Acherus.\n\nHe has been in contact with the Lich King, and making improvements on the citadel.\n\nFor his benefit, or yours, I know not.", objectives = "" }
WordHunterWoW_QuestEN[46720] = { title = "Frozen Memories", description = "Close your eyes, Deathlord. Can't you feel his presence already?\n\n<The Lich King's icy presence is inside your mind in an instant.>\n\nStand in the rune circle atop Acherus, Deathlord.\n\nI will show you what I have seen.\n\n<The presence fades.>", objectives = "" }
WordHunterWoW_QuestEN[46722] = { title = "Nothing Up My Sleeve", description = "Now, you may think that a sack of gold would be a good reward for your troubles, but I've got something better in mind for you.\n\nI'm gonna teach you my best trick!\n\nI know, I know, I'm a very generous goblin.   Let me show you how it's done!", objectives = "" }
WordHunterWoW_QuestEN[46723] = { title = "Down the Rabbit Hole", description = "Alright, bub. I'm gonna need you to go in there and find out what's going wrong.  I'd go in myself, but... well, it's complicated.\n\nAnyway, we got no time to lose! Just jump in the hat and find out what's goin on.\n\nI'll be ready to pull you out once you've got everything handled.", objectives = "" }
WordHunterWoW_QuestEN[46724] = { title = "Champion: The Great Akazamzarak", description = "You know, you're a useful fella to have around, {name}. \n\nTell ya what, I think I'll accompany you on your adventures. Seems to be good gold in it, and I think it'll be a good way to scout out some new business opportunities around the Broken Isles.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[46725] = { title = "Power Outage", description = "Kor'vass asked for a bunch of other stuff, but it won't hurt her to learn a bit of patience. Don't you agree?\n\nShe did mentioned that the ship'ss weaponss array is severely damaged and dangerously low on power. Knowing her, I'm sure that'ss an exaggeration.\n\nI suppose you may as well take this power core I confiscated. You can replenish it from those disgusting Legion geyserss and energy globess floating around the Tomb.", objectives = "" }
WordHunterWoW_QuestEN[46727] = { title = "Battle for Azeroth: Tides of War", description = "Champion!\n\nAn urgent War Council is underway. Your presence is requested in Stormwind Keep.", objectives = "" }
WordHunterWoW_QuestEN[46728] = { title = "The Nation of Kul Tiras", description = "Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore.\n\nMany have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father.\n\nPerhaps she feels the time has come to atone for this.\n\nLoath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[46729] = { title = "The Old Knight", description = "These days Cyrus is the Harbormaster, but he used to be one of Daelin Proudmoore's most trusted knights!\n\nI lost my mother when the Scourge hit Lordaeron. My father sent me here to be raised away from the war. I don't know much about him... just that he was a Stormwind knight who gave his life fighting the Lich King.\n\nDaelin hand-picked Cyrus to raise me and forced him to take a desk job. It's the only reason he wasn't at Theramore.\n\nHe's probably checking in that other Alliance ship. Let's go!", objectives = "" }
WordHunterWoW_QuestEN[46730] = { title = "Armies of Legionfall", description = "Thanks to your leadership, the {class} order has grown even mightier than I had dared hope. Alongside champions of the other orders, we now have a fighting force capable of driving the Burning Legion from our world.\n\nIt's time to end this invasion! Using the Pillars of Creation, we will dissipate the Felstorm and seal the Tomb of Sargeras.", objectives = "" }
WordHunterWoW_QuestEN[46732] = { title = "The Prophet's Gambit", description = "I can feel their presence just ahead. It is as faint as the lightest breeze that once rolled across these hills, but it is not of the Legion, of that I am certain.\n\nWe must see if these broken are potential allies. It is a great risk, but our numbers are too few to ignore the chance.", objectives = "" }
WordHunterWoW_QuestEN[46734] = { title = "Assault on Broken Shore", description = "It has been a long and costly war, {name}. It is time we put an end to it.\n\nWe will drive the Burning Legion from their seat of power and close their gateway into Azeroth. Our first step is to gain a foothold on the Broken Shore.\n\nDivided, the Alliance and Horde faced defeat. But united as the Armies of Legionfall, we will claim victory!", objectives = "" }
WordHunterWoW_QuestEN[46765] = { title = "The Broken Shore: Investigating the Legion", description = "While we focus efforts on the Broken Shore, we must be careful to guard against other threats. We have been getting disturbing reports on the Legion starting or supporting indirect threats to Azeroth.\n\nWhile you are on the Broken Shore, please keep an eye out for strange objects or intelligence that could give us a clue as to what and where these threats are.\n\nI know it is not a lot to go on, we will do our best from here as well.", objectives = "" }
WordHunterWoW_QuestEN[46769] = { title = "Relieved of Their Valuables", description = "Not all demons on this shore stomp around in the open. Some slink about in the shadows, finding more subtle ways to advance the Legion's cause.\n\nI have been observing the behavior of smaller demons, these wyrmtongues. They seem to spend considerable time acquiring objects of power. We cannot allow them to use these items against us.\n\nThe wyrmtongues stash their goods in chests spread around the Broken Shore. I suggest you relieve them of their ill-gotten gain.", objectives = "" }
WordHunterWoW_QuestEN[46772] = { title = "The Mage Tower", description = "Well done {name}. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Mage Tower.\n\nAll that remains is for you to inspect our work, and complete the construction.", objectives = "" }
WordHunterWoW_QuestEN[46773] = { title = "The Command Center", description = "Well done {name}. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Command Center.\n\nAll that remains is for you to inspect our work, and complete the construction.", objectives = "" }
WordHunterWoW_QuestEN[46774] = { title = "The Nether Disruptor", description = "Well done {name}. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Nether Disruptor.\n\nAll that remains is for you to inspect our work, and complete the construction.", objectives = "" }
WordHunterWoW_QuestEN[46778] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Einar the Runecaster to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46779] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Winstone Wolfe to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46780] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Loramus Thalipedes to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46781] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Journeyman Goldmine to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46782] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Chronicler Elrianne to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46783] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Survivalist Bahn to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46784] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Archivist Melinda to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46785] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Number Nine Jia to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46786] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Leafbeard the Storied to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46787] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Sir Alamande Graythorn to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46788] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Archon Torias to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46789] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Archivist Zubashi to continue advancing the Order Hall.", objectives = "" }
WordHunterWoW_QuestEN[46791] = { title = "Carried On the Wind", description = "Farseer {name}, Consular Celestos has requested your presence back at the Maelstrom. Please see him at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[46792] = { title = "Gathering of the Storms", description = "Thunderaan has asked me to send you to the Throne of the Four Winds to assist him with a situation.\n\nSpeak with me again when you're ready to leave, Farseer.", objectives = "" }
WordHunterWoW_QuestEN[46794] = { title = "Paragon of the Court", description = "The grateful Court of Farondis has requested your presence. They wish to reward you for your exceptional aid.", objectives = "" }
WordHunterWoW_QuestEN[46796] = { title = "Paragon of Highmountain", description = "The grateful Highmountain Tribes have requested your presence. They wish to reward you for your exceptional aid.", objectives = "" }
WordHunterWoW_QuestEN[46797] = { title = "Paragon of the Dreamweavers", description = "The grateful druids of the Dreamweavers have requested your presence. They wish to reward you for your exceptional aid.", objectives = "" }
WordHunterWoW_QuestEN[46798] = { title = "Paragon of the Valarjar", description = "The impressed vrykul of the Valarjar have requested your presence. They wish to reward you for your exceptional aid.", objectives = "" }
WordHunterWoW_QuestEN[46799] = { title = "Paragon of the Nightfallen", description = "A very grateful Thalyssra has requested your presence. She wishes to reward you for your exceptional aid.", objectives = "" }
WordHunterWoW_QuestEN[46800] = { title = "Paragon of the Wardens", description = "The impressed Wardens have requested your presence. They wish to reward you for your exceptional aid.", objectives = "" }
WordHunterWoW_QuestEN[46802] = { title = "Paragon of the Legionfall Armies", description = "Your loyal forces in the Armies of Legionfall have requested your presence. They wish to reward you for your exceptional aid.", objectives = "" }
WordHunterWoW_QuestEN[46804] = { title = "Fashion History and a Philosophy of Style", description = "Greetings, {name}. I am a fashion historian and I have astonishing advancements in tailoring, leatherworking, and blacksmithing that I must share with you. Why? \n\nA true legend is only as good as their ability to form an epic silhouette on the battlefield and--let's be honest--this is not where you shine. \n\nSpeak to me again if you wish to learn.", objectives = "" }
WordHunterWoW_QuestEN[46805] = { title = "The Deceiver's Downfall", description = "Once he was as a brother to me. Then he bartered the soul of my world for his own power. Hounded my people across the stars. Twisted my son into a monster.\n\nNow he has come to oversee the final assault on Azeroth. To end this world as he has countless others.\n\nKil'jaeden.\n\nWe must ensure he does not escape our grasp this time, {name}. Storm the tomb. Break the Legion's hold. End the Deceiver's reign.", objectives = "" }
WordHunterWoW_QuestEN[46812] = { title = "Draconic Secrets", description = "<The Lich King's icy presence enters your mind once more.>\n\nArthas never found the prize he sought, Deathlord.\n\nIt is ours by right.\n\nThe dragons must know where the resting place of their kin resides.\n\nFind a member of the bronze flight, the tenders of history. Do not be merciful.\n\n<The presence fades.>", objectives = "" }
WordHunterWoW_QuestEN[46813] = { title = "The Lost Glacier", description = "<The Lich King's presence is overwhelming.>\n\nDo you know why the red dragonflight seeks to prevent us from finding our prize?\n\nThe bones of a great red dragon teem with the essence of life, even decades after its passing.\n\nYou will consume this life essence, blight it, and turn it to undeath.\n\nAnd then you will raise a dragon.\n\nFly now into the north. Find this glacier, and your destiny.\n\n<The presence fades.>", objectives = "" }
WordHunterWoW_QuestEN[46815] = { title = "Eredath, Jewel of Argus", description = "The shattered ruin below us is all that remains of Eredath.\n\nWe called it the Jewel of Argus. It was here that my fellows in the triumvirate guided our people to prosperity. That was a long time ago.\n\n<Velen lapses into a moment of silence.>\n\nJoin me on the surface. We will begin our search for the Crown of the Triumvirate.", objectives = "" }
WordHunterWoW_QuestEN[46816] = { title = "Rendezvous", description = "There is much to be done before this nightmare can end, but we need to regroup before we draw more attention from the Legion.\n\nI managed to retain a signal crystal during the crash used to call transport beacons from the Xenedar.\n\nWith luck, we should be able to use it to establish a link between here and your forces as well.", objectives = "" }
WordHunterWoW_QuestEN[46818] = { title = "Defenseless and Afraid", description = "This is the battle that raged while I awaited the Genedar. So many ran to join me, but Kil'jaeden inspired still more to stand in their way.\n\nMy people were slaughtered without mercy.\n\nTo cover our retreat I ordered for this arena's defenses to be activated. It is clear that they were unable.\n\nTo turn the tide in this battle, to give these spirits rest, we must do what they could not. Find a way to activate the pylons.", objectives = "" }
WordHunterWoW_QuestEN[46827] = { title = "Meld Into the Shadows", description = "We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.", objectives = "" }
WordHunterWoW_QuestEN[46832] = { title = "Aalgen Point", description = "You wanna hold territory on this chunder puddle of an island, right? Right. That means linkin' up with camps on the outskirts, mate. \n\nI know this bloke called Heidirk. Scrappy fella, loves to get into the thick of it. Headed out to the eastern coast with those drakes of his.\n\nHave a look for him. Remind him he owes me a pint or two!", objectives = "" }
WordHunterWoW_QuestEN[46834] = { title = "Khazaduum, First of His Name", description = "The Argunite Matrix that powered this part of Eredath was shattered by a hulking beast. We had never seen another like him.\n\nHe was called Khazaduum and he was a most faithful servant of the Legion. He volunteered to undergo an experimental transformation to become the first of his kind. His arrival was the end of this battle.\n\nAs a prize he took the Argunite Keystone from the shattered matrix. Take it back and we can finally end this bloodshed.", objectives = "" }
WordHunterWoW_QuestEN[46839] = { title = "From Darkness", description = "I'm afraid it's only a matter of time before our presence is known.\n\nWe must begin our preparations at once.", objectives = "" }
WordHunterWoW_QuestEN[46840] = { title = "Prisoners No More", description = "Hatuun's people have endured arduous times. Their numbers dwindle as those ripped from beyond the walls of their sanctuary become servants to the annihilan lords in the pits just beyond, sentenced to a life of labor, torture and ultimately, death.\n\nSeek out these captives, release them from their bonds and show our allies we stand as one against the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[46841] = { title = "Threat Reduction", description = "In time, Hatuun and his people will set aside their bitterness and become valuable allies. But their trust must be earned.\n\nHe says their village is beset by a demon called Aggonar and his cruel kin.\n\nWe need these fiends out of the way before we can seek out Alleria and the others.\n\nThe chieftain lent us his horn. Use it to call down his people's vengeance upon the demon lieutenants while I carve a path to Aggonar's lair.", objectives = "" }
WordHunterWoW_QuestEN[46842] = { title = "A Strike at the Heart", description = "These pits have long been a blight upon the lives of our new allies. The demons hunt them down and torture the poor souls for sport.\n\n<Turalyon shakes his head with disgust, fixing his gaze upon the beast before him.>\n\nIt is time to make them pay for their cruelty and restore hope to this Light-forsaken place.\n\nWe strike on your mark, {name}.", objectives = "" }
WordHunterWoW_QuestEN[46843] = { title = "Return to the Vindicaar", description = "That pit lord won't trouble our new allies any longer.\n\n<Turalyon's brow furrows.>\n\nUntil another takes its place, at least. If there's one thing I've learned in our endless war against the Legion, it's to savor victories as you find them.\n\nCome, let us take a moment to regroup back at your vessel. Alleria and I have been waiting a long time for a reunion with our son.", objectives = "" }
WordHunterWoW_QuestEN[46845] = { title = "Vengeance Point", description = "On my way here, I ran across a squad of demon hunters headed northwest to Vengeance Point. You can bet the Legion will try to stop them from establishing a forward position.\n\nI spoke to an elf named Izal Whitemoon. Not the friendliest sort, but I'm sure she'd be grateful if you lent the Illidari a hand... whether she admits it or not.", objectives = "" }
WordHunterWoW_QuestEN[46846] = { title = "The Word of Zul", description = "I have a mundane task for you. Our esteemed Prophet Zul has words to distribute to very specific individuals in de port. \n\nAnd he requested you be de one to deliver dem.\n\nDon't ask me why he didn't just have you deliver these when you were here de first time. De prophet is notorious for not sharing all of his visions.", objectives = "" }
WordHunterWoW_QuestEN[46924] = { title = "The Wolf's Tale", description = "Goldrinn sure didn't take any time getting out of here, did he?\n\nLet's go see if we can find him outside.", objectives = "" }
WordHunterWoW_QuestEN[46926] = { title = "Shakedown", description = "Where are de guards? \n\nPrincess Talanji has convinced King Rastakhan to permit outsiders in our port. For de first time in centuries, we have allowed non-trolls to set foot on our shores and peddle their wares.\n\nAnd now trolls of lesser tribes seem to think dey can take advantage of these merchants?\n\nI will not allow dis sort of behavior. While I investigate why de merchants are not protected, I want you to work your way through de bazaar and slay any thugs you find. \n\nSend dem a message.", objectives = "" }
WordHunterWoW_QuestEN[46927] = { title = "Punishment of Tal'aman", description = "Look, Zolani is going about dis all wrong. If you want de Amani, or anyone, to pay attention, take out their leaders.\n\nGo into Tal'aman and look for their mighty gong. Challenge four of their disciples to combat and slay dem.", objectives = "" }
WordHunterWoW_QuestEN[46928] = { title = "Punishment of Tal'farrak", description = "De Sandfury tribe may have had a hand in some crime around here, but it is really their false belief system dat makes dem do dis sort of thing. Enter Tal'farrak, bang de gong within, and face de hydra dey keep as a sacred pet.\n\nBring me dis thing's tongues.", objectives = "" }
WordHunterWoW_QuestEN[46929] = { title = "Deterrent", description = "General Jakra'zet had orders to ensure dis place had protection. Guard protection. I see none of dat.\n\nJakra'zet is a stubborn general, and one I have had my eye on for a while now.\n\nRegardless, we must remind dese lesser tribes who rules dis city with a message dey will understand.\n\nI charge you with collecting heads.\n\nEnter Tal'farrak and Tal'aman, and collect a quota of heads.", objectives = "" }
WordHunterWoW_QuestEN[46930] = { title = "Rastakhan", description = "You stand before General Jakra'zet, lord of de armies of Zandalar, enforcer of her seas and bringer of war.\n\nAnd I do not like you. \n\nIt took years to earn my place here after your Horde laid waste to my people. You will not undo what I have built.\n\nI will see you kneel before King Rastakhan. I will watch you beg as he lets me take your head for a trophy. I will fling your corpse into de wastes of Vol'dun.\n\nHer \"Highness\" may object... but she is not queen yet.\n\nCome. Let us fly to your fate.", objectives = "" }
WordHunterWoW_QuestEN[46931] = { title = "Speaker of the Horde", description = "Your Horde has grown powerful, eclipsing some of de troll empires in its magnitude.\n\nFor saving my daughter, you have earned de right to a presence in my city.\n\nSince my daughter has taken such a fondness to you, you may join her in de Great Seal beneath us. De servants there will answer to you now.\n\nTalanji seems excited by whatever she has planned for your people. I look forward to being amused by it later.\n\nZolani can show you a way down dat does not involve falling.", objectives = "" }
WordHunterWoW_QuestEN[46935] = { title = "The Shadow of the Sentinax", description = "This device appears to be used to relay messages to the large demon ship up above. Unfortunately, it is cracked and unresponsive.\n\nPerhaps someone at Deliverance Point will know more about these beacons.", objectives = "" }
WordHunterWoW_QuestEN[46938] = { title = "Alone in the Abyss", description = "Champion, we will suffer the same fate as the Army of the Light if the Legion fires that infernal weapon upon us.\n\nWe must descend into the siege camp below and destroy it while we still can!", objectives = "" }
WordHunterWoW_QuestEN[46941] = { title = "The Path Forward", description = "<Velen stares beyond the arena for a time.>\n\nWe must continue on, but I feel Eredath is far from finished with us. We should take advantage of this relative safety while we still can.\n\nI will place a signal beacon that will allow the Vindicaar to lock onto our location. Romuul will send us our means of returning to the Vindicaar if there is a need.", objectives = "" }
WordHunterWoW_QuestEN[46957] = { title = "Welcome to Zuldazar", description = "Champion of de Horde, welcome to de city of Zuldazar, capital of de Zandalari Empire, de jewel of all troll civilizations.\n\nI would have you ride by my side so we might discuss matters without prying ears close at hand.", objectives = "" }
WordHunterWoW_QuestEN[47000] = { title = "The Council's Call", description = "I'm sorry that I haven't kept your apprised of the situation. We needed more actionable information before bringing the matter before you.\n\nThe Council of the Six has been investigating Legion threats outside of the Broken Shore. I believe this scroll to be the final piece of information we need.\n\nMeet me in Dalaran at the Violet Citadel. We will need the other members of the Council.", objectives = "" }
WordHunterWoW_QuestEN[47002] = { title = "The Crown of the Triumvirate", description = "We begin our search now, {name}.\n\nThe Crown of the Triumvirate was created to spread the Light's touch to all. With it, our culture thrived.\n\nWhen I fled Argus with the Draenei, I took one shard of the Crown with me to ensure that it would not fall into the wrong hands.\n\n<Velen tips his staff forward and gestures to the central crystal.>\n\nKil'jaeden and Archimonde's fragments are still here. I will seek them out, but you will need to safeguard me while I search.\n\nStay close, my friend.", objectives = "" }
WordHunterWoW_QuestEN[47003] = { title = "Restoration: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.\n\nSpecialization: Restoration Shaman", objectives = "" }
WordHunterWoW_QuestEN[47004] = { title = "Restoration: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.\n\nSpecialization: Restoration Druid", objectives = "" }
