WordHunterWoW_QuestEN[47018] = { title = "Beast Mastery: Rumblings Near Feltotem", description = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later.\n\nThe drogbar chieftain, Navarrogg, is handling this personally and we'd like you to meet him near the Feltotem village.\n\nSpecialization: Beast Mastery Hunter", objectives = "" }
WordHunterWoW_QuestEN[47019] = { title = "Windwalker: Rumblings Near Feltotem", description = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later.\n\nThe drogbar chieftain, Navarrogg, is handling this personally and we'd like you to meet him near the Feltotem village.\n\nSpecialization: Windwalker Monk", objectives = "" }
