WordHunterWoW_QuestEN[47027] = { title = "Legion Threat: Val'sharah", description = "It appears you have grown strong enough to take on another Legion threat. If you could speak to Archmage Modera in Dalaran as soon as possible, the Council would be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[47029] = { title = "Holy: A Threat in Val'sharah", description = "It appears you have grown strong enough to take on another Legion threat. If you could speak to Archmage Modera in Dalaran as soon as possible, the Council would be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[47030] = { title = "Legion Threat: Dalaran Infiltration", description = "It appears you have grown strong enough to take on another Legion threat. If you could speak to Archmage Ansirem in Dalaran as soon as possible, the Council would be in your debt.", objectives = "" }
