WordHunterWoW_QuestEN[47033] = { title = "Legion Threat: Suramar", description = "It appears you have grown strong enough to take on another Legion threat. I'd like you to meet with the Council of the Six in Dalaran as soon as possible. Thank you.", objectives = "" }
WordHunterWoW_QuestEN[47034] = { title = "Legion Threat: The Necromancer", description = "It appears you have grown strong enough to take on another Legion threat. I'd like you to meet with Archmage Karlain as soon as possible. Thank you.", objectives = "" }
WordHunterWoW_QuestEN[47035] = { title = "Legion Threat: The Missing Mage", description = "It appears you have grown strong enough to take on another Legion threat. If you could speak to Archmage Modera in Dalaran as soon as possible, the Council would be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[47037] = { title = "Balance: The Twisted Twin", description = "I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.\n\nOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.\n\nFind Karam in the Legerdemain Lounge and see if you can lend a hand.\n\nSpecialization: Balance Druid", objectives = "" }
WordHunterWoW_QuestEN[47039] = { title = "Marksmanship: The Twisted Twin", description = "I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.\n\nOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.\n\nFind Karam in the Legerdemain Lounge and see if you can lend a hand.\n\nSpecialization: Marksmanship Hunter", objectives = "" }
