WordHunterWoW_QuestEN[47043] = { title = "Havoc: The Thieving Apprentice", description = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him.\n\nFortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem.\n\nI'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.\n\nSpecialization: Havoc Demon Hunter", objectives = "" }
WordHunterWoW_QuestEN[47046] = { title = "Frost: The Thieving Apprentice", description = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him.\n\nFortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem.\n\nI'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.\n\nSpecialization: Frost Death Knight", objectives = "" }
