WordHunterWoW_QuestEN[47055] = { title = "Fire: The Folly of Levia Laurence", description = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.\n\nShe was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail.\n\nSpecialization: Fire Mage", objectives = "" }
WordHunterWoW_QuestEN[47056] = { title = "Fury: The Folly of Levia Laurence", description = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.\n\nShe was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail.\n\nSpecialization: Fury Warrior", objectives = "" }
WordHunterWoW_QuestEN[47057] = { title = "Unholy: The Folly of Levia Laurence", description = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.\n\nShe was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail.\n\nSpecialization: Unholy Death Knight", objectives = "" }
WordHunterWoW_QuestEN[47058] = { title = "Outlaw: The Folly of Levia Laurence", description = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.\n\nShe was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail.\n\nSpecialization: Outlaw Rogue", objectives = "" }
WordHunterWoW_QuestEN[47059] = { title = "Feral: The Folly of Levia Laurence", description = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.\n\nShe was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail.\n\nSpecialization: Feral Druid", objectives = "" }
WordHunterWoW_QuestEN[47066] = { title = "Consecrating Ground", description = "We have everything we need.\n\nIn the alcove below you will find the shattered remains of the Argunite Matrix. Replacing the Keystone will restore it to full capacity.\n\nThe pylons you activated will then be able to repel those who still hunt my people. At long last this battle will be over.\n\nI hope it brings them peace.", objectives = "" }
WordHunterWoW_QuestEN[47097] = { title = "A Walk to Remember", description = "It's good to have you at my side, {name}.\n\nI've come to the Broken Shore to see, for myself, the price that my father... that the Alliance has paid to protect our world.\n\nAs long as I am blind to the suffering and sacrifices of my people, I will never be able to lead them to peace.\n\nTime is short, we should move onward.", objectives = "" }
WordHunterWoW_QuestEN[47098] = { title = "Out Like Flynn", description = "I'm relieved you woke up! Having to carry you would have made this job far less appealing.\n\nThe name's Flynn, and my client in Boralus is paying me a king's bounty to break you out of here.\n\nYou, my friend, are incarcerated in Tol Dagor. Used to be a legit prison... 'til the Ashvane Trading Company bought it. Now it's Priscilla's own personal fortress, riddled with scum on both sides of the bars.\n\nWasn't hard to bribe my way into this cell. Now we just have to get out.\n\nNot to worry. I have a plan!", objectives = "" }
WordHunterWoW_QuestEN[47099] = { title = "Get Your Bearings", description = "I think a proper introduction is in order!\n\nMy name is Taelia, member of the Proudmoore Guard and squire of Sir Cyrus Crestfall.\n\n<Taelia salutes firmly.>\n\nCyrus asked me and Flynn to break you out of that Ashvane prison and get you settled in here at the market, but he neglected to mention that you're with the Alliance.\n\nI must say, it's an honor.\n\nLet's get you up to speed.", objectives = "" }
WordHunterWoW_QuestEN[47100] = { title = "Arkhaan's Pain", description = "Darkness envelops us... the Light has gone from this place...\n\n<Arkhaan mumbles to himself before noticing you are still talking to him.>\n\nArkhaan could not save them. Brothers. Sisters. Whispers twisted them. The Light cannot see them. It turns away from us.\n\nArkhaan failed.\n\n<Arkhaan stares off into space.>", objectives = "" }
WordHunterWoW_QuestEN[47101] = { title = "Arkhaan's Prayers", description = "<As you near the statue, a somber voice fills your mind.>\n\n\"You must resist the shadow's pull. Come to me, brothers and sisters. Be whole within the Light.\n\nLet Arkhaan show you the way home.\"\n\n<The rest of the message is garbled, though the nearby broken seem to be gnawing on pieces of the statue.>", objectives = "" }
WordHunterWoW_QuestEN[47102] = { title = "The Mysterious Missive", description = "<On the body, you find a missive emblazoned with the seal of the Army of the Light. \n\nIf the messenger was killed to prevent the letter's delivery, its contents must be of great import.>", objectives = "" }
WordHunterWoW_QuestEN[47103] = { title = "Journey to Nazmir", description = "It is time to put an end to de blood trolls in Nazmir before their monstrous horde descends upon Zuldazar.\n\nMy most loyal followers are willing to come with me to dat cursed place. But it will not be enough.\n\nI am relieved dat you and de Horde are willing to help. Rokhan and his darkspears are getting ready to leave.\n\nI will finish my preparations here. Meet with Rokhan and make your way to Nazmir, I will see you there.", objectives = "" }
WordHunterWoW_QuestEN[47104] = { title = "Imprisoned Inquisitor", description = "This report states that the Legion seeks to free an imprisoned Legion inquisitor called Raalgar, a demon from here on Argus who cannot be killed because of a secret magic he alone possesses. \n\nBecause of his immortality, he is held in the Arcatraz in Tempest Keep.\n\nThe Light Mother told us of that naaru stronghold, but I've never set eyes upon it myself, {name}. Turalyon mentioned the Vindicaar has some connection to Tempest Keep. Perhaps your ship's engineer knows more.", objectives = "" }
WordHunterWoW_QuestEN[47105] = { title = "Into The Darkness", description = "We are in Nazmir to stop de blood trolls from destroying Zuldazar. Dis is de start of our campaign to end dem.\n\nDese monsters want my kingdom and its people destroyed. We are going destroy dem first.\n\nMy father thinks de blood troll threat will go away on its own, like it did in de past. But things are different now.\n\nRokhan and de others are moving north of here to establish a camp for us to stay in, den dey will join us in de fight.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[47112] = { title = "Lost Souls", description = "Never in my life have I beheld such destruction... such misery. The very ground we walk on us paved with the bones of our allies.\n\nEven now I can see the lost spirits of Alliance soldiers wandering the ruins.\n\nI cannot leave this place without putting the souls of our brave soldiers to rest. We owe them... I owe them that much.", objectives = "" }
WordHunterWoW_QuestEN[47130] = { title = "Improper Burial", description = "De blood trolls are gathering de corpses of my people for their blood magic. Dis ends today.\n\nI will take care of de corpses here. Take dis torch. Its fires are blessed by priests of Bwonsamdi, de loa of death. \n\nBurn any corpses of my people dat you see. Each corpse burned means less power for dese monsters' blood magic.", objectives = "" }
WordHunterWoW_QuestEN[47134] = { title = "Foiling the Legion's Jailbreak", description = "High Inquisitor Raalgar has some connection to the fel here on Argus that makes him unkillable. Long ago, the naaru imprisoned him on the Arcatraz. \n\nWhen the forces of Kael'thas Sunstrider attacked the citadel, we were forced to flee on the Exodar.\n\nSome Legion prisoners escaped the Arcatraz when last the Legion invaded Azeroth, but Raalgar did not. Stop them from freeing him and I will study the source of his immortality so it can be broken. \n\nI can get you close. The rest is up to you.", objectives = "" }
WordHunterWoW_QuestEN[47137] = { title = "Champions of Legionfall", description = "The battle to reclaim the Broken Shore is straining our resources. We cannot afford to relent, lest the Legion undo all that we have accomplished.\n\nThe members of your order have given much, but more is needed.\n\nRally your champions and do what you must to bolster their ranks. There may be untapped power in this land that will turn the tide of war in our favor.", objectives = "" }
WordHunterWoW_QuestEN[47139] = { title = "Mark of the Sentinax", description = "The Sentinax rains down terror upon the Broken Shore, unleashing hordes of demons that menace our forces. The fiends seek to stop us from taking the Tomb.\n\nThey will fail.\n\nLure out the strongest among their vile ranks. Slay them and seize the marks they bear. Make the Legion fear our strength!", objectives = "" }
WordHunterWoW_QuestEN[47148] = { title = "Something Different", description = "Even the most bloodthirsty combatants eventually grow weary and turn their backs to the unending struggle of war. They seek a new way to test their mettle and destroy their enemies. \n\nJoin the Brawl in progress and fight your opponents in a limited time event that tosses traditional rules aside.", objectives = "" }
WordHunterWoW_QuestEN[47180] = { title = "The Pulsing Madness", description = "This broken still retains some of his sanity, though not all of it.\n\nI can sense some Void influence nearby, but it is isolated to small pockets. Dispelling these manifestations should help our friend here clear his mind.\n\nPerhaps we can use the prayer fragments you found, as they still contain some Light energy.\n\nI will try and make sense of his chattering in the meantime. Maybe we can learn something about what is happening here.", objectives = "" }
WordHunterWoW_QuestEN[47181] = { title = "The Smoking Gun", description = "The Ashvane Company doesn't know it yet, but throwing you into Tol Dagor was the biggest mistake they've ever made.\n\nThat new powder we swiped could be the key to bringing them down.\n\nFirst, how about we give everyone a little demonstration of just how powerful this stuff is?\n\n<Flynn loads a pinch of the glittering powder into his pistol.>\n\nGo ahead, take a shot at that barrel over there.", objectives = "" }
WordHunterWoW_QuestEN[47182] = { title = "Long Overdue", description = "I have learned much. High Inquisitor Raalgar has moved to a base near the Legion citadel across the mountains. This is where he keeps the Fel Heart of Argus, the source of his immortality, and it is powered by wells leading directly to the core of Argus. \n\nHe is preparing to attack so you will strike first. Mark the location of the wells and I will rain holy fire upon them with the Vindicaar's guns. With that connection to the fel on Argus broken, Raalgar can be killed and the Fel Heart retrieved.", objectives = "" }
WordHunterWoW_QuestEN[47183] = { title = "Arkhaan's Plan", description = "Arkhaan remembers. He remembers something that will... yes... will save us.\n\nFollow Arkhaan. Isolon calls! We will offer soft words to the Light. The Light will banish the darkness.\n\n<Arkhaan eyes Alleria warily.>\n\nArkhaan will watch that one closely.", objectives = "" }
WordHunterWoW_QuestEN[47184] = { title = "Arkhaan's Peril", description = "Whatever called to him, it cannot have good intentions. We need to go in after him.\n\nBefore we step through this portal, {name}... ensure you are prepared to fight. The Void's influence is rarely peaceful.", objectives = "" }
WordHunterWoW_QuestEN[47186] = { title = "Sanctum of the Sages", description = "Sounds like you'll be working with us for awhile.\n\nCyrus will charter a naval transport between here and Stormwind, but I expect you'll want something a bit faster for day to day use.\n\nHead back upstairs and take a left when you get outside. You'll find an old study where the Tidesages used to conduct their magic rituals.\n\nSurely your Alliance mages have already sensed its power.\n\nInform them they may open their portals there. The harbor guards will keep the room secure.", objectives = "" }
WordHunterWoW_QuestEN[47188] = { title = "The Aid of the Loa", description = "De blood trolls are stronger than ever, thanks to dis G'huun... and now dey are empowering a giant construct!\n\nWe need a plan to destroy dat construct, G'huun, and de blood trolls. It is not going to be easy.\n\nBut I have an idea.", objectives = "" }
WordHunterWoW_QuestEN[47189] = { title = "A Nation Divided", description = "Kul Tiras must be unified before it can be of any help to the Alliance.\n\nLet's get you briefed on the current situation in each of our major territories.\n\nThen you can take a look at the map behind me and make the call on where you want to go first.", objectives = "" }
WordHunterWoW_QuestEN[47198] = { title = "They Want Us Alive", description = "Blood troll poisons are made to paralyze, not kill. See, dey want us alive.\n\nI do not feel good thinking about why.\n\nI am making antitoxins as quickly as I can, but I need someone like yourself to get out dere and test dem. Take what I have made so far and see if we can get those soldiers back on their feet.", objectives = "" }
WordHunterWoW_QuestEN[47199] = { title = "The Blood Gate", description = "We just received word that the Northern border is under heavy attack by an army of blood trolls.\n\nKing Rastakhan has called for reinforcements.\n\nYou are more familiar with that threat than any of us. Go and do what you can to help them.", objectives = "" }
WordHunterWoW_QuestEN[47200] = { title = "Ticks", description = "Kill those bloodbellies before dey take off with all of my soldiers! I will have my troops prepare for a flanking charge.", objectives = "" }
WordHunterWoW_QuestEN[47201] = { title = "Rokhan", description = "My scouts have informed me dat your Darkspear shadow hunter, Rokhan, has returned from Nazmir. He is pinned down at de far side of de gate.\n\nWe need to break dis onslaught with a flanking maneuver.\n\nOld Rotana is in position. Mount up and smash through de side of those blood troll ranks.\n\nOnce down dere, try to find Rokhan.\n\nOh, and {name}, be careful. A lot of dark magic is being tossed around down dere.", objectives = "" }
WordHunterWoW_QuestEN[47202] = { title = "A Personal Message", description = "The time has come for me to travel to the Broken Shore and see, for myself, the place where my father died.\n\nIf I am to be the king my father was... the king Stormwind deserves, I must know firsthand the threat my people face.\n\nPlease tell my advisors that I've gone to the Broken Shore. If I told them myself they'd only try and stop me.\n\nI'll wait for you at Deliverance Point. Farewell.", objectives = "" }
WordHunterWoW_QuestEN[47203] = { title = "Throwing Shade", description = "That was Locus-Walker. He taught me all that I know about the Void, and he still has more to teach me.\n\nIf he is here, then the ethereals' presence only intrigues me further. I had thought him the only one of his kind, but now that I have seen another tangling with the Void...\n\nCome, we must play his game if we want to learn what he knows. He appears to have gone toward the Umbra Hollows to the north.", objectives = "" }
WordHunterWoW_QuestEN[47204] = { title = "The New Frontline", description = "Kill anything ya see dat not a Zandalari!", objectives = "" }
WordHunterWoW_QuestEN[47205] = { title = "Warmother", description = "Old Rotana be cursed by da warmother dese vile blood trolls brought with dem. We need to take her down so we can get dis old direhorn back in da field.", objectives = "" }
WordHunterWoW_QuestEN[47217] = { title = "Sources of Darkness", description = "I think I understand what he was trying to show us, {name}.\n\nI feel a surge of power building ahead. They must be cultivating the Void, calling it here.\n\nWe need to stop them before they plunge this entire city into shadow. Find the source and cut it off by any means necessary.\n\nLocus-Walker and I have unfinished business to attend to.", objectives = "" }
WordHunterWoW_QuestEN[47218] = { title = "The Shadowguard Incursion", description = "As you have surely gathered by now, a certain subset of my people have tragically succumbed to the call of the Void.\n\nI had hoped to find more who possess the necessary strength of mind. I am disappointed to find such an utter lack of resistance.\n\nIt cannot be helped. To advance your cause, and mine, we will need to eradicate these weak-willed beings.", objectives = "" }
WordHunterWoW_QuestEN[47219] = { title = "A Vessel Made Ready", description = "After some consideration, I have decided to allow Alleria another opportunity to pursue her destiny.\n\nI suppose you want to know what that means, mortal.\n\n<Locus-Walker laughs.>\n\nMeet us deep in the Shadowguard camp ahead- my brethren are preparing a summons that will provide adequate energy for Windrunner to begin again.\n\nWitness what happens when you harness the Void's power.", objectives = "" }
WordHunterWoW_QuestEN[47220] = { title = "A Beacon in the Dark", description = "That was... an intense experience.\n\n<Alleria rubs her forehead.>\n\nIt is difficult to focus. I need you to return to Velen. Give him this.\n\n<She places something cold and dense in your palm.>\n\nI feel as though he should have it, though I am not sure why.\n\nTell him all that we have learned. I am sure Romuul will have been watching our progress. With any luck, a beacon is already headed our way.", objectives = "" }
WordHunterWoW_QuestEN[47221] = { title = "The Hand of Fate", description = "{name},\n\nWe have won many battles against the Burning Legion, but it is time to end this war once and for all. \n\nFinal preparations have begun to depart for Argus.\n\nMake haste to Stormwind Harbor. A ship awaits you there to grant you and your allies passage to Azuremyst.", objectives = "" }
WordHunterWoW_QuestEN[47222] = { title = "Two If By Sea", description = "The Tomb of Sargeras was only the beginning. If we do not destroy the Legion utterly, they will return even stronger.\n\nWe will travel to Azuremyst by sea to avoid drawing unnecessary attention. The less time the Legion has to react to our assault, the better.\n\nJust say the word when you are ready to depart.", objectives = "" }
WordHunterWoW_QuestEN[47223] = { title = "Light's Exodus", description = "Prophet Velen and the others have gathered within the Vault of Lights below. There is an entrance just down this path.\n\nWe should find the Prophet at once so that we do not stall the invasion.", objectives = "" }
WordHunterWoW_QuestEN[47224] = { title = "The Vindicaar", description = "Everything is prepared for our assault. We need only establish the beacon to transport us to the vessel.\n\nOnce the beacon arrives, place your hand upon its surface to board the Vindicaar, the instrument of our retribution.", objectives = "" }
WordHunterWoW_QuestEN[47226] = { title = "The Orphaned Hatchling", description = "<The surviving hatchling bleats piteously as it gazes at its mother's corpse.\n\nIt inspects you hopefully and seems to want to follow you.\n\nPerhaps you can find someone in Warbeast Kraal who can care for it?>", objectives = "" }
WordHunterWoW_QuestEN[47228] = { title = "Xibalan Ecology", description = "I had really hoped this area would be more hospitable.\n\nThe Zandalari have been no help whatsoever in clearing this space for archaeological exploration. Before we can even begin to uncover Xibala's secrets, we must make it safe for those less combat savvy to do their work.\n\nYou will find the ruins ahead infested with all manner of carnivorous beasts. The few intrepid explorers who ventured within have all failed to return.\n\nLocal ecology will not stand in the way of progress, {name}. Understand?", objectives = "" }
WordHunterWoW_QuestEN[47229] = { title = "Bulwark of Torcali", description = "We got Old Rotana up on her feet again. Load up an' take her reins.\n\nGive us some cover so Talanji can fight her way in from her side.", objectives = "" }
WordHunterWoW_QuestEN[47235] = { title = "Scrying for the Eye", description = "On behalf of the Horde we seek a relic called the Eye of Xibala.\n\nThe locals have been no help whatsoever and Miss Tae'shara insists that we use her survey equipment.\n\nI abhor guesswork. Instead we shall use a more direct method: scrying.\n\nI will mark three locations on your map. I would like you to place a scrying vessel at each of them. I will use their measurements to isolate the relic's location and we will be on our way.", objectives = "" }
WordHunterWoW_QuestEN[47238] = { title = "The Seat of the Triumvirate", description = "Even with the Sigil of Awakening in hand, the Crown cannot save us until it is whole.\n\nThat is why we must enter the Seat of the Triumvirate, even knowing that L'ura awaits us there.\n\nThis is a dire task, one that I would not ask if it were not completely necessary.\n\nWe will descend together. Come.", objectives = "" }
WordHunterWoW_QuestEN[47241] = { title = "The Shadow of Death", description = "We have four loa, but we only know where one is: Bwonsamdi.\n\nAs uncomfortable as it makes me, I am prepared to do anything to stop de blood trolls... even if it means dealing with de loa of death.\n\nAges ago, Bwonsamdi had a temple here in Nazmir. My scrying has revealed a few locations to de north where I sense a magical presence. Search dem for clues.\n\nHurry, {name}. Zuldazar will fall if we cannot obtain Bwonsamdi's help!", objectives = "" }
WordHunterWoW_QuestEN[47244] = { title = "A Culling of Souls", description = "Only two types enter Bwonsamdi's temple anymore: those looking to make a deal with death, and de dead. You do not stink, so I guess you are de former.\n\nI am headed to de temple myself, so how about a trade?\n\nSee de land across de bridge? Dere is a witch named Najima dat I have been tracking. De blood trolls are corrupt to de core, but their souls are useful as offerings to Bwonsamdi. She is too strong for me to deal with, but if you can slay her, I will take you to de temple.\n\nI give you my word.", objectives = "" }
WordHunterWoW_QuestEN[47245] = { title = "Getting the Message", description = "Da loa be powerful, but we be needin' soldiers if we gonna have a chance of stopping dem blood trolls from building dat giant of theirs. If we not be able ta destroy dat thing before it be finished, den Zuldazar and all of our people gonna be dead!\n\nWe need da help of da Horde!\n\nWord of da situation already be sent to da warchief. As soon as we be hearin' her reply, we can mov-- \n\nWait... what be dat noise?", objectives = "" }
WordHunterWoW_QuestEN[47246] = { title = "Remnants of the Damned", description = "Ever since da spirits have begun calling upon this \"G'huun\" me temple has been covered with the unbearable taint of the undead. \n\nDa undead be an abomination, but da bloodstones that create them be powerful. They could be of use ta Bwonsamdi.\n\nIf you wish ta show me your fervor, then cleanse me temple of their filth and bring me their bloodstones.", objectives = "" }
WordHunterWoW_QuestEN[47247] = { title = "That Which Haunts the Dead", description = "Bwonsamdi knows why ya be here. Ya be seekin' me favor.\n\n<Bwonsamdi ponders you silently.>\n\nA test, ta see if ya be worth Bwonsamdi's time.\n\nDere be spirits whose prayers sing of something called \"G'huun.\" Dey pay me homage no more. I will not allow da desecration of me own temple!\n\nGo and subdue da strongest of da ancient spirits.\n\nIf ya do dis for me, ya may be worth da trouble after all.", objectives = "" }
WordHunterWoW_QuestEN[47248] = { title = "'Til Death Do Us Part", description = "I don't know who you are, but I need your help.\n\nMy precious Valjabu always told me he didn't care dat he took de vows of a priest... we would be together forever. \n\nWell, my time came to pass, and I knew I'd not be able to go on without him. I came back and have been waiting in dis spot for... it seems forever, and Valjabu never showed!\n\nI've been walking around dis world for far too long.\n\nPlease, I beg you, bring a memento of my Valjabu back to me!", objectives = "" }
WordHunterWoW_QuestEN[47249] = { title = "Soulbound", description = "Ya did well with me tasks. I be thinkin' ya show promise. Ya might be worthy of a deal.\n\nVery well, I pledge ta lend ya me powers ta use against ya foes. In exchange, ya be sendin' one million souls ta Bwonsamdi! No need ta look shocked, ya be plenty capable of doing dis.\n\nCome, meet with me at da Court of Spirits. Dere, we will finalize our agreement.", objectives = "" }
WordHunterWoW_QuestEN[47250] = { title = "We'll Meet Again", description = "Now, it be time for ya ta leave. \n\nDere be many of dem blood troll souls for ya ta be sendin' to da Other Side for Bwonsamdi, and ya not gonna find any more of dem here.", objectives = "" }
WordHunterWoW_QuestEN[47251] = { title = "Interesting Times", description = "{name}, I don't mean to alarm you, but we may be experiencing some... temporal disturbances.\n\nHave you ever heard the phrase 'I hope the past doesn't come back to haunt you?'\n\nCome visit me in the Valley of Spirits and we can speak more.", objectives = "" }
WordHunterWoW_QuestEN[47252] = { title = "Interesting Times", description = "{name}, I don't mean to alarm you, but we may be experiencing some... temporal disturbances.\n\nHave you ever heard the phrase 'I hope the past doesn't come back to haunt you?'\n\nCome visit me in the Stormwind Royal Library and we can speak more.", objectives = "" }
WordHunterWoW_QuestEN[47254] = { title = "The Originals", description = "Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism.\n\nI speak, of course, about Lord Kazzak, Azuregos, and the Dragons of Nightmare.\n\nLegends have it that so sought after were their treasures, that armies would camp overnight to hunt them down.\n\nThe dragons have felt disturbances in the timeways, coincidentally located where these giants once roamed. \n\nThey have tasked me with finding champions to investigate.", objectives = "" }
WordHunterWoW_QuestEN[47257] = { title = "The Bones of Xibala", description = "Far to the south you will find the bones of an ancient creature. This is Xibala, the progenitor, first of the devilsaurs. She was mother to Rezan, mother to all that came after. The Zandalari do not live there, as it belongs to beasts now.\n\nI have heard rumors of some of your Horde arriving in search of something among her bones.\n\nThis is ill advised. Look into it, won't you?", objectives = "" }
WordHunterWoW_QuestEN[47258] = { title = "Prepare for a Siege", description = "It would seem we must make ready for a siege. For now, return to your Horde in Dazar'alor. Prepare for de coming conflict.\n\nShould de forces of Nazmir surge, I will send word.", objectives = "" }
WordHunterWoW_QuestEN[47259] = { title = "Direhorn Daycare", description = "Handler Bazkoji had a real gift with de little ones. If dis hatchling is following you, it must mean Bazkoji is dead.\n\nI don't have time to find another handler. Are you up to de task?\n\nIt's a lot of work, and de little ones get attached real fast. If you're going to care for it, it will be a commitment. That baby will be depending on you. I hope you will be up to de task of feeding and protecting it.\n\nFirst things first: food. Dere is plenty of fodder in de pens and river below.", objectives = "" }
WordHunterWoW_QuestEN[47260] = { title = "Side Effects May Include...", description = "<Your direhorn companion hiccoughs repeatedly. Each time, it either shrinks or grows by a perceptible amount. It whines at you in distress. \n\nYou could use some help.>", objectives = "" }
WordHunterWoW_QuestEN[47261] = { title = "How to Train Your Direhorn", description = "I have to get some of whatever you fed your baby! Wow!\n\nNow dat it's bigger, it is time to teach it to be a reliable battle companion.\n\nLet's see how it does against a tougher challenge, hmm?\n\nTalk to Kraal Master B'khor when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[47262] = { title = "Ending the Blood Trolls", description = "De loa are smiling on us today. De \"matriarch\" of dese blood trolls, a sick monster named Ateena, is up ahead.\n\nWe have a change in plans, {name}. We will end dis threat now. We kill Ateena and de blood trolls will be thrown into chaos.\n\nShe is a powerful hexxer. Go start de fight and I will ambush and catch her off guard.\n\nLet us get moving. We will be back in Zuldazar before de day is over.", objectives = "" }
WordHunterWoW_QuestEN[47263] = { title = "A Time of Revelation", description = "I can feel Ateena's dark voodoo up ahead. We need to stop whatever she is planning with dis \"G'huun\".\n\nBe ready for anything, {name}. We do not know what power Ateena truly has.\n\nI do know one thing. If G'huun is threatening my people, den it will die, just like Ateena.", objectives = "" }
WordHunterWoW_QuestEN[47264] = { title = "Leave None Standing", description = "Now you see what my father refuses to acknowledge. De blood trolls are slaughtering us, and dey need to be stopped.\n\nOur plan is simple, {name}. We will go out dere and kill as many of dese blood trolls as we can. You go east, I go north.\n\nMeet with me after and we will see what is left to do. We will teach dese blood trolls to fear de Zandalari!", objectives = "" }
WordHunterWoW_QuestEN[47272] = { title = "Direhorn Growth Hormone", description = "Nice little critter you got there. Seems a tad too small to be much more than a nuisance though. \n\nWanna help a friend make a profit? There's an abundance of opportunity here, but these trolls won't listen to me!\n\nTell you what, I can make a supplement of sorts that'll make hair grow on your chest! Er, your hatchling's chest! \n\nI know direhorn are vegetarians and all, but there's a reason all the biggest predators eat meat!\n\nRapid growth requires protein. LOTS of protein.\n\nYou interested?", objectives = "" }
WordHunterWoW_QuestEN[47283] = { title = "Chop, Chop!", description = "Throm-ka, {name}.\n\nI'm always looking for someone who thinks they can swing an axe with the best of them.\n\nIf you can remove that sapling without much trouble, I'm sure we can find a better use for your skills.", objectives = "" }
WordHunterWoW_QuestEN[47287] = { title = "The Vindicaar Matrix Core", description = "Much has happened on Argus that concerns me but none moreso than Xe'ra's fate. I wonder sometimes if we are doing the right thing? \n\nBut we must carry on. I can rig the Matrix Core that powers the Vindicaar to allow you to call on the power of our guns when you have need of them on the planet. \n\nGo to the Matrix Core in the room at the heart of our ship. Once linked, whatever powers the core has installed now and in the future will be at your disposal.", objectives = "" }
WordHunterWoW_QuestEN[47289] = { title = "Teddies and Tea", description = "There's nobody to play with here anymore. But you'll play with me, right mister?\n\nIt's time for tea! Help me find the other guests, please!", objectives = "" }
WordHunterWoW_QuestEN[47310] = { title = "Naptime", description = "Your not-so-little guy is looking a bit ragged after such an exciting day. I bet you both need a rest, hm?\n\nCome back later when you're a bit stronger.", objectives = "" }
WordHunterWoW_QuestEN[47311] = { title = "Headbutting 101", description = "Your beast is looking well fed. Good. Try and keep it dat way.\n\nNow, next you need to teach your little one to defend itself. Direhorns in de wild are prey for much larger creatures and de young are easy pickings for saurid and their like.\n\nGo out into de Savagelands and show your little one how to fend dem off.\n\nIt's all in de horn, {name}.", objectives = "" }
WordHunterWoW_QuestEN[47312] = { title = "Queenfeather", description = "Ah, so you are de one who inherited Bazkoji's herd. What is left of it, anyway.\n\nI know what killed him, and I tried to warn him. Queenfeather is a vicious ravasaur, bigger than de rest and smarter as well. Most of de eggs around here are hers.\n\nUsually I praise de strength of such a beast, but she has become a nuisance.\n\nYou will find her guarding her nests in de feeding grounds. Kill her and bring back one of her head feathers as proof dat de deed is done.", objectives = "" }
WordHunterWoW_QuestEN[47313] = { title = "Discreet Discussions", description = "General Jakra'zet cannot be trusted. \n\nHe is up to something, but I do not know what.\n\nAny who question his actions earn demselves a trip to de sands. \n\nAs long as he remains in power, my city will never be safe.\n\nSpeak to his guards. See what you can find out, but be discreet. We do not want to alert Jakra'zet to our actions.", objectives = "" }
WordHunterWoW_QuestEN[47314] = { title = "Rumors of Exile", description = "Talanji sent you, didn't she? \n\nDe princess needs to know dat it is no longer safe to ask such questions so openly. \n\nWarguard Rakera spoke out, and no one has heard from her since. \n\nRumor has it she was exiled to Vol'dun.", objectives = "" }
WordHunterWoW_QuestEN[47315] = { title = "Into the Dunes", description = "Whatever Rakera uncovered, it was important enough to earn her a death sentence to de sands. \n\nWe must head into Vol'dun to find her. \n\nWe cannot let whatever she knows about Jakra'zet die with her in de dunes.", objectives = "" }
WordHunterWoW_QuestEN[47316] = { title = "Secrets in the Sand", description = "I found this journal buried in the sand. \n\nKiro tried to toss it in the fire.\n\n\"Our wagon has no space for a diary, Meerah. What practical use does it have?\"\n\nDon't tell him I said so, but I think it's fascinating! Can you imagine what kinds of secrets it holds? \n\nQuite a few pages are missing, but I bet you can recover them out on the dunes!", objectives = "" }
WordHunterWoW_QuestEN[47317] = { title = "Searching for Survivors", description = "It is good to see you are safe, but what of de others? Have dey been lost to de sands?\n\nYou need to head back to de crash site and see if de others survived.\n\nI will ask around and see if these fox people can tell us anything about Rakera.", objectives = "" }
WordHunterWoW_QuestEN[47319] = { title = "Restorative Venom", description = "Meerah here found your friend in the dunes. The lightning strike nearly killed her. It might still, without treatment. \n\nThe wasps within the grove have a painful sting, but their venom also has restorative properties. \n\nI can extract what I need from their glands.\n\nWith an ample amount of venom, we should be able to soothe your friend's wounds.", objectives = "" }
WordHunterWoW_QuestEN[47320] = { title = "A Balm to Calm", description = "As promised, here is the balm that should remedy your companion's injuries. \n\nApply it liberally to any bits of exposed flesh.\n\nIts effects should be felt immediately.", objectives = "" }
WordHunterWoW_QuestEN[47321] = { title = "Knickknack Takeback", description = "Nisha told me you came here in search of an exile. One named Rakera? \n\nWe don't know her, but we might be able to help you find her. \n\nYou help us, and we help you. Deal?\n\nWe survive by scavenging. We trade what we find, but the sethrak that raided our burrows made away with many of our knickknacks.    \n\nI always knew they were ruthless, but never imagined they'd be so greedy.\n\nTake back what the sethrak have taken, and I'll see that you are provided safe passage through the dunes.", objectives = "" }
WordHunterWoW_QuestEN[47322] = { title = "Aided Escape", description = "The sethrak may be strong, but we're quick. Well, at least Mekaru and I are.\n\nWe just barely made it back to the wagon with our tails attached. \n\nThe others weren't so lucky, I guess. We've been waiting a while, and still no sign of them. \n\nIf you're headed into the thick of it, would you mind looking for our friends?", objectives = "" }
WordHunterWoW_QuestEN[47324] = { title = "Unlikely Allies", description = "I believe this is one of the Keepers' keys! Only Vorrik would know for sure. \n\nWe need to head to the temple at once. \n\nMy pterrordax can take us there when you're ready, but we need to hurry.", objectives = "" }
WordHunterWoW_QuestEN[47327] = { title = "Answering Their Attacks", description = "The sethrak's attacks on our burrows cannot go unanswered. \n\nThey need to learn that not all within the desert will give up so easily. \n\nThe only thing the sethrak understand is blood, so that's the language we'll use to teach them.\n\n<Nisha pauses and looks at you, skeptical that you understood her.>\n\nI'm saying we need to kill the sethrak here. All of them.", objectives = "" }
WordHunterWoW_QuestEN[47329] = { title = "The Bloodwatcher Legacy", description = "Greetings, {name}.\n\nI have been sent on behalf of my father, High Examiner Tae'thelan Bloodwatcher, to oversee the extraction of all fossils, relics, and artifacts from this area.\n\nMy sources inform me that an object that could advance the Horde's cause may be buried beneath this very site.\n\nI will require your help extracting it. You see, these nightborne are not precisely good with their hands. Nor do they enjoy getting dirty.\n\nCould you be a dear and set a good example?", objectives = "" }
WordHunterWoW_QuestEN[47330] = { title = "Whispers of a Frightened World", description = "Champion, Magni needs your help!\n\nThe Speaker has a message for you, perhaps from Azeroth herself. He seems to be having trouble understanding her, but I'm sure he can explain everything better.\n\nHe said he was in Sholazar Basin, in Northrend. He should be contacting you shortly.", objectives = "" }
WordHunterWoW_QuestEN[47332] = { title = "Your Next Move", description = "Princess Talanji plans to travel north to Nazmir. The blood trolls there are a threat she believes her father refuses to acknowledge.\n\nGeneral Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe.\n\nYou will also need to win over King Rastakhan here in Zuldazar. This city is vast and has many secrets.", objectives = "" }
WordHunterWoW_QuestEN[47416] = { title = "Shadow of the Triumvirate", description = "Talgath's words carry more gravity than I think he knew. In an attempt to hurt me one final time, he has given us the answer.\n\nThe Crest of Knowledge is hidden away in the Seat of the Triumvirate, and it is not unguarded.\n\nIf my suspicions are correct, we may be facing a greater threat than any of us dared imagine.\n\nA dark naaru.\n\nLet us return to the Vindicaar. We will plan our next steps there.", objectives = "" }
WordHunterWoW_QuestEN[47418] = { title = "Growing Pains", description = "These trolls are missing a real opportunity here! They complain about not having enough beasts to go around, yet have they really tried to mass produce them? Nope!\n\nWith my Direhorn Growth Hormone, they'll be able to fill these pens to overflowing! Sure, the overcrowding might lead to disease and excess waste issues, but I'm sure those are solvable.\n\nHa ha ha this is gonna be great!", objectives = "" }
WordHunterWoW_QuestEN[47422] = { title = "Dire Situation", description = "Good news, we found de source of de corruption.\n\nDe bad news, it is a ritual on de apex of Zanchul.\n\nBlood magic wielding heretics are empowering some sort of dire troll up dere.\n\nHow it made it all de way to de apex without us catching it is something I am sure Raal and I will be arguing about for de next year.\n\nCome, let us stop dis heresy.", objectives = "" }
WordHunterWoW_QuestEN[47423] = { title = "Forbidden Practices", description = "You come at a good time, {name}. I have need of a weapon such as yourself.\n\nYazma's spies say dere are blood cultists in our ranks. King Rastakhan has charged me with tracking down any trolls guilty of practicing blood magic and purging dem.\n\nTake dis totem, route out those with de stench of blood magic, and cleanse dem from dis holy place.\n\nWhen you are done, tell dat lazy Hexlord Raal to get off his perch and help keep dis place secure.", objectives = "" }
WordHunterWoW_QuestEN[47428] = { title = "Kitty?", description = "You have to find our last guest before it's time for tea!\n\nSmoochums really likes the woods, I bet we'll find him there!", objectives = "" }
WordHunterWoW_QuestEN[47430] = { title = "Moonkin Monitoring", description = "<Makkaw motions for you to observe the other moonkin in the area.>", objectives = "" }
WordHunterWoW_QuestEN[47431] = { title = "Gathering Light", description = "Alleria and I long for more time with our son, but we cannot afford to wait any longer, {name}. We must strike now.\n\nThe Army of the Light is scattered, but not defeated. Any survivors should have stayed near the crash site of the Xenedar. If there is any hope of victory, we must rally them and rescue Xe'ra.\n\nWith the pit lords dealt with, we should have a safer route to the Xenedar. Meet me in the krokul hovel as soon as you can.", objectives = "" }
WordHunterWoW_QuestEN[47432] = { title = "The Bargain is Struck", description = "Now dat you have declared a patron loa for your time here in Zuldazar, you should inform de king of your decision.\n\nHe will appreciate dat you chose to follow de great Pa'ku.", objectives = "" }
WordHunterWoW_QuestEN[47433] = { title = "Offensively Defensive", description = "Let me guess, Loti had you kill any trolls dat smelled of blood magic, yes? Well, dat is barely a half measure.\n\nSee, blood magic comes from de old ways, and our people have only been giving in to its allure since de walls fell on our northern border.\n\nCome, we will go for a little ride and patrol de border to Nazmir. Dat is where all dese bad ideas are coming from.", objectives = "" }
WordHunterWoW_QuestEN[47434] = { title = "Restraining Order", description = "\"Something feels different\"? Dat was all Raal said?\n\nHis flock of pterrordaxes have swarmed de courtyard of Zanchul. Dey are being driven mad.\n\nShoo dem away before dey hurt demselves or others.", objectives = "" }
WordHunterWoW_QuestEN[47435] = { title = "Pterrortorial Dispute", description = "De courtyard of Zanchul has been overrun by pterrordaxes driven mad by some dark ritual. Power is coalescing here, and it is hard to tell who or what is causing it.\n\nI need to track down de source. In de meantime, you take dis, de power of Gonk, and call his allies to help you in battle. Slay dese maddened pterrordaxes.\n\nWhen you are done, tell Raal to get his flock under control.", objectives = "" }
WordHunterWoW_QuestEN[47437] = { title = "Competitive Devotion", description = "Okay, I know dis situation is serious, but she gave you de power of her loa? Sounds to me like Loti is more big on recruiting than on dealing with dis blood troll threat.\n\nInside de temple behind me are three guardians. When I walked in dere, de things tried to kill me. Me!\n\nSomeone has corrupted our own guardians.\n\nHere, I will lend you de voice of my own loa, Pa'ku, de pterrordax. Use it to crush dis corruption.", objectives = "" }
WordHunterWoW_QuestEN[47438] = { title = "Picking a Side", description = "Look, dis has gone on long enough, {name}. I am not one to hold a grudge, but I will be damned if I let you double dip with Raal's loa and my own.\n\nTime has come to pick a loa. De loa are not de sharing type.", objectives = "" }
WordHunterWoW_QuestEN[47439] = { title = "Gonk, Lord of the Pack", description = "You can find Gonk in his lair west of here, in de Garden of the Loa.\n\nYou should be able to see his totems. Run near dem to improve your speed.\n\nI will continue to purge de heretics from dis temple.\n\nMind your manners around de loa, or he may rip your throat out.", objectives = "" }
WordHunterWoW_QuestEN[47440] = { title = "Pa'ku, Master of Winds", description = "Come, ride Ata de Winglord with me, and he will take us to Pa'ku.\n\nOh, and mind your manners around dat loa. Pa'ku has been known to drop followers she is not fond of from a really great height onto really hard stone.", objectives = "" }
WordHunterWoW_QuestEN[47441] = { title = "Pests", description = "Let me guess, de saurid stole something of yours as well, eh? Look, I don't have de time to run down every little thing dese ankle-biters snap off with.\n\nYou want some coin? Help me kill some of dese snappers.\n\nOtherwise, leave me be.", objectives = "" }
WordHunterWoW_QuestEN[47442] = { title = "Curse of Jani", description = "Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets.\n\nYa be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn.\n\nI tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.", objectives = "" }
WordHunterWoW_QuestEN[47445] = { title = "The Zanchuli Council", description = "You there, Speaker of de Horde.\n\nMy spies have told me of dark heresies being practiced in our sacred temple of Zanchul.\n\nDe king sent Loti and Raal to deal with de situation, but those two bickering council members are soft on their own followers.\n\nWe need someone more... ruthlessly neutral.\n\nGo meet Wardruid Loti down at de Zocalo and she can tell you de rest.", objectives = "" }
WordHunterWoW_QuestEN[47473] = { title = "Sizing Up The Opposition", description = "Turalyon was no doubt hoping for better news, but I fear I cannot provide it. Attempting to drive into the heart of the Legion now would cost us everything.\n\nThere must be another way. I do not know what it is, but I trust that we will find it.\n\nBest not keep Turalyon waiting. We must move forward.", objectives = "" }
WordHunterWoW_QuestEN[47485] = { title = "The Ashvane Trading Company", description = "So, Ashvane's goons are walking around with a new powder that can blow a galleon clean in half and the military has no idea.\n\nWe need to find out how much of this powder they have and where it's going.\n\nAn old buddy of mine works the ferry down by the Ashvane Foundry. He may know something about this.\n\nYou can take the ferry from Tradewinds Market to Eastpoint Station. Once you get there, look for a man named Cagney. Tell him I sent you. He owes me a favor.", objectives = "" }
WordHunterWoW_QuestEN[47486] = { title = "Suspicious Shipments", description = "Normally I wouldn't tell you nothin'... but I'll spill it for Cyrus.\n\nAshvane's onto somethin' big.\n\nThey got guys workin' round the clock in there. Even brought in some muscle to keep everyone uh... \"motivated.\"\n\nI don't know anything about what they're makin', but I know it ain't passin' through here to Boralus.\n\nIf I were dumb enough to go snooping around in there, I'd look at the goods themselves. See if they got shipping labels.\n\nBut I ain't that dumb, so you gotta do it.", objectives = "" }
WordHunterWoW_QuestEN[47487] = { title = "Labor Dispute", description = "The Ashvane Company has been workin' their people so hard they even tried to strike! \n\nThe company brought in a bunch of goons to break it up and get everyone back to work. \n\nHeard they even shot a couple guys who tried to walk off the job.\n\nWhat say you give 'em a taste of their own brutality while you're in there?", objectives = "" }
WordHunterWoW_QuestEN[47488] = { title = "Small Haulers", description = "<sniff>\n\nThey said they would feed us. Said they'd keep us warm.\n\n<Olive runs the sleeve of her coat across her nose.>\n\nBut they were mean! And it was really hard work. And when we tried to rest, they yelled at us!\n\n<sniff>\n\nI got away, but my friends are still in there.", objectives = "" }
WordHunterWoW_QuestEN[47489] = { title = "Stow and Go", description = "<Flynn lifts his collar to hide his face and speaks to you under his breath.>\n\nYou see that ship? I know that ship.\n\nLet's just say her captain and I have a little history.\n\nIt's a smuggling vessel. Our illegal weapons are on there for sure. I'd bet my coat on it... and I love this coat.\n\nWe need to find out where it's going...\n\nHow are you in tight spaces?", objectives = "" }
WordHunterWoW_QuestEN[47491] = { title = "Remnants of the Damned", description = "Ever since da spirits have begun calling upon dis \"G'huun,\" me temple has been covered with da unbearable taint of da undead. \n\nDa undead be an abomination, but da bloodstones dat create dem be powerful. Dey could be of use ta Bwonsamdi.\n\nIf ya wish ta show me ya fervor, den cleanse me temple of their filth and bring me their bloodstones.", objectives = "" }
WordHunterWoW_QuestEN[47493] = { title = "A Lonely Spirit", description = "Da spirit of a child named Keula be wanderin' me temple grounds. Her ma'da gave her child up ta me long ago, she be thinkin' that a great sacrifice would spare her from me call, from going to da other side.\n\nWell she be right, I not claim her yet. But she be wrong too. Her child be da one to decide when ta be reunited with her ma'da, and it seem ta me dat da child be no longer be content ta wait.\n\nDey both belong in my realm.\n\nGo, bring da child to her ma'da.", objectives = "" }
WordHunterWoW_QuestEN[47497] = { title = "Meet the Goldtusk Gang", description = "Greetings, traveler, and welcome to de Goldtusk Inn!\n\nUnless you're here to kill us... In which case, get out.\n\nOtherwise, sit down and enjoy de mess!\n\nI mean, don't mind de mess. EAT DE MESS! No, don't eat de mess. Ignore it!\n\n<Rhan'ka turns to the skull with the eyepatch and shouts furiously in Zandalari.>\n\nHa, don't mind him. All exiles are welcome to rest at de Goldtusk Inn, de only luxury lodge in dese harsh dunes.\n\nCome, let me introduce you to de staff.", objectives = "" }
WordHunterWoW_QuestEN[47498] = { title = "Rhan'ka's Lost Friend", description = "When you head up to Dead Man's Pass, be sure to say hello to Zulsan.\n\nHe's my best friend, even if he doesn't want to be near me most of de time. Ha!\n\nSeriously, though, he's been up on de cliffs for days. If you find him, convince him to come back down to de inn. We need him to restock our breakfast buffet.\n\nOh, and a completely unrelated question dat has nothing to do with you not being able to find Zulsan and my needing to replace him: How wide is ya head?", objectives = "" }
WordHunterWoW_QuestEN[47499] = { title = "The Grinning Idols", description = "Before de curse, we were a loyal crew to a good captain. But de curse corrupted Pirate-King Zem'lan, made him cruel and controlling.\n\nNow, he treats us more like slaves than crewmates. Forced to fight and die for his gain, no treasure for ourselves. No speakin' up without punishment.\n\nWell, us four, we ain't gonna be his slaves no more.\n\nA few of de crew hold onto de idols dat Zem'lan used to curse us. Kill dem and take de idols. I wanna see if we can break dem. Just for fun.", objectives = "" }
WordHunterWoW_QuestEN[47501] = { title = "Dirty Work for Dirty Drinks", description = "Guests gotta earn their keep at de Goldtusk Inn. What say you help me clear out some scorpids at one of our off-site excursion locations? De delightful Dead Man's Pass!\n\nNormally, you'd need to purchase our Warlord Package to be allowed access, but I'll make an exception dis time.\n\nI'll even throw in our Scorpid King Package. Unlimited scorpid blood drinks all day, every day!\n\nDere's one catch: we're out of scorpid blood. Bring some back and I'll whip up a batch of drinks for us.", objectives = "" }
WordHunterWoW_QuestEN[47502] = { title = "The Great Cranium Caper", description = "Sandfury thugs attacked de inn after you left and kidnapped de whole Goldtusk Gang!\n\nWe gotta get dem back.\n\nMan'zul was usually de brains behind our thefts back in Zuldazar, but I'll try to come up with a plan to get dem outta dis mess.\n\n<Rhan'ka thinks for awhile.>\n\nI got it! You rescue 'em all!", objectives = "" }
WordHunterWoW_QuestEN[47503] = { title = "Gozda'kun the Slaver", description = "Dat's it. De Sandfury are officially banned from de Goldtusk Inn!\n\nYou can't just ransack a place, kidnap its staff, and mock its owner with an assortment of fruits and vegetables and expect to get away with it!\n\nWe gotta teach those thugs what happens when you mess with de Goldtusk Gang!\n\nGozda'kun de Slaver was bossing around de rest of de Sandfury during de attack.\n\nTake him out, and leave some Sandfury behind to spread de word.", objectives = "" }
WordHunterWoW_QuestEN[47506] = { title = "REUSE", description = "", objectives = "" }
WordHunterWoW_QuestEN[47508] = { title = "Fire At Will", description = "Look out there, the wings of the bats fill the sky. We must offer what ranged support we can, but our hands are full here.\n\nIt looks like the Legion has not yet destroyed all of the artillery batteries. If you can get to one, you should be able to show those flying fiends the Light.", objectives = "" }
WordHunterWoW_QuestEN[47509] = { title = "Terrace of the Chosen", description = "This betrayal has cut deep into the heart of Zandalar. Half of the Zanchuli Council and their followers have sided with Zul and his... blood god.\n\nLucky for us not all of Zandalar is behind this betrayal.\n\nWe need to topple Zul's cultists before they can rally too many to their cause. Zanchul is the place to start.\n\nGo and see if you can muster any of the Zandalari still loyal to their king.", objectives = "" }
WordHunterWoW_QuestEN[47512] = { title = "Nazmir", description = "The blood trolls within the cursed swamp Nazmir threaten to destroy all of Zuldazar. \n\nPrincess Talanji wants the Horde's help in an expedition to strike at the heart of the blood trolls and end their threat to Zuldazar.", objectives = "" }
WordHunterWoW_QuestEN[47513] = { title = "Vol'dun", description = "General Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe.\n\nWe are not alone in our suspicions. Speak to Princess Talanji to follow up.", objectives = "" }
WordHunterWoW_QuestEN[47514] = { title = "Zuldazar", description = "King Rastakhan is an ancient ruler who is not quick to trust new allies. We must earn his trust if we are to earn his fleet.\n\nZuldazar is the seat of power for the Zandalar empire and a good place to start in winning over these potential allies.", objectives = "" }
WordHunterWoW_QuestEN[47518] = { title = "Raal", description = "Crazzak is a traitor in priest's clothing who thinks if he tortures enough of us it will hurt our loa.\n\nDey even have my husband Raal up on de apex of Zanchul. Normally I would say dey could have him, but dey are using his connection to Pa'ku to weaken de loa.\n\nCan't have dat. Let's get to de top of Zanchul and rescue my worthless husband.", objectives = "" }
WordHunterWoW_QuestEN[47520] = { title = "Walls Have Ears", description = "Yazma, mistress of spies.\n\nBah! A traitor who is into creepy crawlies. She chose to side with Zul, and she uses de children of her loa, Shadra, to watch and track everything we do.\n\nWe have to kill all de spiders we see, or dat traitor Yazma will know every move we make.", objectives = "" }
WordHunterWoW_QuestEN[47521] = { title = "Midnight in the Garden of the Loa", description = "Yazma and her henchtroll Vol'kaal have pulled most of their forces back to de Garden of de Loa. \n\nSomething bad is afoot, I can feel it in my spirit. Pa'ku is in danger, along with all de loa who have followers dere.\n\nCome, let's fly dere and put an end to dese heresies.", objectives = "" }
WordHunterWoW_QuestEN[47522] = { title = "The Hunter", description = "Gonk is in danger. I can hear his call.\n\nMy loa has saved my life so many times, it is about time I return de favor.\n\nCome, join me at de Lair of Gonk on de west side of de Garden of the Loa, and we will save a god.", objectives = "" }
WordHunterWoW_QuestEN[47523] = { title = "Disturbance Detected: Black Temple", description = "{name}, right on time, as always.\n\nGood news first, because they're happening at the same time for me anyway. Thanks to the various timewarped objects past and future you discovered, we've figured out how to detect when a new one turns up.  \n\nThe bad news is, we know our technique works because something has changed in the Black Temple, and it's wreaking havoc across the timescape! We need you to ensure the fateful raid turns out exactly like it did before, and to remove the source of this disturbance.", objectives = "" }
WordHunterWoW_QuestEN[47525] = { title = "Staying Hidden", description = "Dere be trouble brewin', mon. Da blood trolls be on da move! Dey set up a large camp nearby and have been sending a small force to da isle south of here. \n\nIf dey discover our position while we be havin' no defenses, it gonna be game over! We need ta see what dey be up to and get rid of dem.\n\nOur best bet be ta investigate da isle south a here. Ya want ta join me? I be ready ta head out.", objectives = "" }
WordHunterWoW_QuestEN[47526] = { title = "Bringing the Big Guns", description = "Light's Judgment has a security feature to prevent it from falling into enemy hands. We can trigger its recall mechanism, which will teleport it back to a vessel.\n\nWith the Xenedar out of commission, the gun should recall to your ship instead. You can make good use of its firepower.\n\nThe process takes time, though, and will likely attract the Legion's attention. Be on your guard.", objectives = "" }
WordHunterWoW_QuestEN[47528] = { title = "Mistress of Lies", description = "If you are done dealing with dese peasant loa, den perhaps you can help with my own loa: Shadra.\n\nMy \"high\" priestess, Yazma, is behind all of dis. If she is having her minions slay other loa, den I can only guess she is also trying to sacrifice my own loa as well.\n\nShadra's shrine is on de northwest side of de Garden of the Loa. You must stop her from slaying de Mistress of Spies.", objectives = "" }
WordHunterWoW_QuestEN[47529] = { title = "Supernatural Support", description = "The loa can bestow powerful boon's to their followers, aid that can be the difference between victory or defeat in our efforts here.\n\nThink carefully which of the two you would like to ask for their blessing. The loa will not give their assistance to those who are currently pledged to another loa.", objectives = "" }
WordHunterWoW_QuestEN[47540] = { title = "Totemic Restoration", description = "I am fed and my body is prepared. I can now be instilled with my power of old and for a time will be immune to their blood curses and leeching powers.\n\nUse the magic of the glowflies to channel my power from the totems into me.\nSoon you will see me restored. Then we will destroy the army that prepares across the river to take all that is mine by force.", objectives = "" }
WordHunterWoW_QuestEN[47541] = { title = "The Best Prevention", description = "If you've brought the High Exarch back to us, you are a welcome ally indeed.\n\nMore is needed of you. You see our soldiers out there, fighting against all odds? Defend them. Slay the enemy.\n\nStrong words for a priest, perhaps, but every dead man'ari is one less blade at our throats.\n\nShow them that the Light protects its chosen even as it scorches the unfaithful.\n\nWhen you are finished, seek out Y'mera. She will have fewer troops, and more need of your abilities.", objectives = "" }
WordHunterWoW_QuestEN[47543] = { title = "The Day That Chromie Dies", description = "Oh, {name}! I was just thinking about you! Talk about being at the right time in the right place!\n\nI was just reviewing some aberrations in the timeways, when I discovered something... unexpected. Something not-so-great.\n\nI'm going to die in the near future. Bad times.\n\nI was just about to jump ahead and see if I can figure out why, how, who... but I'd feel better with a {race} like you by my side. Care to join me?", objectives = "" }
WordHunterWoW_QuestEN[47545] = { title = "Rewind", description = "Now we know when the attack happens, and vaguely where it's coming from. Progress! All we need to do now is to find out more details and stop that attack!\n\nLet me know when you're ready to try again.", objectives = "" }
WordHunterWoW_QuestEN[47550] = { title = "The Many Advantages of Being a Time Dragon", description = "Well, unfortunately for... whomever is fixated on blasting me into oblivion, I am a fairly skilled master of the timeways! We have the advantage of trying that again, and again, and again, until I'm not dead anymore.\n\nWe're going to need a little more than a few seconds to stop this attack. How does four hours sound?", objectives = "" }
WordHunterWoW_QuestEN[47554] = { title = "Intercepting the Legion's Plans", description = "Our scout Skara writes in the missive that she learned of a major Legion initiative. She was after two encoded orders held by Legion troops near us to get the details and this must be when she was killed. The Legion splits their messages into encoded parts so that we cannot read them. \n\nSkara also writes that her partner Brae, a codebreaker, was slain trying to reach our lines with a code book that we will need to translate the Legion's orders. It is vital you find the orders and that code book!", objectives = "" }
WordHunterWoW_QuestEN[47557] = { title = "Smoldering Chronoshard", description = "This shard of crystal is hot to the touch. The void creature that carried it wasn't a wielder of flame in any noticeable way, so perhaps the chronoshard is related to fire in some other way.", objectives = "" }
WordHunterWoW_QuestEN[47558] = { title = "Fel-Touched Chronoshard", description = "This shard of crystal is scarred with deep rivets of green, malevolent energy. Being held by a dreadlord will do that to you.", objectives = "" }
WordHunterWoW_QuestEN[47559] = { title = "Gleaming Chronoshard", description = "This shard of crystal glitters with a metallic sheen. Based on Chromie's reaction, it may be used to connect you to another time and place.", objectives = "" }
WordHunterWoW_QuestEN[47560] = { title = "Frozen Chronoshard", description = "This shard of crystal is encased in a thin, frigid layer of permafrost. It still has that distinctive lich smell to it.", objectives = "" }
WordHunterWoW_QuestEN[47564] = { title = "Restocking the Buffet", description = "Imagine for a moment, {name}. You wake up in de Goldtusk Inn after a long day of drinking scorpid blood, slaughtering Sandfury, and sharing jokes with your best friend Zulsan.\n\nYa not fully awake yet, and not feeling ya best. What do you need most at dat exact moment?\n\nAn all-you-can-eat breakfast buffet, of course!\n\nI'm working on it, but I need some fruit to balance out my menu. Luckily, I've seen some in de oasis outside.\n\nBring me some, and I'll give you lifetime access to de buffet.", objectives = "" }
WordHunterWoW_QuestEN[47570] = { title = "Hidden Motives", description = "I do not understand why the naga would bother attacking a small fishing village.\n\nWhy waste their time on our simple tribe? The naga seek power and we have none. It makes no sense!\n\nThey must be after something else entirely...\n\nSearch Darkwood Shoal and learn of their plans. Whatever the naga are after, it must be quite powerful.\n\nPerhaps if we find it first, we can use it against them!", objectives = "" }
WordHunterWoW_QuestEN[47571] = { title = "The Elder's Wisdom", description = "The naga are searching for a powerful artifact called the Ring of Tides.\n\nAccording to the invasion plans, the ring was lost long ago in a battle with Eraka no Kimbul, the great tiger loa.\n\nThe temple of Eraka no Kimbul is just to the north. If the loa was strong enough to defeat the naga before, maybe he can do it again!\n\nWe must let the tribe know what we've found!\n\nTake the invasion plans to Elder Kuppaka. He is the oldest, and wisest member of our tribe. He will know what to do.", objectives = "" }
WordHunterWoW_QuestEN[47573] = { title = "Jungleweb Infestation", description = "The walls of the temple could provide us with vital protection against the naga, but the temple is overrun with jungle spiders.\n\nWe'll need to clear out the infestation before the tribe can take refuge at the temple.\n\nVenture into the lower ruins and lay waste to the spiders that have nested there.", objectives = "" }
WordHunterWoW_QuestEN[47574] = { title = "All Webbed Up", description = "The lower ruins of the temple are covered in thick webs and spider egg sacs.\n\nSome of our tribesman went down to the lower ruins to clear out the spiders, but they haven't come back.\n\nI fear for their safety.\n\nPlease head into the lower ruins and free our brethren before it's too late.", objectives = "" }
WordHunterWoW_QuestEN[47576] = { title = "Wrath of the Tiger", description = "The Tortaka shall have my protection. Even as we speak, an army of the naga have risen from the depths to attack my temple.\n\nHow soon the naga have forgotten their previous defeat!\n\nThey seek to reclaim the Ring of Tides, a powerful artifact that I took as my trophy when I killed Azshara's previous champion, Mepjila.\n\nI will send you to the battlefield as my avatar to rain destruction upon the naga. They have forgotten what happens to those who trespass against my followers.\n\nRemind them.", objectives = "" }
WordHunterWoW_QuestEN[47577] = { title = "They Came From The Sea", description = "You are free to rest your weary legs in our camp, but I'm afraid we have little more to offer you.\n\nNaga have driven us from our village by the sea. We can no longer fish or hunt crabs. I fear we may not survive long if we cannot take back our lagoon.\n\nBut taking back the lagoon will not be enough. We must find out why the naga attacked us. What is it they are looking for?\n\nTake this ancient scroll and use it summon the spirits of the naga.\n\nThey will only speak truth while under its spell.", objectives = "" }
WordHunterWoW_QuestEN[47578] = { title = "Mark of the Loa", description = "You have proven worthy of my blessing, {name}.\n\nThis means should you choose me as your loa, you can call upon my power when needed.\n\nCommune at my shrine and make your decision. \n\nKnow that whatever you choose, you will always be welcome within these walls.", objectives = "" }
WordHunterWoW_QuestEN[47580] = { title = "The Curse of Mepjila", description = "Centuries ago, the sea witch Mepjila attacked my temple with an army of naga invaders.\n\nMy followers fought bravely, but I arrived too late to save them.\n\nI defeated the naga army with ease. But as I closed my jaws around Mepjila, she placed a curse upon the spirits of my followers, locking them in an eternal battle they can never win.\n\nThis mask will give you the power to enter the spirit realm and end their nightmare.\n\nDefeat the spirit of Mepjila and the curse will be broken.", objectives = "" }
WordHunterWoW_QuestEN[47581] = { title = "Blessing of Kimbul", description = "The entrance to the temple is sealed by a magical barrier.\n\nAccording to my scrolls, the barrier can only be lowered by one who has gained the Ring of Tides.\n\nThere is a statue somewhere in the temple grounds with the power to bestow the ring, but the ruins are overrun with jungle spiders. Tulu and I are not strong enough to explore the lower ruins ourselves.\n\nIf you can gain the Ring of Tides and enter the temple, we may finally be able to face the naga head on!", objectives = "" }
WordHunterWoW_QuestEN[47583] = { title = "Die, Die, Diemetradon", description = "We are competing, you and I and these other savages.\n\nI find this... amusing.\n\nSouth of here you will find a number of diemetradons. I challenge you, {class}, to slay more of these creatures than I.\n\nDo you accept my wager?", objectives = "" }
WordHunterWoW_QuestEN[47584] = { title = "A Thorn in the Side", description = "You fools speak of \"big game\" hunting like it is a thing of wonder. Bah! \n\nNone know big game hunting like my kin. Mastery of the hunt, passed down from parent to child, for generations. \n\nI am here to prove it.\n\nI wager that you could not slay more than eleven of the ankylodon beasts that wander this region.", objectives = "" }
WordHunterWoW_QuestEN[47585] = { title = "Predatory", description = "<There is a wound in his back, possibly from a knife.\n\nIt seems more than the wildlife is fighting back out here.>", objectives = "" }
WordHunterWoW_QuestEN[47586] = { title = "Hunting the Hunter", description = "Your hunter king, Nesingwary, is a mighty fine bit of prey here. I even thought of hunting him myself.\n\nBut someone else is on his trail now. And dat hunter, he is a dangerous one.\n\nIf you wish to save your hunter king, you best start tracking quickly. If he made camp, you may be too late already. You cannot paint a target and wonder why you were shot!\n\nI believe he was last seen heading west...", objectives = "" }
WordHunterWoW_QuestEN[47587] = { title = "Headhunter Jo", description = "He said he's hunting you. I'm not the prey, I'm the bait!\n\nBehind ye!", objectives = "" }
WordHunterWoW_QuestEN[47588] = { title = "King of the Hunt", description = "", objectives = "" }
WordHunterWoW_QuestEN[47589] = { title = "Righteous Fury", description = "The devastators bombarding our forces prevent us from advancing any further. I can only protect us from their blasts for so long.\n\nChampion, you must pierce their lines and remove the barriers protecting the devastators.\n\nIf you can destroy the anchors that maintain the shields, I can cleanse them from afar.", objectives = "" }
WordHunterWoW_QuestEN[47591] = { title = "Wanna Buy a Lamp?", description = "Ey dere, wanna buy a lamp? You be not regrettin' it.", objectives = "" }
WordHunterWoW_QuestEN[47592] = { title = "Shine Bright Like a Diamond", description = "Oh, I be sorry. Dat lamp look like it could use some shinin'. I happen to have just da ting.", objectives = "" }
WordHunterWoW_QuestEN[47593] = { title = "Magical Coins, You Say?", description = "", objectives = "" }
WordHunterWoW_QuestEN[47594] = { title = "I'll Take Those, Thanks!", description = "These coins, dey be vanishin' inta air ya say? Dat be soundin' perfect, as I have jus the fella ta give dem to.", objectives = "" }
WordHunterWoW_QuestEN[47596] = { title = "There Is No Plan \"B\"", description = "Look, I'll be honest with you. Our mech, the A.M.O.D., was the best we've ever made. It was mobile. It was powerful. It was one of a kind! \n\nWhat I'm trying to say is, without it, our whole plan is ruined! We have to salvage and rebuild it!\n\nThat big oaf of a sea giant broke the A.M.O.D. apart and scattered its pieces all over the shore. Find its parts and I'll try to hammer them back together.", objectives = "" }
WordHunterWoW_QuestEN[47597] = { title = "No Goblin Left Behind", description = "Our mission is dead in the water unless we move fast!\n\nI've found the perfect spot for a new base. While I secure the location, I need you to rescue the team and bring them back. We've trained for this a million times. Just direct them toward the rendezvous point and they'll find the way.\n\nWe don't have much time, let's go!", objectives = "" }
WordHunterWoW_QuestEN[47598] = { title = "Pilfering and Fencing", description = "Our ships are sunk. Our A.M.O.D.'s gone. We've lost a LOT on this mission... and the Bilgewater Cartel don't offer insurance. The debt collectors will be all over us! We gotta make up for these losses. \n\nThe beach is swarmin' with naga tryin' to collect artifacts from the ruins. How 'bout we grab some of that treasure and make back our money? I'm sure we could find a buyer willing to take 'em off our hands. \n\nWe'll split the proceeds 80/20. Sounds fair to me.", objectives = "" }
WordHunterWoW_QuestEN[47599] = { title = "Revenge: Served Hot", description = "Look, the boss might be keeping a level head here, but we should show these naga what happens when you mess with the Gob Squad. Don't you agree?\n\nThe naga are sending their behemoths to destroy what's left of our ship. Why don't you take my rocket launcher and make an example out of them. That'll send the message loud and clear!", objectives = "" }
WordHunterWoW_QuestEN[47601] = { title = "Field Evaluation", description = "We got the A.M.O.D. back together. It's a fine piece of equipment, but we're gonna have to give it a tune up. We don't want to end up digging shrapnel out of our rears.\n\nLucky for us, there are a few naga camps remaining along with the giant that broke the gun in the first place. They'll be great for target practice.\n\nWe'll deploy the A.M.O.D. just outside the building here. After we deploy, go man it. I'll have you fire a few rounds while I tune its gun.\n\nEverything'll be fine... unless it isn't.", objectives = "" }
WordHunterWoW_QuestEN[47602] = { title = "Ready For Action", description = "It's gonna take a bit to get the gun chassis set up. Who knew lifting big equipment could be so hard?\n\nIn the meantime, why don't you go check back with your friends. Make sure everything's ready on their end. I'd hate to drive this gun into ANOTHER ambush because they're not ready.", objectives = "" }
WordHunterWoW_QuestEN[47603] = { title = "The Mysterious, Magnificent Al'Abas", description = "I see you, puny mortal! I appreciate your concern for my lamp!", objectives = "" }
WordHunterWoW_QuestEN[47604] = { title = "In the Land of Magic", description = "I think I see the problem. Your puny eyes are too weak to detect the mana-infused finery that these elves have spread throughout the land. They've been wearing jewelry the entire time, and you simply couldn't see it.\n\nI propose a partnership, my newly minted associate. My lamp currently suffers from an embarrassing lack of magic and could always use more beautiful decorations. I propose a trade. I shall pierce this sinister veil, and you shall give me the spoils of your theft.", objectives = "" }
WordHunterWoW_QuestEN[47605] = { title = "Coins of Air", description = "I would be much interested in these magical trinkets that reside in the pockets of the denizens of this land, and humbly offer my services in helping you acquire them, {name}. \n\nHowever, I sadly cannot pay you in the coin of this realm. What I can offer are ephemera - coins of purest air. They're better than nothing, though!\n\nCarry my lamp with you. Drop the treasures you steal within, and I will grant you these coins. Perhaps the former owner of my lamp would have a use for them.", objectives = "" }
WordHunterWoW_QuestEN[47606] = { title = "Loyalty Is Its Own Reward", description = "I offer you a challenge, mortal. Obtain a thousand of my coins, and I believe that I can empower my lamp and the vision within.", objectives = "" }
WordHunterWoW_QuestEN[47607] = { title = "High Fash-Djinn", description = "With my newly empowered lamp, I sense further, more valuable trinkets in the pockets of these elves and demons. Fetch them for me!", objectives = "" }
WordHunterWoW_QuestEN[47608] = { title = "I Wish You Could See It", description = "", objectives = "" }
WordHunterWoW_QuestEN[47621] = { title = "A True Loa Feast", description = "The blood troll attacks have not stopped until now. They have weakened me significantly and I need to get my strength back. My followers used to bring me offerings of meat from the nearby lands.\n\nGo and bring back a mighty feast. My strength will return and we will stop these attacks once and for all.", objectives = "" }
WordHunterWoW_QuestEN[47622] = { title = "A Magical Glow", description = "Long ago when the trolls began listening to the whispering darkness, I instilled portions of my power into the totems that surround my lair. I need that power now.\n\nIn the swamps north of here are glowflies. Their magical essence will aid me in drawing the stored power from the totems. Collect them and return. Then you will see what I was capable of at the height of my strength.", objectives = "" }
WordHunterWoW_QuestEN[47623] = { title = "The Last Witch Doctor of Krag'wa", description = "I am Krag'wa, the once mighty. Curse the blood trolls and their dark god! They have slain my worshippers until only Zentimo remained, and now even he is gone.\n\nI want revenge on the blood trolls, but first I must honor the last of my witch doctors. As I have no others, I must request you perform the ritual.\n\nThen we can talk of revenge.", objectives = "" }
WordHunterWoW_QuestEN[47627] = { title = "Vengeance", description = "The Army of the Light will not have fallen in vain.\n\nOur forces will assault the main encampment while we destroy their siege weapon.\n\nThis will be but the beginning of our vengeance.", objectives = "" }
WordHunterWoW_QuestEN[47631] = { title = "Rendezvous with the Libation", description = "I be honest wit' ya, mon. I be havin' little patience for goblins and their antics.\n\nGo meet with their leader and ensure dat his crew and da weapon be ready for da assault. Zuldazar gonna be overrun by da blood trolls if we fail.\n\nGood luck, {name}!", objectives = "" }
WordHunterWoW_QuestEN[47638] = { title = "Powerful Spirits", description = "You prove your worth, {name}. We be willin' to initiate you into de ranks of de Goldtusk Gang, if you wanna join.\n\nDe ritual drink is ready. Boiled scorpid blood spiked with bilewing honey!\n\nDon't mind de smell, it's mostly delicious. It's not terrible. It won't kill you. Usually.\n\nWhen you are ready to join de Goldtusk Gang, let me know. I'll unite you with de whole gang. It's time you see what we see.", objectives = "" }
WordHunterWoW_QuestEN[47641] = { title = "Signs of Resistance", description = "Our forces sustained heavy losses defending the Vindicaar, {name}. We require allies.\n\nThe Army of the Light was known to take in survivors of the Legion's crusade to bolster their ranks. We must do the same.\n\nI sense the presence of the Legion slaves you freed nearby. I suspect that they have carved out a resistance against their masters.\n\nI would appreciate your company, {name}.", objectives = "" }
WordHunterWoW_QuestEN[47642] = { title = "Soul Crystal", description = "<The three shards combine neatly into a large crystal. Once reassembled, the image of a powerful lich appears above the crystal's surface.>\n\n<The lich speaks:>\n\nKeep the Ruby Shrinewardens occupied. I shall carry out our master's attack from within the great tree itself.", objectives = "" }
WordHunterWoW_QuestEN[47643] = { title = "The Ancients' Wisdom", description = "The three ancients left three clues:\n\n\"...the great nightmare...\"\n\n\"...by the water...\"\n\n\"...within the dragon's palm...\"\n\nPerhaps Chromie's attacker lies in the place the ancients describe?", objectives = "" }
WordHunterWoW_QuestEN[47644] = { title = "Demonic Corestone", description = "<Deep within the demonic corestone, the image of a dreadlord speaks ominously:>\n\nYes, master. It shall be done, at the exact time that you specified. The bronze dragon will see nothing. One shot from outside the Obsidian Dragonshrine is all I require.", objectives = "" }
WordHunterWoW_QuestEN[47645] = { title = "Voidcallers' Scroll", description = "<The scroll pieces combine to form a tattered, but readable message:>\n\nThe time is nigh. The invocation will take place above the azure shrine. The void will swallow the bronze dragon. Our master has spoken, and we obey.", objectives = "" }
